module mem_arb (
    input  wire        clk,
    input  wire        rst,
    input  wire        req0,
    input  wire        req1,
    input  wire        req2,
    input  wire        req3,
    input  wire [1:0]  kind0,
    input  wire [1:0]  kind1,
    input  wire [1:0]  kind2,
    input  wire [1:0]  kind3,
    input  wire        is_ram,
    input  wire        c_store,
    input  wire        c_amo,
    input  wire        c_dmem_we,
    input  wire        eng_ready,
    input  wire        eng_done,
    output reg         sel0,
    output reg         sel1,
    output reg         sel2,
    output reg         sel3,
    output reg         bsel0,
    output reg         bsel1,
    output reg         bsel2,
    output reg         bsel3,
    output reg         grant0,
    output reg         grant1,
    output reg         grant2,
    output reg         grant3,
    output reg         eng_start,
    output reg         eng_we,
    output reg         eng_line,
    output reg [1:0]   eng_src,
    output reg         rdone,
    output reg         wdone
);

    localparam S_IDLE                 = 3'd0,
               S_READ_WAIT            = 3'd1,
               S_WRITE_WAIT           = 3'd2,
               S_ATOMIC_READ_WAIT     = 3'd3,
               S_ATOMIC_DECIDE        = 3'd4,
               S_ATOMIC_WRITE_WAIT    = 3'd5;

    reg [2:0] state;
    reg [1:0] cur;
    reg       core;
    reg [1:0] last;

    reg [2:0] next_state;
    reg [1:0] next_cur;
    reg       next_core;
    reg [1:0] next_last;

    reg [3:0] eligible;
    reg       w_exists;
    reg [1:0] w;
    reg [1:0] kw;
    reg       cstore, camo, cload, dev, start;

    always @* begin
        eligible[0] = req0 && (kind0 != 2'b11);
        eligible[1] = req1 && (kind1 != 2'b11);
        eligible[2] = req2 && (kind2 != 2'b11);
        eligible[3] = req3 && (kind3 != 2'b11);

        w_exists = 1'b0;
        w        = 2'b00;
        if (eligible[(last + 1) % 4]) begin w_exists = 1'b1; w = (last + 1) % 4; end
        else if (eligible[(last + 2) % 4]) begin w_exists = 1'b1; w = (last + 2) % 4; end
        else if (eligible[(last + 3) % 4]) begin w_exists = 1'b1; w = (last + 3) % 4; end
        else if (eligible[last]) begin w_exists = 1'b1; w = last; end

        case (w)
            2'd0: kw = kind0;
            2'd1: kw = kind1;
            2'd2: kw = kind2;
            2'd3: kw = kind3;
            default: kw = 2'b00;
        endcase

        cstore = w_exists && (kw == 2'b00) && is_ram && c_store && !c_amo;
        camo   = w_exists && (kw == 2'b00) && is_ram && c_amo;
        cload  = w_exists && (kw == 2'b00) && is_ram && !c_store && !c_amo;
        dev    = w_exists && (kw == 2'b00) && !is_ram;
        start  = (cstore || camo || cload || (w_exists && (kw == 2'b01)) || (w_exists && (kw == 2'b10))) && eng_ready;
    end

    always @* begin
        sel0 = 1'b0; sel1 = 1'b0; sel2 = 1'b0; sel3 = 1'b0;
        bsel0 = 1'b0; bsel1 = 1'b0; bsel2 = 1'b0; bsel3 = 1'b0;
        grant0 = 1'b0; grant1 = 1'b0; grant2 = 1'b0; grant3 = 1'b0;
        eng_start = 1'b0; eng_we = 1'b0; eng_line = 1'b0; eng_src = 2'b00;
        rdone = 1'b0; wdone = 1'b0;

        next_state = state;
        next_cur = cur;
        next_core = core;
        next_last = last;

        case (state)
            S_IDLE: begin
                if (w_exists) begin
                    case (w)
                        2'd0: sel0 = 1'b1;
                        2'd1: sel1 = 1'b1;
                        2'd2: sel2 = 1'b1;
                        2'd3: sel3 = 1'b1;
                    endcase
                    if (kw == 2'b00) begin
                        case (w)
                            2'd0: bsel0 = 1'b1;
                            2'd1: bsel1 = 1'b1;
                            2'd2: bsel2 = 1'b1;
                            2'd3: bsel3 = 1'b1;
                        endcase
                    end
                    if (dev) begin
                        case (w)
                            2'd0: grant0 = 1'b1;
                            2'd1: grant1 = 1'b1;
                            2'd2: grant2 = 1'b1;
                            2'd3: grant3 = 1'b1;
                        endcase
                    end
                    eng_start = start;
                    eng_we    = start && cstore;
                    eng_line  = start && (kw == 2'b10);
                    eng_src   = w_exists ? kw : 2'b00;
                end else begin
                    eng_src = 2'b00;
                end

                if (start) begin
                    next_cur   = w;
                    next_last  = w;
                    next_core  = (kw == 2'b00);
                    if (cstore)       next_state = S_WRITE_WAIT;
                    else if (camo)    next_state = S_ATOMIC_READ_WAIT;
                    else              next_state = S_READ_WAIT;
                end else if (dev) begin
                    next_last = w;
                end
            end

            S_READ_WAIT: begin
                case (cur)
                    2'd0: begin sel0 = 1'b1; if (core) bsel0 = 1'b1; end
                    2'd1: begin sel1 = 1'b1; if (core) bsel1 = 1'b1; end
                    2'd2: begin sel2 = 1'b1; if (core) bsel2 = 1'b1; end
                    2'd3: begin sel3 = 1'b1; if (core) bsel3 = 1'b1; end
                endcase
                if (eng_done) begin
                    case (cur)
                        2'd0: grant0 = 1'b1;
                        2'd1: grant1 = 1'b1;
                        2'd2: grant2 = 1'b1;
                        2'd3: grant3 = 1'b1;
                    endcase
                end
                rdone = eng_done;
                if (eng_done) next_state = S_IDLE;
            end

            S_WRITE_WAIT: begin
                case (cur)
                    2'd0: begin sel0 = 1'b1; if (core) bsel0 = 1'b1; end
                    2'd1: begin sel1 = 1'b1; if (core) bsel1 = 1'b1; end
                    2'd2: begin sel2 = 1'b1; if (core) bsel2 = 1'b1; end
                    2'd3: begin sel3 = 1'b1; if (core) bsel3 = 1'b1; end
                endcase
                if (eng_done) begin
                    case (cur)
                        2'd0: grant0 = 1'b1;
                        2'd1: grant1 = 1'b1;
                        2'd2: grant2 = 1'b1;
                        2'd3: grant3 = 1'b1;
                    endcase
                end
                wdone = eng_done;
                if (eng_done) next_state = S_IDLE;
            end

            S_ATOMIC_READ_WAIT: begin
                case (cur)
                    2'd0: begin sel0 = 1'b1; if (core) bsel0 = 1'b1; end
                    2'd1: begin sel1 = 1'b1; if (core) bsel1 = 1'b1; end
                    2'd2: begin sel2 = 1'b1; if (core) bsel2 = 1'b1; end
                    2'd3: begin sel3 = 1'b1; if (core) bsel3 = 1'b1; end
                endcase
                rdone = eng_done;
                if (eng_done) next_state = S_ATOMIC_DECIDE;
            end

            S_ATOMIC_DECIDE: begin
                case (cur)
                    2'd0: begin sel0 = 1'b1; if (core) bsel0 = 1'b1; end
                    2'd1: begin sel1 = 1'b1; if (core) bsel1 = 1'b1; end
                    2'd2: begin sel2 = 1'b1; if (core) bsel2 = 1'b1; end
                    2'd3: begin sel3 = 1'b1; if (core) bsel3 = 1'b1; end
                endcase
                eng_start = c_dmem_we && eng_ready;
                eng_we    = c_dmem_we && eng_ready;
                eng_line  = 1'b0;
                eng_src   = 2'b00;
                if (!c_dmem_we) begin
                    case (cur)
                        2'd0: grant0 = 1'b1;
                        2'd1: grant1 = 1'b1;
                        2'd2: grant2 = 1'b1;
                        2'd3: grant3 = 1'b1;
                    endcase
                end
                if (c_dmem_we && eng_ready)       next_state = S_ATOMIC_WRITE_WAIT;
                else if (!c_dmem_we)              next_state = S_IDLE;
                else                              next_state = S_ATOMIC_DECIDE;
            end

            S_ATOMIC_WRITE_WAIT: begin
                case (cur)
                    2'd0: begin sel0 = 1'b1; if (core) bsel0 = 1'b1; end
                    2'd1: begin sel1 = 1'b1; if (core) bsel1 = 1'b1; end
                    2'd2: begin sel2 = 1'b1; if (core) bsel2 = 1'b1; end
                    2'd3: begin sel3 = 1'b1; if (core) bsel3 = 1'b1; end
                endcase
                if (eng_done) begin
                    case (cur)
                        2'd0: grant0 = 1'b1;
                        2'd1: grant1 = 1'b1;
                        2'd2: grant2 = 1'b1;
                        2'd3: grant3 = 1'b1;
                    endcase
                end
                wdone = eng_done;
                if (eng_done) next_state = S_IDLE;
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            cur   <= 2'b00;
            core  <= 1'b0;
            last  <= 2'b11;
        end else begin
            state <= next_state;
            cur   <= next_cur;
            core  <= next_core;
            last  <= next_last;
        end
    end

endmodule

module rsp_hold (
    input  wire         clk,
    input  wire         rst,
    input  wire         done,
    input  wire [255:0] line,
    output wire [255:0] data,
    output wire [31:0]  word
);

    reg [255:0] held;

    always @(posedge clk) begin
        if (rst) begin
            held <= 256'd0;
        end else if (done) begin
            held <= line;
        end
    end

    assign data = done ? line : held;
    assign word = data[31:0];

endmodule

module sm_ptw (
    input  wire        sel0,
    input  wire        sel1,
    input  wire        sel2,
    input  wire        sel3,
    input  wire [31:0] d0,
    input  wire [31:0] d1,
    input  wire [31:0] d2,
    input  wire [31:0] d3,
    output wire [31:0] y
);

    assign y = (d0 & {32{sel0}}) |
               (d1 & {32{sel1}}) |
               (d2 & {32{sel2}}) |
               (d3 & {32{sel3}});

endmodule

module sm_if (
    input  wire        sel0,
    input  wire        sel1,
    input  wire        sel2,
    input  wire        sel3,
    input  wire [31:0] d0,
    input  wire [31:0] d1,
    input  wire [31:0] d2,
    input  wire [31:0] d3,
    output wire [31:0] y
);

    assign y = (d0 & {32{sel0}}) |
               (d1 & {32{sel1}}) |
               (d2 & {32{sel2}}) |
               (d3 & {32{sel3}});

endmodule

module bm_amo (
    input  sel0,
    input  sel1,
    input  sel2,
    input  sel3,
    input  d0,
    input  d1,
    input  d2,
    input  d3,
    output y
);

    assign y = (sel0 & d0) | (sel1 & d1) | (sel2 & d2) | (sel3 & d3);

endmodule

module eng_src_mux (
    input  wire [1:0]   src,
    input  wire [31:0]  a,
    input  wire [31:0]  b,
    input  wire [31:0]  c,
    output reg  [31:0]  y
);

    always @* begin
        case (src)
            2'b00: y = a;
            2'b01: y = b;
            2'b10: y = c;
            2'b11: y = 32'd0;
            default: y = 32'd0;
        endcase
    end

endmodule

module zeros (
    output z1,
    output [3:0] z4,
    output [31:0] z32
);

    assign z1 = 1'b0;
    assign z4 = 4'b0;
    assign z32 = 32'b0;

endmodule

module dc_wp (
    input run,
    input stall,
    output en
);

    assign en = run & (~stall);

endmodule

// axi_m: curated AXI4 master (barg_axi_master), written from the design by rule; no model wrote it.
module axi_m (
  input  wire clk,
  input  wire rst,
  input  wire req_valid,
  output wire req_ready,
  input  wire req_we,
  input  wire req_line,
  input  wire [31:0] req_addr,
  input  wire [31:0] req_wdata,
  input  wire [3:0] req_wstrb,
  input  wire [255:0] req_wline,
  output wire resp_valid,
  output wire [255:0] resp_data,
  output wire resp_err,
  output wire m_axi_arvalid,
  input  wire m_axi_arready,
  output wire [31:0] m_axi_araddr,
  output wire [7:0] m_axi_arlen,
  output wire [2:0] m_axi_arsize,
  output wire [1:0] m_axi_arburst,
  input  wire m_axi_rvalid,
  output wire m_axi_rready,
  input  wire [31:0] m_axi_rdata,
  input  wire [1:0] m_axi_rresp,
  input  wire m_axi_rlast,
  output wire m_axi_awvalid,
  input  wire m_axi_awready,
  output wire [31:0] m_axi_awaddr,
  output wire [7:0] m_axi_awlen,
  output wire [2:0] m_axi_awsize,
  output wire [1:0] m_axi_awburst,
  output wire m_axi_wvalid,
  input  wire m_axi_wready,
  output wire [31:0] m_axi_wdata,
  output wire [3:0] m_axi_wstrb,
  output wire m_axi_wlast,
  input  wire m_axi_bvalid,
  output wire m_axi_bready,
  input  wire [1:0] m_axi_bresp
);
  barg_axi_master #(.BEATS_W(3)) u_ip (
    .clk(clk),
    .rst(rst),
    .req_valid(req_valid),
    .req_ready(req_ready),
    .req_we(req_we),
    .req_line(req_line),
    .req_addr(req_addr),
    .req_wdata(req_wdata),
    .req_wstrb(req_wstrb),
    .req_wline(req_wline),
    .resp_valid(resp_valid),
    .resp_data(resp_data),
    .resp_err(resp_err),
    .m_axi_arvalid(m_axi_arvalid),
    .m_axi_arready(m_axi_arready),
    .m_axi_araddr(m_axi_araddr),
    .m_axi_arlen(m_axi_arlen),
    .m_axi_arsize(m_axi_arsize),
    .m_axi_arburst(m_axi_arburst),
    .m_axi_rvalid(m_axi_rvalid),
    .m_axi_rready(m_axi_rready),
    .m_axi_rdata(m_axi_rdata),
    .m_axi_rresp(m_axi_rresp),
    .m_axi_rlast(m_axi_rlast),
    .m_axi_awvalid(m_axi_awvalid),
    .m_axi_awready(m_axi_awready),
    .m_axi_awaddr(m_axi_awaddr),
    .m_axi_awlen(m_axi_awlen),
    .m_axi_awsize(m_axi_awsize),
    .m_axi_awburst(m_axi_awburst),
    .m_axi_wvalid(m_axi_wvalid),
    .m_axi_wready(m_axi_wready),
    .m_axi_wdata(m_axi_wdata),
    .m_axi_wstrb(m_axi_wstrb),
    .m_axi_wlast(m_axi_wlast),
    .m_axi_bvalid(m_axi_bvalid),
    .m_axi_bready(m_axi_bready),
    .m_axi_bresp(m_axi_bresp)
  );
endmodule

// barg_axi_master: an AXI4 master with a simple request port. One request at a time; 32-bit address and data.
//   word read   (req_we 0, req_line 0): one beat; resp_data bits 31:0 hold the word, the rest of resp_data is 0.
//   line read   (req_we 0, req_line 1): a burst of 2^BEATS_W beats from the line-aligned address (AXI INCR); resp_data holds the line, beat 0 in bits 31:0.
//   word write  (req_we 1, req_line 0): one beat with byte strobes req_wstrb at the word-aligned address.
//   line write  (req_we 1, req_line 1): a burst of 2^BEATS_W beats at the line-aligned address, beat j is bits 32*j+31:32*j of req_wline, all strobes 1.
// A request is taken in a cycle where req_valid and req_ready are both 1 (req_ready is 1 only when idle). resp_valid is 1 for exactly one cycle when
// the transaction is complete; resp_err is 1 in that cycle if any AXI response was not OKAY. Written by rule from its parameters (no model writes it).
// AXI: AxSIZE is 2 (4 bytes), AxBURST is 1 (INCR), a write is a single beat with WLAST 1. AWVALID and WVALID are raised together and each drops when
// accepted (a line write: AWVALID once, WVALID per beat, WLAST on the last). A synchronous active-high reset returns to idle.
module barg_axi_master #(
  parameter integer BEATS_W = 3,
  parameter integer LB = (1 << BEATS_W)      // derived: beats per line
) (
  input  wire                clk,
  input  wire                rst,
  input  wire                req_valid,
  output wire                req_ready,
  input  wire                req_we,
  input  wire                req_line,
  input  wire [31:0]         req_addr,
  input  wire [31:0]         req_wdata,
  input  wire [3:0]          req_wstrb,
  input  wire [LB*32-1:0]    req_wline,
  output wire                resp_valid,
  output wire [LB*32-1:0]    resp_data,
  output wire                resp_err,
  output wire                m_axi_arvalid,
  input  wire                m_axi_arready,
  output wire [31:0]         m_axi_araddr,
  output wire [7:0]          m_axi_arlen,
  output wire [2:0]          m_axi_arsize,
  output wire [1:0]          m_axi_arburst,
  input  wire                m_axi_rvalid,
  output wire                m_axi_rready,
  input  wire [31:0]         m_axi_rdata,
  input  wire [1:0]          m_axi_rresp,
  input  wire                m_axi_rlast,
  output wire                m_axi_awvalid,
  input  wire                m_axi_awready,
  output wire [31:0]         m_axi_awaddr,
  output wire [7:0]          m_axi_awlen,
  output wire [2:0]          m_axi_awsize,
  output wire [1:0]          m_axi_awburst,
  output wire                m_axi_wvalid,
  input  wire                m_axi_wready,
  output wire [31:0]         m_axi_wdata,
  output wire [3:0]          m_axi_wstrb,
  output wire                m_axi_wlast,
  input  wire                m_axi_bvalid,
  output wire                m_axi_bready,
  input  wire [1:0]          m_axi_bresp
);
  localparam [2:0] S_IDLE = 3'd0, S_AR = 3'd1, S_R = 3'd2, S_W = 3'd3, S_B = 3'd4, S_RESP = 3'd5;
  reg [2:0]          state;
  reg [31:0]         addr_q;
  reg                line_q;
  reg                wl_q;                   // a line write
  reg [31:0]         wdata_q;
  reg [3:0]          wstrb_q;
  reg [BEATS_W:0]    beat_q;
  reg [LB*32-1:0]    data_q;
  reg                err_q, aw_done, w_done;

  assign req_ready = (state == S_IDLE);
  assign resp_valid = (state == S_RESP);
  assign resp_data = data_q;
  assign resp_err = err_q;

  assign m_axi_arvalid = (state == S_AR);
  assign m_axi_araddr = addr_q;
  assign m_axi_arlen = line_q ? (LB - 1) : 8'd0;
  assign m_axi_arsize = 3'd2;
  assign m_axi_arburst = 2'd1;
  assign m_axi_rready = (state == S_R);
  assign m_axi_awvalid = (state == S_W) && !aw_done;
  assign m_axi_awaddr = addr_q;
  assign m_axi_awlen = wl_q ? (LB - 1) : 8'd0;
  assign m_axi_awsize = 3'd2;
  assign m_axi_awburst = 2'd1;
  assign m_axi_wvalid = (state == S_W) && !w_done;
  assign m_axi_wdata = wl_q ? data_q[beat_q*32 +: 32] : wdata_q;
  assign m_axi_wstrb = wl_q ? 4'hF : wstrb_q;
  assign m_axi_wlast = wl_q ? (beat_q == LB - 1) : 1'b1;
  assign m_axi_bready = (state == S_B);

  wire aw_now = aw_done || m_axi_awready;   // both channels done once each has been accepted (this cycle or before)
  wire w_now = w_done || (m_axi_wready && (!wl_q || beat_q == LB - 1));   // a line write is done with its last beat

  always @(posedge clk) begin
    if (rst) begin
      state <= S_IDLE; addr_q <= 32'd0; line_q <= 1'b0; wl_q <= 1'b0; wdata_q <= 32'd0; wstrb_q <= 4'd0; beat_q <= 0; data_q <= {(LB*32){1'b0}};
      err_q <= 1'b0; aw_done <= 1'b0; w_done <= 1'b0;
    end else begin
      case (state)
        S_IDLE: if (req_valid) begin
          line_q <= req_line & ~req_we;
          wl_q <= req_line & req_we;
          addr_q <= req_line ? (req_addr & ~((LB * 4) - 1)) : {req_addr[31:2], 2'b00};
          wdata_q <= req_wdata; wstrb_q <= req_wstrb;
          data_q <= (req_line & req_we) ? req_wline : {(LB*32){1'b0}}; err_q <= 1'b0; beat_q <= 0; aw_done <= 1'b0; w_done <= 1'b0;
          state <= req_we ? S_W : S_AR;
        end
        S_AR: if (m_axi_arready) state <= S_R;
        S_R: if (m_axi_rvalid) begin
          data_q[beat_q*32 +: 32] <= m_axi_rdata;
          if (m_axi_rresp != 2'b00) err_q <= 1'b1;
          if (m_axi_rlast) state <= S_RESP; else beat_q <= beat_q + 1'b1;
        end
        S_W: begin
          if (m_axi_awready) aw_done <= 1'b1;
          if (m_axi_wready && !w_done) begin
            if (wl_q && beat_q != LB - 1) beat_q <= beat_q + 1'b1; else w_done <= 1'b1;
          end
          if (aw_now && w_now) state <= S_B;
        end
        S_B: if (m_axi_bvalid) begin
          if (m_axi_bresp != 2'b00) err_q <= 1'b1;
          state <= S_RESP;
        end
        S_RESP: state <= S_IDLE;
        default: state <= S_IDLE;
      endcase
    end
  end
endmodule

module bus_mux4 (
    input  wire        grant0,
    input  wire        grant1,
    input  wire        grant2,
    input  wire        grant3,
    input  wire [31:0] addr0,
    input  wire [31:0] addr1,
    input  wire [31:0] addr2,
    input  wire [31:0] addr3,
    input  wire [31:0] store_data0,
    input  wire [31:0] store_data1,
    input  wire [31:0] store_data2,
    input  wire [31:0] store_data3,
    input  wire [2:0]  memtype0,
    input  wire [2:0]  memtype1,
    input  wire [2:0]  memtype2,
    input  wire [2:0]  memtype3,
    input  wire [1:0]  memsrc0,
    input  wire [1:0]  memsrc1,
    input  wire [1:0]  memsrc2,
    input  wire [1:0]  memsrc3,
    input  wire        valid0,
    input  wire        valid1,
    input  wire        valid2,
    input  wire        valid3,
    input  wire        xcpt0,
    input  wire        xcpt1,
    input  wire        xcpt2,
    input  wire        xcpt3,
    input  wire        memwrite0,
    input  wire        memwrite1,
    input  wire        memwrite2,
    input  wire        memwrite3,
    input  wire        kill0,
    input  wire        kill1,
    input  wire        kill2,
    input  wire        kill3,
    input  wire        dmem_we0,
    input  wire        dmem_we1,
    input  wire        dmem_we2,
    input  wire        dmem_we3,
    input  wire [31:0] dmem_wdata0,
    input  wire [31:0] dmem_wdata1,
    input  wire [31:0] dmem_wdata2,
    input  wire [31:0] dmem_wdata3,
    output reg  [31:0] addr,
    output reg  [31:0] store_data,
    output reg  [2:0]  memtype,
    output reg  [1:0]  memsrc,
    output reg         valid,
    output reg         xcpt,
    output reg         memwrite,
    output reg         kill,
    output reg         dmem_we,
    output reg  [31:0] dmem_wdata
);

always @* begin
    // Default assignments
    addr         = 32'd0;
    store_data   = 32'd0;
    memtype      = 3'd0;
    memsrc       = 2'd0;
    valid        = 1'b0;
    xcpt         = 1'b0;
    memwrite     = 1'b0;
    kill         = 1'b0;
    dmem_we      = 1'b0;
    dmem_wdata   = 32'd0;

    if (grant0) begin
        addr         = addr0;
        store_data   = store_data0;
        memtype      = memtype0;
        memsrc       = memsrc0;
        valid        = valid0;
        xcpt         = xcpt0;
        memwrite     = memwrite0;
        kill         = kill0;
        dmem_we      = dmem_we0;
        dmem_wdata   = dmem_wdata0;
    end else if (grant1) begin
        addr         = addr1;
        store_data   = store_data1;
        memtype      = memtype1;
        memsrc       = memsrc1;
        valid        = valid1;
        xcpt         = xcpt1;
        memwrite     = memwrite1;
        kill         = kill1;
        dmem_we      = dmem_we1;
        dmem_wdata   = dmem_wdata1;
    end else if (grant2) begin
        addr         = addr2;
        store_data   = store_data2;
        memtype      = memtype2;
        memsrc       = memsrc2;
        valid        = valid2;
        xcpt         = xcpt2;
        memwrite     = memwrite2;
        kill         = kill2;
        dmem_we      = dmem_we2;
        dmem_wdata   = dmem_wdata2;
    end else if (grant3) begin
        addr         = addr3;
        store_data   = store_data3;
        memtype      = memtype3;
        memsrc       = memsrc3;
        valid        = valid3;
        xcpt         = xcpt3;
        memwrite     = memwrite3;
        kill         = kill3;
        dmem_we      = dmem_we3;
        dmem_wdata   = dmem_wdata3;
    end
end

endmodule

module region_decode (
    input  wire [31:0] addr,
    output wire        sel_ram,
    output wire        sel_clint,
    output wire        sel_plic,
    output wire        sel_uart,
    output wire        sel_periph,
    output wire        sel_gpu,
    output wire        is_io
);

    assign sel_ram     = (addr[31:26] == 6'b100000);
    assign sel_clint   = (addr[31:16] == 16'h0200);
    assign sel_plic    = (addr[31:26] == 6'b000011);
    assign sel_uart    = (addr[31:12] == 20'h10000);
    assign sel_periph  = (addr[31:16] == 16'h1001);
    assign sel_gpu     = (addr[31:25] == 7'b0011000);

    assign is_io = sel_clint | sel_plic | sel_uart | sel_periph | sel_gpu;

endmodule

module bus_ctl_i (
    input  wire        memwrite,
    input  wire [1:0]  memsrc,
    input  wire        valid,
    input  wire        xcpt,
    input  wire        kill,
    input  wire        sel_ram,
    input  wire        sel_clint,
    input  wire        sel_plic,
    input  wire        sel_uart,
    input  wire        sel_periph,
    input  wire        sel_gpu,
    input  wire        idle,
    output wire        ram_we,
    output wire        clint_we,
    output wire        plic_we,
    output wire        uart_we,
    output wire        periph_we,
    output wire        gpu_we,
    output wire        plic_re,
    output wire        uart_re,
    output wire        periph_re,
    output wire        gpu_re
);

    wire read_enable = (memsrc == 2'b01) && valid && !xcpt && !kill;

    assign ram_we     = memwrite && sel_ram;
    assign clint_we   = memwrite && sel_clint && idle;
    assign plic_we    = memwrite && sel_plic && idle;
    assign uart_we    = memwrite && sel_uart && idle;
    assign periph_we  = memwrite && sel_periph && idle;
    assign gpu_we     = memwrite && sel_gpu && idle;

    assign plic_re    = read_enable && sel_plic && idle;
    assign uart_re    = read_enable && sel_uart && idle;
    assign periph_re  = read_enable && sel_periph && idle;
    assign gpu_re     = read_enable && sel_gpu && idle;

endmodule

module clint_decode4 (
    input  wire [31:0] addr,
    output reg  [2:0]  kind,
    output reg  [1:0]  hart
);

    wire [13:0] w = addr[15:2];

    always @* begin
        kind = 3'd0;
        hart = 2'd0;
        if (w <= 14'd3) begin
            kind = 3'd1;
            hart = w[1:0];
        end else if (w >= 14'h1000 && w <= 14'h1007) begin
            hart = w[2:1];
            if (w[0] == 1'b0)
                kind = 3'd2;
            else
                kind = 3'd3;
        end else if (w == 14'h2FFE) begin
            kind = 3'd4;
            hart = 2'd0;
        end else if (w == 14'h2FFF) begin
            kind = 3'd5;
            hart = 2'd0;
        end else begin
            kind = 3'd0;
            hart = 2'd0;
        end
    end

endmodule

module clint4_div (
    input clk,
    input rst,
    input [2:0] kind,
    input [1:0] hart,
    input [31:0] wdata,
    input we,
    output reg [31:0] rdata,
    output [63:0] mtime,
    output mtip0,
    output mtip1,
    output mtip2,
    output mtip3,
    output msip0,
    output msip1,
    output msip2,
    output msip3
);

    reg [3:0] msip_reg;
    reg [63:0] mtime_reg;
    reg [63:0] mtimecmp_reg [0:3];
    reg [3:0] pre;

    assign msip0 = msip_reg[0];
    assign msip1 = msip_reg[1];
    assign msip2 = msip_reg[2];
    assign msip3 = msip_reg[3];

    assign mtime = mtime_reg;

    assign mtip0 = (mtime_reg >= mtimecmp_reg[0]);
    assign mtip1 = (mtime_reg >= mtimecmp_reg[1]);
    assign mtip2 = (mtime_reg >= mtimecmp_reg[2]);
    assign mtip3 = (mtime_reg >= mtimecmp_reg[3]);

    always @(posedge clk) begin
        if (rst) begin
            pre <= 4'b0;
            msip_reg <= 4'b0;
            mtime_reg <= 64'b0;
            mtimecmp_reg[0] <= 64'hFFFFFFFFFFFFFFFF;
            mtimecmp_reg[1] <= 64'hFFFFFFFFFFFFFFFF;
            mtimecmp_reg[2] <= 64'hFFFFFFFFFFFFFFFF;
            mtimecmp_reg[3] <= 64'hFFFFFFFFFFFFFFFF;
        end else begin
            // Increment prescaler
            pre <= (pre == 4'd15) ? 4'd0 : pre + 1;

            // Write logic
            if (we) begin
                case (kind)
                    3'd1: begin
                        msip_reg[hart] <= wdata[0];
                    end
                    3'd2: begin
                        mtimecmp_reg[hart][31:0] <= wdata;
                    end
                    3'd3: begin
                        mtimecmp_reg[hart][63:32] <= wdata;
                    end
                    3'd4: begin
                        mtime_reg[31:0] <= wdata;
                    end
                    3'd5: begin
                        mtime_reg[63:32] <= wdata;
                    end
                    default: begin
                        // no write
                    end
                endcase
            end

            // Increment mtime only when pre==15 before the edge and not writing to mtime halves
            if ((pre == 4'd15) && !(we && (kind==4 || kind==5))) begin
                mtime_reg <= mtime_reg + 1;
            end
        end
    end

    always @* begin
        case (kind)
            3'd1: rdata = {31'b0, msip_reg[hart]};
            3'd2: rdata = mtimecmp_reg[hart][31:0];
            3'd3: rdata = mtimecmp_reg[hart][63:32];
            3'd4: rdata = mtime_reg[31:0];
            3'd5: rdata = mtime_reg[63:32];
            default: rdata = 32'b0;
        endcase
    end

endmodule

module uart16550 (
    input  wire         clk,
    input  wire         rst,
    input  wire [31:0]  addr,
    input  wire [31:0]  wdata,
    input  wire         we,
    input  wire         re,
    input  wire         rx_valid,
    input  wire [7:0]   rx_data,
    output wire [31:0]  rdata,
    output wire         irq,
    output wire         tx_valid,
    output wire [7:0]   tx_data
);

    // Held state
    reg [3:0]  IER;
    reg [7:0]  LCR;
    reg [4:0]  MCR;
    reg [7:0]  SCR;
    reg [7:0]  DLL;
    reg [7:0]  DLM;
    reg        FE;
    reg        TXF;
    reg        OE;
    reg [7:0]  fifo_mem [0:15];
    reg [3:0]  RP;
    reg [3:0]  WP;
    reg [4:0]  RXCNT;  // 0..16

    // Combinational outputs
    wire       rx_int_pending;
    wire       tx_int_pending;
    wire       interrupt_pending;
    wire [2:0] iir_bits_3_1;

    assign rx_int_pending   = IER[0] && (RXCNT != 0);
    assign tx_int_pending   = IER[1] && TXF;
    assign interrupt_pending = rx_int_pending || tx_int_pending;

    assign iir_bits_3_1 = rx_int_pending   ? 3'b010 :
                          tx_int_pending   ? 3'b001 :
                                             3'b000;

    // rdata
    assign rdata = (addr[2:0] == 3'd0) ? (LCR[7] ? {24'd0, DLL} : (RXCNT != 0 ? {24'd0, fifo_mem[RP]} : 32'd0)) :
                   (addr[2:0] == 3'd1) ? (LCR[7] ? {24'd0, DLM} : {28'd0, IER}) :
                   (addr[2:0] == 3'd2) ? {24'd0, {2{FE}}, 2'b00, iir_bits_3_1, ~interrupt_pending} :
                   (addr[2:0] == 3'd3) ? {24'd0, LCR} :
                   (addr[2:0] == 3'd4) ? {27'd0, MCR} :
                   (addr[2:0] == 3'd5) ? {24'd0, 1'b0, 1'b1, 1'b1, 3'b000, OE, (RXCNT != 0)} :
                   (addr[2:0] == 3'd6) ? 32'd0 :
                   (addr[2:0] == 3'd7) ? {24'd0, SCR} :
                                           32'd0;

    assign irq       = interrupt_pending;
    assign tx_valid  = we && (addr[2:0] == 3'd0) && !LCR[7];
    assign tx_data   = tx_valid ? wdata[7:0] : 8'd0;

    // Next-state signals
    reg [3:0]  IER_next;
    reg [7:0]  LCR_next;
    reg [4:0]  MCR_next;
    reg [7:0]  SCR_next;
    reg [7:0]  DLL_next;
    reg [7:0]  DLM_next;
    reg        FE_next;
    reg        TXF_next;
    reg        OE_next;
    reg [3:0]  RP_next;
    reg [3:0]  WP_next;
    reg [4:0]  RXCNT_next;
    reg        fifo_we;
    reg [3:0]  fifo_waddr;
    reg [7:0]  fifo_wdata;

    // Combinational next-state logic
    always @* begin
        // Default: hold
        IER_next    = IER;
        LCR_next    = LCR;
        MCR_next    = MCR;
        SCR_next    = SCR;
        DLL_next    = DLL;
        DLM_next    = DLM;
        FE_next     = FE;
        TXF_next    = TXF;
        OE_next     = OE;
        RP_next     = RP;
        WP_next     = WP;
        RXCNT_next  = RXCNT;
        fifo_we     = 1'b0;
        fifo_waddr  = 4'd0;
        fifo_wdata  = 8'd0;

        // Step 1: Reads
        if (re) begin
            case (addr[2:0])
                3'd0: if (!LCR[7] && RXCNT != 0) begin
                          RP_next    = RP + 1;
                          RXCNT_next = RXCNT - 1;
                      end
                3'd5: OE_next = 1'b0;
                3'd2: if (iir_bits_3_1 == 3'b001) TXF_next = 1'b0;
                default: ;
            endcase
        end

        // Step 2: Stores
        if (we) begin
            case (addr[2:0])
                3'd0: if (LCR[7]) DLL_next = wdata[7:0];
                      else        TXF_next = 1'b1;
                3'd1: if (LCR[7]) DLM_next = wdata[7:0];
                      else begin
                          IER_next = wdata[3:0];
                          if (IER[1] == 1'b0 && wdata[1] == 1'b1) TXF_next = 1'b1;
                      end
                3'd2: begin
                          FE_next = wdata[0];
                          if (wdata[1]) begin
                              RP_next    = 4'd0;
                              WP_next    = 4'd0;
                              RXCNT_next = 5'd0;
                          end
                      end
                3'd3: LCR_next = wdata[7:0];
                3'd4: MCR_next = wdata[4:0];
                3'd7: SCR_next = wdata[7:0];
                default: ;
            endcase
        end

        // Step 3: Receive
        if (rx_valid) begin
            if (RXCNT_next < 16) begin
                fifo_we     = 1'b1;
                fifo_waddr  = WP_next;
                fifo_wdata  = rx_data;
                WP_next     = WP_next + 1;
                RXCNT_next  = RXCNT_next + 1;
            end else begin
                OE_next = 1'b1;
            end
        end
    end

    // Sequential state update
    integer i;
    always @(posedge clk) begin
        if (rst) begin
            IER    <= 4'd0;
            LCR    <= 8'd0;
            MCR    <= 5'd0;
            SCR    <= 8'd0;
            DLL    <= 8'd0;
            DLM    <= 8'd0;
            FE     <= 1'b0;
            TXF    <= 1'b0;
            OE     <= 1'b0;
            RP     <= 4'd0;
            WP     <= 4'd0;
            RXCNT  <= 5'd0;
            for (i = 0; i < 16; i = i + 1) fifo_mem[i] <= 8'd0;
        end else begin
            IER    <= IER_next;
            LCR    <= LCR_next;
            MCR    <= MCR_next;
            SCR    <= SCR_next;
            DLL    <= DLL_next;
            DLM    <= DLM_next;
            FE     <= FE_next;
            TXF    <= TXF_next;
            OE     <= OE_next;
            RP     <= RP_next;
            WP     <= WP_next;
            RXCNT  <= RXCNT_next;
            if (fifo_we) fifo_mem[fifo_waddr] <= fifo_wdata;
        end
    end

endmodule

module io_mux (
    input  wire [31:0] clint_rdata,
    input  wire [31:0] plic_rdata,
    input  wire [31:0] uart_rdata,
    input  wire [31:0] periph_rdata,
    input  wire [31:0] gpu_rdata,
    input  wire        sel_clint,
    input  wire        sel_plic,
    input  wire        sel_uart,
    input  wire        sel_periph,
    input  wire        sel_gpu,
    output reg  [31:0] y
);

    always @* begin
        y = 32'd0;
        if (sel_clint)
            y = clint_rdata;
        else if (sel_plic)
            y = plic_rdata;
        else if (sel_uart)
            y = uart_rdata;
        else if (sel_periph)
            y = periph_rdata;
        else if (sel_gpu)
            y = gpu_rdata;
    end

endmodule

module hart_cfg (
  input  meip,
  output meip0,
  output meip1,
  output meip2,
  output meip3,
  output [1:0] hartid0,
  output [1:0] hartid1,
  output [1:0] hartid2,
  output [1:0] hartid3
);

  assign meip0  = meip;
  assign meip1  = 1'b0;
  assign meip2  = 1'b0;
  assign meip3  = 1'b0;

  assign hartid0 = 2'd0;
  assign hartid1 = 2'd1;
  assign hartid2 = 2'd2;
  assign hartid3 = 2'd3;

endmodule

module plic8 (
  input clk,
  input rst,
  input we,
  input re,
  input [31:0] addr,
  input [31:0] wdata,
  input s1,
  input s2,
  input s3,
  input s4,
  input s5,
  output reg [31:0] rdata,
  output meip0,
  output meip1,
  output meip2,
  output meip3,
  output seip0,
  output seip1,
  output seip2,
  output seip3
);

  localparam [31:0] OFF_PRIO1 = 32'd1;
  localparam [31:0] OFF_PRIO2 = 32'd2;
  localparam [31:0] OFF_PRIO3 = 32'd3;
  localparam [31:0] OFF_PRIO4 = 32'd4;
  localparam [31:0] OFF_PRIO5 = 32'd5;
  localparam [31:0] OFF_PENDING = 32'h0400;
  localparam [31:0] OFF_ENABLE_BASE = 32'h0800;
  localparam [31:0] OFF_ENABLE_STRIDE = 32'h20;
  localparam [31:0] OFF_THRESHOLD_BASE = 32'h80000;
  localparam [31:0] OFF_THRESHOLD_STRIDE = 32'h400;
  localparam [31:0] OFF_CLAIM_BASE = 32'h80001;
  localparam [31:0] OFF_CLAIM_STRIDE = 32'h400;

  wire [31:0] off = {8'd0, addr[25:2]};

  reg [2:0] prio [1:5];
  reg [5:0] enable [0:7];
  reg [2:0] threshold [0:7];
  reg in_service [1:5];
  reg [2:0] claim [0:7];

  // Combinational claim computation
  always @* begin
    integer c, s;
    reg [2:0] max_prio;
    reg [2:0] max_src;
    for (c = 0; c < 8; c = c + 1) begin
      max_prio = 3'd0;
      max_src = 3'd0;
      for (s = 1; s <= 5; s = s + 1) begin
        if ( (s==1 ? s1 : (s==2 ? s2 : (s==3 ? s3 : (s==4 ? s4 : s5)))) &&
             !in_service[s] &&
             enable[c][s] &&
             (prio[s] > threshold[c]) ) begin
          if (prio[s] > max_prio || (prio[s] == max_prio && s < max_src)) begin
            max_prio = prio[s];
            max_src = s[2:0];
          end
        end
      end
      claim[c] = max_src;
    end
  end

  // Combinational read data
  always @* begin
    rdata = 32'd0;
    if (off >= OFF_PRIO1 && off <= OFF_PRIO5) begin
      rdata = {29'd0, prio[off]};
    end else if (off == OFF_PENDING) begin
      rdata = {26'd0, (s5 & ~in_service[5]), (s4 & ~in_service[4]), (s3 & ~in_service[3]),
               (s2 & ~in_service[2]), (s1 & ~in_service[1]), 1'b0};
    end else begin
      integer c;
      for (c = 0; c < 8; c = c + 1) begin
        if (off == OFF_ENABLE_BASE + c * OFF_ENABLE_STRIDE) begin
          rdata = {26'd0, enable[c][5:1], 1'b0};
        end else if (off == OFF_THRESHOLD_BASE + c * OFF_THRESHOLD_STRIDE) begin
          rdata = {29'd0, threshold[c]};
        end else if (off == OFF_CLAIM_BASE + c * OFF_CLAIM_STRIDE) begin
          rdata = {29'd0, claim[c]};
        end
      end
    end
  end

  // Sequential state updates
  always @(posedge clk) begin
    if (rst) begin
      integer i;
      for (i = 1; i <= 5; i = i + 1) begin
        prio[i] <= 3'd0;
        in_service[i] <= 1'b0;
      end
      for (i = 0; i < 8; i = i + 1) begin
        enable[i] <= 6'd0;
        threshold[i] <= 3'd0;
      end
    end else begin
      if (we) begin
        if (off >= OFF_PRIO1 && off <= OFF_PRIO5) begin
          prio[off] <= wdata[2:0];
        end else begin
          integer c;
          for (c = 0; c < 8; c = c + 1) begin
            if (off == OFF_ENABLE_BASE + c * OFF_ENABLE_STRIDE) begin
              enable[c] <= {wdata[5:1], 1'b0};
            end else if (off == OFF_THRESHOLD_BASE + c * OFF_THRESHOLD_STRIDE) begin
              threshold[c] <= wdata[2:0];
            end else if (off == OFF_CLAIM_BASE + c * OFF_CLAIM_STRIDE) begin
              if (wdata >= 32'd1 && wdata <= 32'd5) begin
                in_service[wdata] <= 1'b0;
              end
            end
          end
        end
      end else if (re) begin
        integer c;
        for (c = 0; c < 8; c = c + 1) begin
          if (off == OFF_CLAIM_BASE + c * OFF_CLAIM_STRIDE) begin
            if (claim[c] != 3'd0) begin
              in_service[claim[c]] <= 1'b1;
            end
          end
        end
      end
    end
  end

  assign meip0 = (claim[0] != 3'd0);
  assign meip1 = (claim[2] != 3'd0);
  assign meip2 = (claim[4] != 3'd0);
  assign meip3 = (claim[6] != 3'd0);
  assign seip0 = (claim[1] != 3'd0);
  assign seip1 = (claim[3] != 3'd0);
  assign seip2 = (claim[5] != 3'd0);
  assign seip3 = (claim[7] != 3'd0);

endmodule

module wlane (
    input [3:0] memtype,
    input [31:0] addr,
    input [31:0] wdata,
    output reg [3:0] be,
    output reg [31:0] data
);

    always @* begin
        case (memtype)
            // Byte access (000, 011)
            4'd0, 4'd3: begin
                // a = bits 1:0 of addr
                // be has only bit a set
                be = 4'b0001 << addr[1:0];
                // data is bits 7:0 of wdata shifted left by 8 * a
                data = wdata[7:0] << (8 * addr[1:0]);
            end

            // Half-word access (001, 100)
            4'd1, 4'd4: begin
                // h = bit 1 of addr
                // be is 0011 when h=0 and 1100 when h=1
                be = addr[1] ? 4'b1100 : 4'b0011;
                // data is bits 15:0 of wdata shifted left by 16 * h
                data = wdata[15:0] << (16 * addr[1]);
            end

            // Word access (010, 110, 111)
            4'd2, 4'd6, 4'd7: begin
                // be is 1111
                be = 4'b1111;
                // data is wdata
                data = wdata;
            end

            // No access (101)
            4'd5: begin
                // be and data are 0
                be = 4'b0000;
                data = 32'b0;
            end

            // Handle reserved/unspecified codes if necessary, though the description implies 0-7 are covered.
            default: begin
                // Defaulting to no access for safety, although all 8 codes are defined above.
                be = 4'b0000;
                data = 32'b0;
            end
        endcase
    end

endmodule

module postw (
    input  clk,
    input  rst,
    input  start,
    input  we,
    input  amo,
    input  wdone,
    input  g0,
    input  g1,
    input  g2,
    input  g3,
    input  b0,
    input  b1,
    input  b2,
    input  b3,
    output wdone_o,
    output go0,
    output go1,
    output go2,
    output go3
);

    // Internal signals
    wire posted;
    reg  pst;

    // posted = start & we & ~amo
    assign posted = start & we & ~amo;

    // pst register: synchronous reset
    always @(posedge clk) begin
        if (rst) begin
            pst <= 1'b0;
        end else begin
            if (posted) begin
                pst <= 1'b1;
            end else if (pst && wdone) begin
                pst <= 1'b0;
            end
            // else keep current value
        end
    end

    // Outputs
    assign wdone_o = (wdone & ~pst) | posted;

    assign go0 = (g0 & ~pst) | (posted & b0);
    assign go1 = (g1 & ~pst) | (posted & b1);
    assign go2 = (g2 & ~pst) | (posted & b2);
    assign go3 = (g3 & ~pst) | (posted & b3);

endmodule

module pdev_bus3(
    input  [31:0] pa,
    input         pw,
    input         pr,
    input  [31:0] gpio_rdata,
    input  [31:0] spi_rdata,
    input  [31:0] i2c_rdata,
    input  [31:0] kbd_rdata,
    input  [31:0] mouse_rdata,
    output        gpio_we,
    output        spi_we,
    output        i2c_we,
    output        kbd_we,
    output        mouse_we,
    output        kbd_re,
    output        mouse_re,
    output [31:0] prdata
);

    wire [3:0] dev = pa[11:8];

    // Write enable signals
    assign gpio_we = pw & (dev == 4'b0000);
    assign spi_we  = pw & (dev == 4'b0001);
    assign i2c_we  = pw & (dev == 4'b0010);
    assign kbd_we  = pw & (dev == 4'b0011);
    assign mouse_we = pw & (dev == 4'b0100);

    // Read enable signals
    assign kbd_re  = pr & (dev == 4'b0011);
    assign mouse_re = pr & (dev == 4'b0100);

    // Read data multiplexer
    assign prdata = (dev == 4'b0000) ? gpio_rdata :
                    (dev == 4'b0001) ? spi_rdata  :
                    (dev == 4'b0010) ? i2c_rdata  :
                    (dev == 4'b0011) ? kbd_rdata  :
                    (dev == 4'b0100) ? mouse_rdata :
                    32'b0;

endmodule

module gpio_regs(
    input          clk,
    input          rst,
    input          we,
    input  [31:0]  addr,
    input  [31:0]  wdata,
    input  [15:0]  pins,
    output [31:0]  rdata,
    output [15:0]  gpio_out,
    output [15:0]  gpio_oe,
    output         irq
);
    // Registers
    reg  [15:0] out;
    reg  [15:0] oe;
    reg  [15:0] ien;
    reg  [15:0] pend;
    reg  [15:0] s1;
    reg  [15:0] s2;
    reg  [15:0] prev;

    // Combinational signals
    wire [15:0] rise;
    wire [15:0] clr;

    assign rise = s2 & ~prev;
    assign clr  = (we && (addr[3:2] == 2'b11)) ? wdata[15:0] : 16'd0;

    // Sequential logic
    always @(posedge clk) begin
        if (rst) begin
            out  <= 16'd0;
            oe   <= 16'd0;
            ien  <= 16'd0;
            pend <= 16'd0;
            s1   <= 16'd0;
            s2   <= 16'd0;
            prev <= 16'd0;
        end else begin
            // Sample pins
            s1   <= pins;
            s2   <= s1;
            prev <= s2;

            // Update pend
            pend <= (pend & ~clr) | rise;

            // Write registers
            if (we) begin
                case (addr[3:2])
                    2'b00: out  <= wdata[15:0];
                    2'b01: oe   <= wdata[15:0];
                    2'b10: ien  <= wdata[15:0];
                    default: ; // pend handled by clr
                endcase
            end
        end
    end

    // Combinational outputs
    assign rdata   = (addr[3:2] == 2'b00) ? {16'd0, s2} :
                     (addr[3:2] == 2'b01) ? {16'd0, oe}  :
                     (addr[3:2] == 2'b10) ? {16'd0, ien} :
                                            {16'd0, pend};

    assign gpio_out = out;
    assign gpio_oe  = oe;
    assign irq      = |(pend & ien);

endmodule

module spi_regs(
    input  clk,
    input  rst,
    input  we,
    input  [31:0] addr,
    input  [31:0] wdata,
    input  tx_ready,
    input  [7:0] rx_data,
    input  rx_valid,
    output [31:0] rdata,
    output [7:0]  tx_data,
    output [1:0]  tx_cs,
    output        tx_valid,
    output        irq
);

// Internal registers
reg  [1:0] cs_reg;
reg  [7:0] last_reg;
reg        done_reg;
reg        busy_reg;
reg        ien_reg;

// Combinational outputs
assign tx_data  = wdata[7:0];
assign tx_cs    = cs_reg;
assign tx_valid = we & (addr[4:2] == 3'b000) & tx_ready;
assign irq      = done_reg & ien_reg;

// rdata combinational logic
wire [2:0] addr_bits = addr[4:2];
assign rdata = (addr_bits == 3'b000) ? {24'b0, last_reg} :
               (addr_bits == 3'b001) ? {30'b0, done_reg, busy_reg} :
               (addr_bits == 3'b010) ? {30'b0, cs_reg} :
               (addr_bits == 3'b011) ? {31'b0, ien_reg} :
               32'b0;

// Sequential logic
always @(posedge clk) begin
    if (rst) begin
        cs_reg   <= 2'b0;
        last_reg <= 8'b0;
        done_reg <= 1'b0;
        busy_reg <= 1'b0;
        ien_reg  <= 1'b0;
    end else begin
        // Handle rx_valid priority
        if (rx_valid) begin
            busy_reg <= 1'b0;
            done_reg <= 1'b1;
            last_reg <= rx_data;
        end else begin
            // rx_valid == 0
            if (tx_valid) begin
                busy_reg <= 1'b1;
            end
            // Clear done on write to bit1 of wdata when addr[4:2]==1
            if (we && (addr[4:2] == 3'b001) && wdata[1]) begin
                done_reg <= 1'b0;
            end
        end

        // Write cs
        if (we && (addr[4:2] == 3'b010)) begin
            cs_reg <= wdata[1:0];
        end

        // Write ien
        if (we && (addr[4:2] == 3'b011)) begin
            ien_reg <= wdata[0];
        end
    end
end

endmodule

module i2c_regs (
    input  clk,
    input  rst,
    input  we,
    input  [31:0] addr,
    input  [31:0] wdata,
    input  cmd_ready,
    input  rsp_valid,
    input  [7:0] rsp_data,
    input  rsp_nack,
    input  rsp_arb_lost,
    output [31:0] rdata,
    output cmd_valid,
    output [1:0] cmd_op,
    output cmd_start,
    output cmd_stop,
    output cmd_nack,
    output [7:0] cmd_data,
    output irq
);

// Internal registers
reg  [7:0] last;
reg        done;
reg        busy;
reg        nack;
reg        arb;
reg        ien;

// Command signals (combinational)
assign cmd_valid = we && (addr[4:2] == 3'b000) && cmd_ready;
assign cmd_op    = wdata[12:11];
assign cmd_start = wdata[8];
assign cmd_stop  = wdata[9];
assign cmd_nack  = wdata[10];
assign cmd_data  = wdata[7:0];

// IRQ generation
assign irq = done & ien;

// Read data (combinational)
assign rdata = (addr[4:2] == 3'b000) ? {24'b0, last} :
               (addr[4:2] == 3'b001) ? {28'b0, arb, nack, done, busy} :
               (addr[4:2] == 3'b010) ? 32'b0 :
               (addr[4:2] == 3'b011) ? {31'b0, ien} :
               32'b0;

// Sequential logic
always @(posedge clk) begin
    if (rst) begin
        last <= 8'b0;
        done <= 1'b0;
        busy <= 1'b0;
        nack <= 1'b0;
        arb  <= 1'b0;
        ien  <= 1'b0;
    end else begin
        // Update interrupt enable
        if (we && (addr[4:2] == 3'b011))
            ien <= wdata[0];

        // Clear status bits on clear write (when not busy)
        if (!rsp_valid && we && (addr[4:2] == 3'b001) && wdata[1])
            begin
                done <= 1'b0;
                nack <= 1'b0;
                arb  <= 1'b0;
            end

        // Response handling (priority over command)
        if (rsp_valid) begin
            busy <= 1'b0;
            done <= 1'b1;
            last <= rsp_data;
            nack <= rsp_nack;
            arb  <= rsp_arb_lost;
        end
        // Command handling
        else if (cmd_valid) begin
            busy <= 1'b1;
        end
    end
end

endmodule

// spi_m: curated SPI master (barg_spi_master), written from the design by rule; no model wrote it.
module spi_m (
  input  wire clk,
  input  wire rst,
  input  wire [7:0] tx_data,
  input  wire [1:0] tx_cs,
  input  wire tx_valid,
  output wire tx_ready,
  output wire [7:0] rx_data,
  output wire rx_valid,
  output wire sclk,
  output wire mosi,
  input  wire miso,
  output wire [3:0] cs_n
);
  barg_spi_master #(.DATA_W(8), .CLK_DIV(4), .CPOL(0), .CPHA(0), .LSB_FIRST(0), .CS_W(4)) u_ip (
    .clk(clk),
    .rst(rst),
    .tx_data(tx_data),
    .tx_cs(tx_cs),
    .tx_valid(tx_valid),
    .tx_ready(tx_ready),
    .rx_data(rx_data),
    .rx_valid(rx_valid),
    .sclk(sclk),
    .mosi(mosi),
    .miso(miso),
    .cs_n(cs_n)
  );
endmodule

// SPI master, one word per transfer. Hand-written curated IP; no part is generated.
//
// Parameters
//   DATA_W     1..64      bits per transfer
//   CLK_DIV    1..65535   clock cycles per half SCLK period (SCLK = clk / (2 * CLK_DIV))
//   CPOL       0, 1       SCLK level when idle
//   CPHA       0, 1       0: sample on the leading edge, shift on the trailing edge; 1: shift on leading, sample on trailing
//   LSB_FIRST  0, 1       bit order on the wire
//   CS_W       1..16      chip-select lines (active low); tx_cs picks one, a value >= CS_W selects none
//
// A transfer starts on tx_valid && tx_ready. Chip select falls, half an SCLK period passes before the first edge
// and after the last, then chip select rises and rx_data holds the word read from miso for one cycle of rx_valid.
// Chip select stays high for at least CLK_DIV cycles between transfers. Reset is synchronous and active high.
// miso is sampled without a synchroniser: the slave is clocked by this SCLK, so it has half a period to settle.
module barg_spi_master #(
  parameter integer DATA_W    = 8,
  parameter integer CLK_DIV   = 4,
  parameter integer CPOL      = 0,
  parameter integer CPHA      = 0,
  parameter integer LSB_FIRST = 0,
  parameter integer CS_W      = 1
) (
  input  wire                                   clk,
  input  wire                                   rst,
  input  wire [DATA_W-1:0]                      tx_data,
  input  wire [$clog2(CS_W > 1 ? CS_W : 2)-1:0] tx_cs,
  input  wire                                   tx_valid,
  output wire                                   tx_ready,
  output reg  [DATA_W-1:0]                      rx_data,
  output reg                                    rx_valid,
  output reg                                    sclk,
  output reg                                    mosi,
  input  wire                                   miso,
  output reg  [CS_W-1:0]                        cs_n
);
  localparam integer CW = $clog2(CLK_DIV + 1);
  localparam integer EW = $clog2(2 * DATA_W + 1);
  localparam [1:0] S_IDLE = 2'd0, S_RUN = 2'd1, S_END = 2'd2, S_GAP = 2'd3;
  reg [1:0]        st;
  reg [CW-1:0]     cnt;
  reg [EW-1:0]     edges;          // SCLK edges still to make; the leading edges are the ones made when this is even
  reg [DATA_W-1:0] tx_sh, rx_sh;
  assign tx_ready = (st == S_IDLE);
  wire          out_bit  = LSB_FIRST ? tx_sh[0] : tx_sh[DATA_W-1];
  wire [DATA_W-1:0] tx_next = LSB_FIRST ? (tx_sh >> 1) : (tx_sh << 1);
  wire          first_bit = LSB_FIRST ? tx_data[0] : tx_data[DATA_W-1];
  wire [DATA_W-1:0] tx_after_first = LSB_FIRST ? (tx_data >> 1) : (tx_data << 1);
  wire [DATA_W-1:0] rx_next = LSB_FIRST ? ({miso, rx_sh} >> 1) : {rx_sh, miso};
  wire          leading  = !edges[0];
  wire          sample   = (CPHA == 0) ? leading : !leading;
  always @(posedge clk) begin
    rx_valid <= 1'b0;
    if (rst) begin
      st <= S_IDLE; cnt <= 0; edges <= 0; tx_sh <= 0; rx_sh <= 0; rx_data <= 0;
      sclk <= CPOL[0]; mosi <= 1'b0; cs_n <= {CS_W{1'b1}};
    end else case (st)
      S_IDLE: if (tx_valid) begin
        st <= S_RUN; cnt <= CLK_DIV[CW-1:0] - 1'b1; edges <= 2 * DATA_W;
        cs_n <= ~({{CS_W{1'b0}}, 1'b1} << tx_cs);
        if (CPHA == 0) begin mosi <= first_bit; tx_sh <= tx_after_first; end
        else tx_sh <= tx_data;
      end
      S_RUN: if (cnt != 0) cnt <= cnt - 1'b1;
        else begin
          sclk <= ~sclk; edges <= edges - 1'b1; cnt <= CLK_DIV[CW-1:0] - 1'b1;
          if (sample) rx_sh <= rx_next;
          else if (CPHA == 1 || edges != 1) begin mosi <= out_bit; tx_sh <= tx_next; end
          if (edges == 1) st <= S_END;
        end
      S_END: if (cnt != 0) cnt <= cnt - 1'b1;
        else begin
          cs_n <= {CS_W{1'b1}}; rx_data <= rx_sh; rx_valid <= 1'b1;
          st <= S_GAP; cnt <= CLK_DIV[CW-1:0] - 1'b1;
        end
      default: if (cnt != 0) cnt <= cnt - 1'b1; else st <= S_IDLE;
    endcase
  end
endmodule

// i2c_m: curated I2C master (barg_i2c_master), written from the design by rule; no model wrote it.
module i2c_m (
  input  wire clk,
  input  wire rst,
  input  wire cmd_valid,
  output wire cmd_ready,
  input  wire [1:0] cmd_op,
  input  wire cmd_start,
  input  wire cmd_stop,
  input  wire cmd_nack,
  input  wire [7:0] cmd_data,
  output wire rsp_valid,
  output wire [7:0] rsp_data,
  output wire rsp_nack,
  output wire rsp_arb_lost,
  output wire scl_o,
  input  wire scl_i,
  output wire sda_o,
  input  wire sda_i
);
  barg_i2c_master #(.CLK_DIV(4), .STRETCH(0)) u_ip (
    .clk(clk),
    .rst(rst),
    .cmd_valid(cmd_valid),
    .cmd_ready(cmd_ready),
    .cmd_op(cmd_op),
    .cmd_start(cmd_start),
    .cmd_stop(cmd_stop),
    .cmd_nack(cmd_nack),
    .cmd_data(cmd_data),
    .rsp_valid(rsp_valid),
    .rsp_data(rsp_data),
    .rsp_nack(rsp_nack),
    .rsp_arb_lost(rsp_arb_lost),
    .scl_o(scl_o),
    .scl_i(scl_i),
    .sda_o(sda_o),
    .sda_i(sda_i)
  );
endmodule

// I2C master, one byte per command. Hand-written curated IP; no part is generated.
//
// Parameters
//   CLK_DIV   2..65535   clock cycles per quarter SCL period (SCL = clk / (4 * CLK_DIV))
//   STRETCH   0, 1       1: wait while a slave holds SCL low (clock stretching); 0: ignore scl_i
//
// The lines are open-drain: scl_o / sda_o = 0 drives the line low and 1 releases it. Connect each to a tri-state
// buffer (line = o ? 1'bz : 1'b0) and read the pad back on scl_i / sda_i.
//
// One command per cmd_valid && cmd_ready. cmd_op: 0 write cmd_data, 1 read a byte (cmd_nack = answer NACK
// instead of ACK, for the last byte), 2 or 3 STOP only. For a byte, cmd_start sends a START (a repeated START
// inside a transaction) before it and cmd_stop a STOP after it. A byte sent with no transaction open always starts
// one. STOP only with no transaction open does nothing. After a byte without cmd_stop, SCL stays low and the next
// command continues the transaction. cmd_ready returns once the bus is back in the state the command leaves it.
// Do not follow a byte the master ACKed (a read without cmd_nack) with a START: the slave may still hold SDA low
// for its next bit, and the master then reports rsp_arb_lost. NACK the last byte first.
// rsp_valid pulses once per command: rsp_data is the byte read (or echoed back on a write), rsp_nack is 1 when the
// slave did not acknowledge a written byte, rsp_arb_lost is 1 when the master released SDA for a 1 and saw it low:
// the master then releases both lines and the command ends with no STOP. Reset is synchronous, active high.
module barg_i2c_master #(
  parameter integer CLK_DIV = 4,
  parameter integer STRETCH = 0
) (
  input  wire       clk,
  input  wire       rst,
  input  wire       cmd_valid,
  output wire       cmd_ready,
  input  wire [1:0] cmd_op,
  input  wire       cmd_start,
  input  wire       cmd_stop,
  input  wire       cmd_nack,
  input  wire [7:0] cmd_data,
  output reg        rsp_valid,
  output reg  [7:0] rsp_data,
  output reg        rsp_nack,
  output reg        rsp_arb_lost,
  output reg        scl_o,
  input  wire       scl_i,
  output reg        sda_o,
  input  wire       sda_i
);
  localparam integer CW = $clog2(CLK_DIV + 1);
  localparam [2:0] S_IDLE = 3'd0, S_START = 3'd1, S_DATA = 3'd2, S_ACK = 3'd3, S_STOP = 3'd4;
  reg [2:0]    st;
  reg [1:0]    q;                  // quarter of the current symbol
  reg [2:0]    bc;                 // data bit
  reg [CW-1:0] cnt;
  reg [7:0]    sh;
  reg          l_read, l_start, l_stop, l_nack;
  reg          active;             // a transaction is open: START sent, no STOP yet
  reg          m_scl, s_scl, m_sda, s_sda;
  assign cmd_ready = (st == S_IDLE);
  wire hold = (STRETCH != 0) && (q == 2'd1) && !s_scl;
  wire [CW-1:0] reload = CLK_DIV[CW-1:0] - 1'b1;
  always @(posedge clk) begin
    rsp_valid <= 1'b0;
    if (rst) begin
      st <= S_IDLE; q <= 0; bc <= 0; cnt <= 0; sh <= 0; active <= 1'b0;
      l_read <= 0; l_start <= 0; l_stop <= 0; l_nack <= 0;
      m_scl <= 1'b1; s_scl <= 1'b1; m_sda <= 1'b1; s_sda <= 1'b1;
      scl_o <= 1'b1; sda_o <= 1'b1; rsp_data <= 0; rsp_nack <= 0; rsp_arb_lost <= 0;
    end else begin
      m_scl <= scl_i; s_scl <= m_scl; m_sda <= sda_i; s_sda <= m_sda;
      if (st == S_IDLE) begin
        if (cmd_valid) begin
          l_read <= cmd_op == 2'd1; l_start <= cmd_start || !active; l_stop <= cmd_stop; l_nack <= cmd_nack;
          sh <= cmd_data; rsp_nack <= 1'b0; rsp_arb_lost <= 1'b0; q <= 0; bc <= 0; cnt <= reload;
          if (cmd_op[1]) begin
            if (active) begin st <= S_STOP; sda_o <= 1'b0; end
            else begin rsp_valid <= 1'b1; rsp_data <= 0; end
          end else if (cmd_start || !active) begin st <= S_START; sda_o <= 1'b1; end
          else begin st <= S_DATA; sda_o <= (cmd_op == 2'd1) ? 1'b1 : cmd_data[7]; end
        end
      end else if (!hold) begin
        if (cnt != 0) cnt <= cnt - 1'b1;
        else begin
          cnt <= reload;
          case (q)
            2'd0: begin q <= 2'd1; scl_o <= 1'b1; end
            2'd1: begin
              q <= 2'd2;
              if (st == S_START) sda_o <= 1'b0;
              else if (st == S_STOP) sda_o <= 1'b1;
            end
            2'd2: begin
              q <= 2'd3;
              if (st != S_STOP) scl_o <= 1'b0;
              if (st == S_DATA) begin
                sh <= {sh[6:0], s_sda};
                if (!l_read && sda_o && !s_sda) begin           // lost arbitration: let go of both lines
                  scl_o <= 1'b1; sda_o <= 1'b1; st <= S_IDLE; active <= 1'b0;
                  rsp_valid <= 1'b1; rsp_arb_lost <= 1'b1; rsp_data <= {sh[6:0], s_sda}; rsp_nack <= 1'b0;
                end
              end
              if (st == S_ACK && !l_read) rsp_nack <= s_sda;
            end
            2'd3: begin
              q <= 2'd0;
              case (st)
                S_START: begin active <= 1'b1; st <= S_DATA; bc <= 0; sda_o <= l_read ? 1'b1 : sh[7]; end
                S_DATA: if (bc == 3'd7) begin st <= S_ACK; sda_o <= l_read ? l_nack : 1'b1; end
                        else begin bc <= bc + 1'b1; sda_o <= l_read ? 1'b1 : sh[7]; end
                S_ACK: if (l_stop) begin st <= S_STOP; sda_o <= 1'b0; end
                       else begin st <= S_IDLE; rsp_valid <= 1'b1; rsp_data <= sh; end
                default: begin st <= S_IDLE; active <= 1'b0; rsp_valid <= 1'b1; rsp_data <= sh; end   // S_STOP
              endcase
            end
          endcase
        end
      end
    end
  end
endmodule

module irq_or2 (
    input  wire a,
    input  wire b,
    output wire y
);

    assign y = a | b;

endmodule

module irq_or3 (
    input  wire a,
    input  wire b,
    output wire y
);

    assign y = a | b;

endmodule

module irq_or3b (
    input  wire a,
    input  wire b,
    output wire y
);

    assign y = a | b;

endmodule

module ps2k_rx(
    input  clk,          // system clock
    input  rst,          // synchronous reset
    input  clk_i,        // PS/2 clock line
    input  dat_i,        // PS/2 data line
    output reg  valid,   // data ready
    output reg [7:0] dout, // received byte
    output reg  perr     // parity / framing error
);

// Internal registers
reg          c1, c2, c3;          // clock synchronizer (3 FFs)
reg          d1, d2;              // data synchronizer (2 FFs)
reg  [3:0]   cnt;                 // bit counter (0..10)
reg  [10:0]  sh;                  // shift register for bits 0..10
reg  [15:0]  idle;                // cycles since last falling edge (max 65535)

wire fall = c3 & ~c2;              // falling edge of PS/2 clock

// Synchronous logic
always @(posedge clk) begin
    if (rst) begin
        // Reset all state
        c1 <= 1'b1; c2 <= 1'b1; c3 <= 1'b1;
        d1 <= 1'b1; d2 <= 1'b1;
        cnt <= 4'd0;
        sh  <= 11'd0;
        idle <= 16'd0;
        valid <= 1'b0;
        perr  <= 1'b0;
        dout  <= 8'd0;
    end else begin
        // Clear outputs each cycle unless set below
        valid <= 1'b0;
        perr  <= 1'b0;

        // Synchronizers
        c1 <= clk_i;
        c2 <= c1;
        c3 <= c2;
        d1 <= dat_i;
        d2 <= d1;

        // Idle counter
if (fall) begin
    idle <= 16'd0;
end else if (idle != 16'd65535) begin
    idle <= idle + 16'd1;
end

        // Bit counter and shift register
if (fall) begin
    if (idle == 16'd32767) begin
        // Frame stalled: drop current frame
        cnt <= 4'd0;
    end else if (cnt == 4'd10) begin
        // Last bit received: evaluate frame
        cnt <= 4'd0;
        if (sh[0] == 1'b0 && d2 == 1'b1 && (^sh[9:1]) == 1'b1) begin
            // Valid frame
            valid <= 1'b1;
            dout  <= sh[8:1];
        end else begin
            // Error
            perr <= 1'b1;
        end
    end else begin
        // Shift in the received bit
        cnt <= cnt + 4'd1;
        sh  <= (sh & ~(11'd1 << cnt)) | ({10'd0, d2} << cnt);
    end
end else begin
    if (idle == 16'd32767) begin
        cnt <= 4'd0;
    end
end
        // When no falling edge, cnt and sh remain unchanged
    end
end

endmodule

module ps2k_tx(
    input  clk,
    input  rst,
    input  clk_i,
    input  dat_i,
    input  start,
    input  [7:0] data,
    output clk_low,
    output dat_low,
    output busy,
    output done,
    output err
);

// Internal registers
reg c1, c2, c3;
reg d1, d2;
reg [1:0] st;          // 0 idle, 1 inhibit, 2 sending
reg [13:0] hold;
reg [3:0] n;
reg [8:0] sh;          // 8 data bits + parity
reg done_reg;
reg err_reg;

// Edge detection
wire fall = c3 & ~c2;
wire rise = ~c3 & c2;

// Reset logic (synchronous)
always @(posedge clk or posedge rst) begin
    if (rst) begin
        c1 <= 1'b1;
        c2 <= 1'b1;
        c3 <= 1'b1;
        d1 <= 1'b1;
        d2 <= 1'b1;
        st <= 2'b00;
        hold <= 14'd0;
        n <= 4'd0;
        sh <= 9'd0;
        done_reg <= 1'b0;
        err_reg <= 1'b0;
    end else begin
        // Shift registers for clock and data lines
        c1 <= clk_i;
        c2 <= c1;
        c3 <= c2;
        d1 <= dat_i;
        d2 <= d1;

        // State machine
        case (st)
            2'b00: begin // idle
                done_reg <= 1'b0;
                if (start) begin
                    // Load shift register with data and parity
                    sh <= {~(^data), data}; // parity bit: 1 when even number of ones
                    hold <= 14'd0;
                    err_reg <= 1'b0;
                    st <= 2'b01;
                end
            end
            2'b01: begin // inhibit
                hold <= hold + 14'd1;
                if (hold == 14'd16383) begin
                    st <= 2'b10;
                    n <= 4'd0;
                end
            end
            2'b10: begin // sending
                if (fall) begin
                    n <= n + 4'd1;
                end
                if (n == 4'd12 && rise) begin
                    done_reg <= 1'b1;
                    err_reg <= d2; // 1 if device did not acknowledge
                    st <= 2'b00;
                end
            end
            default: st <= 2'b00;
        endcase
    end
end

// Combinational outputs
assign clk_low = (st == 2'b01) ? 1'b1 : 1'b0;

assign dat_low = (st == 2'b10) ?
                 ((n == 4'd0 || n == 4'd1) ? 1'b1 :
                  ((n >= 4'd2 && n <= 4'd10) ? ~sh[n-4'd2] : 1'b0))
                 : 1'b0;

assign busy = (st != 2'b00);
assign done = done_reg;
assign err  = err_reg;

endmodule

module ps2k_fifo (
    input  clk,
    input  rst,
    input  pop,
    input  push,
    input  [7:0] din,
    output [7:0] head,
    output [3:0] count
);

// Internal registers
reg [7:0] q0, q1, q2, q3, q4, q5, q6, q7;
reg [3:0] cnt;

// Reset: synchronous
always @(posedge clk) begin
    if (rst) begin
        q0 <= 8'd0; q1 <= 8'd0; q2 <= 8'd0; q3 <= 8'd0;
        q4 <= 8'd0; q5 <= 8'd0; q6 <= 8'd0; q7 <= 8'd0;
        cnt <= 4'd0;
    end else begin
        // Determine next count
        reg [3:0] next_cnt;
        reg [7:0] next_q0, next_q1, next_q2, next_q3;
        reg [7:0] next_q4, next_q5, next_q6, next_q7;

        // Default assignments
        next_q0 = q0; next_q1 = q1; next_q2 = q2; next_q3 = q3;
        next_q4 = q4; next_q5 = q5; next_q6 = q6; next_q7 = q7;
        next_cnt = cnt;

        // Handle pop first
        if (pop && (cnt != 0)) begin
            next_q0 = q1;
            next_q1 = q2;
            next_q2 = q3;
            next_q3 = q4;
            next_q4 = q5;
            next_q5 = q6;
            next_q6 = q7;
            next_q7 = 8'd0;
            next_cnt = cnt - 4'd1;
        end

        // Handle push after pop
        if (push && (next_cnt < 4'd8)) begin
        case (next_cnt)
            4'd0: next_q0 = din;
            4'd1: next_q1 = din;
            4'd2: next_q2 = din;
            4'd3: next_q3 = din;
            4'd4: next_q4 = din;
            4'd5: next_q5 = din;
            4'd6: next_q6 = din;
            4'd7: next_q7 = din;
            default: ; // no change for out-of-range values
        endcase
            next_cnt = next_cnt + 4'd1;
        end

        // Commit next state
        q0 <= next_q0; q1 <= next_q1; q2 <= next_q2; q3 <= next_q3;
        q4 <= next_q4; q5 <= next_q5; q6 <= next_q6; q7 <= next_q7;
        cnt <= next_cnt;
    end
end

// Combinational outputs
assign head  = (cnt != 0) ? q0 : 8'd0;
assign count = cnt;

endmodule

module ps2k_ctl(
    input  clk,
    input  rst,
    input  we,
    input  re_pulse,
    input  [31:0] addr,
    input  [31:0] wdata,
    input  [7:0]  head,
    input  [3:0]  count,
    input  tx_busy,
    input  tx_done,
    input  tx_err,
    output [31:0] rdata,
    output        pop,
    output        tx_start,
    output [7:0]  tx_data,
    output        irq
);

    // Internal registers
    reg re_reg;
    reg ce_reg;

    // Reset and register updates
    always @(posedge clk) begin
        if (rst) begin
            re_reg <= 1'b0;
            ce_reg <= 1'b0;
        end else begin
            // Write to CONTROL register (bit 2 of addr == 1)
            if (we && addr[2]) begin
                re_reg <= wdata[0];
                ce_reg <= 1'b0;
            end
            // Command error from transmitter
            if (tx_done && tx_err) begin
                ce_reg <= 1'b1;
            end
        end
    end

    // pop is combinational: load when re_pulse and accessing DATA register
    assign pop = re_pulse && !addr[2];

    // tx_start combinational: start when we, accessing DATA, and transmitter idle
    assign tx_start = we && !addr[2] && !tx_busy;

    // tx_data always the lower 8 bits of wdata
    assign tx_data = wdata[7:0];

    // rdata combinational
    assign rdata = addr[2] ?
                   {21'd0, ce_reg, 1'b0, (re_reg & (count != 4'd0)), 7'd0, re_reg}
                   :
                   {12'd0, count[3:0], (count != 4'd0), 7'd0, head};

    // irq combinational: re_reg && count != 0
    assign irq = re_reg && (count != 4'd0);

endmodule

module ps2k_rxrst (
    input  wire a,
    input  wire b,
    output wire y
);

    assign y = a | b;

endmodule

module ps2m_rx(
    input  clk,          // system clock
    input  rst,          // synchronous reset
    input  clk_i,        // PS/2 clock line
    input  dat_i,        // PS/2 data line
    output reg  valid,   // data ready
    output reg [7:0] dout, // received byte
    output reg  perr     // parity / framing error
);

// Internal registers
reg          c1, c2, c3;          // clock synchronizer (3 FFs)
reg          d1, d2;              // data synchronizer (2 FFs)
reg  [3:0]   cnt;                 // bit counter (0..10)
reg  [10:0]  sh;                  // shift register for bits 0..10
reg  [15:0]  idle;                // cycles since last falling edge (max 65535)

wire fall = c3 & ~c2;              // falling edge of PS/2 clock

// Synchronous logic
always @(posedge clk) begin
    if (rst) begin
        // Reset all state
        c1 <= 1'b1; c2 <= 1'b1; c3 <= 1'b1;
        d1 <= 1'b1; d2 <= 1'b1;
        cnt <= 4'd0;
        sh  <= 11'd0;
        idle <= 16'd0;
        valid <= 1'b0;
        perr  <= 1'b0;
        dout  <= 8'd0;
    end else begin
        // Clear outputs each cycle unless set below
        valid <= 1'b0;
        perr  <= 1'b0;

        // Synchronizers
        c1 <= clk_i;
        c2 <= c1;
        c3 <= c2;
        d1 <= dat_i;
        d2 <= d1;

        // Idle counter
if (fall) begin
    idle <= 16'd0;
end else if (idle != 16'd65535) begin
    idle <= idle + 16'd1;
end

        // Bit counter and shift register
if (fall) begin
    if (idle == 16'd32767) begin
        // Frame stalled: drop current frame
        cnt <= 4'd0;
    end else if (cnt == 4'd10) begin
        // Last bit received: evaluate frame
        cnt <= 4'd0;
        if (sh[0] == 1'b0 && d2 == 1'b1 && (^sh[9:1]) == 1'b1) begin
            // Valid frame
            valid <= 1'b1;
            dout  <= sh[8:1];
        end else begin
            // Error
            perr <= 1'b1;
        end
    end else begin
        // Shift in the received bit
        cnt <= cnt + 4'd1;
        sh  <= (sh & ~(11'd1 << cnt)) | ({10'd0, d2} << cnt);
    end
end else begin
    if (idle == 16'd32767) begin
        cnt <= 4'd0;
    end
end
        // When no falling edge, cnt and sh remain unchanged
    end
end

endmodule

module ps2m_tx(
    input  clk,
    input  rst,
    input  clk_i,
    input  dat_i,
    input  start,
    input  [7:0] data,
    output clk_low,
    output dat_low,
    output busy,
    output done,
    output err
);

// Internal registers
reg c1, c2, c3;
reg d1, d2;
reg [1:0] st;          // 0 idle, 1 inhibit, 2 sending
reg [13:0] hold;
reg [3:0] n;
reg [8:0] sh;          // 8 data bits + parity
reg done_reg;
reg err_reg;

// Edge detection
wire fall = c3 & ~c2;
wire rise = ~c3 & c2;

// Reset logic (synchronous)
always @(posedge clk or posedge rst) begin
    if (rst) begin
        c1 <= 1'b1;
        c2 <= 1'b1;
        c3 <= 1'b1;
        d1 <= 1'b1;
        d2 <= 1'b1;
        st <= 2'b00;
        hold <= 14'd0;
        n <= 4'd0;
        sh <= 9'd0;
        done_reg <= 1'b0;
        err_reg <= 1'b0;
    end else begin
        // Shift registers for clock and data lines
        c1 <= clk_i;
        c2 <= c1;
        c3 <= c2;
        d1 <= dat_i;
        d2 <= d1;

        // State machine
        case (st)
            2'b00: begin // idle
                done_reg <= 1'b0;
                if (start) begin
                    // Load shift register with data and parity
                    sh <= {~(^data), data}; // parity bit: 1 when even number of ones
                    hold <= 14'd0;
                    err_reg <= 1'b0;
                    st <= 2'b01;
                end
            end
            2'b01: begin // inhibit
                hold <= hold + 14'd1;
                if (hold == 14'd16383) begin
                    st <= 2'b10;
                    n <= 4'd0;
                end
            end
            2'b10: begin // sending
                if (fall) begin
                    n <= n + 4'd1;
                end
                if (n == 4'd12 && rise) begin
                    done_reg <= 1'b1;
                    err_reg <= d2; // 1 if device did not acknowledge
                    st <= 2'b00;
                end
            end
            default: st <= 2'b00;
        endcase
    end
end

// Combinational outputs
assign clk_low = (st == 2'b01) ? 1'b1 : 1'b0;

assign dat_low = (st == 2'b10) ?
                 ((n == 4'd0 || n == 4'd1) ? 1'b1 :
                  ((n >= 4'd2 && n <= 4'd10) ? ~sh[n-4'd2] : 1'b0))
                 : 1'b0;

assign busy = (st != 2'b00);
assign done = done_reg;
assign err  = err_reg;

endmodule

module ps2m_fifo (
    input  clk,
    input  rst,
    input  pop,
    input  push,
    input  [7:0] din,
    output [7:0] head,
    output [3:0] count
);

// Internal registers
reg [7:0] q0, q1, q2, q3, q4, q5, q6, q7;
reg [3:0] cnt;

// Reset: synchronous
always @(posedge clk) begin
    if (rst) begin
        q0 <= 8'd0; q1 <= 8'd0; q2 <= 8'd0; q3 <= 8'd0;
        q4 <= 8'd0; q5 <= 8'd0; q6 <= 8'd0; q7 <= 8'd0;
        cnt <= 4'd0;
    end else begin
        // Determine next count
        reg [3:0] next_cnt;
        reg [7:0] next_q0, next_q1, next_q2, next_q3;
        reg [7:0] next_q4, next_q5, next_q6, next_q7;

        // Default assignments
        next_q0 = q0; next_q1 = q1; next_q2 = q2; next_q3 = q3;
        next_q4 = q4; next_q5 = q5; next_q6 = q6; next_q7 = q7;
        next_cnt = cnt;

        // Handle pop first
        if (pop && (cnt != 0)) begin
            next_q0 = q1;
            next_q1 = q2;
            next_q2 = q3;
            next_q3 = q4;
            next_q4 = q5;
            next_q5 = q6;
            next_q6 = q7;
            next_q7 = 8'd0;
            next_cnt = cnt - 4'd1;
        end

        // Handle push after pop
        if (push && (next_cnt < 4'd8)) begin
        case (next_cnt)
            4'd0: next_q0 = din;
            4'd1: next_q1 = din;
            4'd2: next_q2 = din;
            4'd3: next_q3 = din;
            4'd4: next_q4 = din;
            4'd5: next_q5 = din;
            4'd6: next_q6 = din;
            4'd7: next_q7 = din;
            default: ; // no change for out-of-range values
        endcase
            next_cnt = next_cnt + 4'd1;
        end

        // Commit next state
        q0 <= next_q0; q1 <= next_q1; q2 <= next_q2; q3 <= next_q3;
        q4 <= next_q4; q5 <= next_q5; q6 <= next_q6; q7 <= next_q7;
        cnt <= next_cnt;
    end
end

// Combinational outputs
assign head  = (cnt != 0) ? q0 : 8'd0;
assign count = cnt;

endmodule

module ps2m_ctl(
    input  clk,
    input  rst,
    input  we,
    input  re_pulse,
    input  [31:0] addr,
    input  [31:0] wdata,
    input  [7:0]  head,
    input  [3:0]  count,
    input  tx_busy,
    input  tx_done,
    input  tx_err,
    output [31:0] rdata,
    output        pop,
    output        tx_start,
    output [7:0]  tx_data,
    output        irq
);

    // Internal registers
    reg re_reg;
    reg ce_reg;

    // Reset and register updates
    always @(posedge clk) begin
        if (rst) begin
            re_reg <= 1'b0;
            ce_reg <= 1'b0;
        end else begin
            // Write to CONTROL register (bit 2 of addr == 1)
            if (we && addr[2]) begin
                re_reg <= wdata[0];
                ce_reg <= 1'b0;
            end
            // Command error from transmitter
            if (tx_done && tx_err) begin
                ce_reg <= 1'b1;
            end
        end
    end

    // pop is combinational: load when re_pulse and accessing DATA register
    assign pop = re_pulse && !addr[2];

    // tx_start combinational: start when we, accessing DATA, and transmitter idle
    assign tx_start = we && !addr[2] && !tx_busy;

    // tx_data always the lower 8 bits of wdata
    assign tx_data = wdata[7:0];

    // rdata combinational
    assign rdata = addr[2] ?
                   {21'd0, ce_reg, 1'b0, (re_reg & (count != 4'd0)), 7'd0, re_reg}
                   :
                   {12'd0, count[3:0], (count != 4'd0), 7'd0, head};

    // irq combinational: re_reg && count != 0
    assign irq = re_reg && (count != 4'd0);

endmodule

module ps2m_rxrst (
    input  wire a,
    input  wire b,
    output wire y
);

    assign y = a | b;

endmodule

module l2_ctl_fw (
    input clk,
    input rst,
    input rv,
    input rwe,
    input rline,
    input [31:0] raddr,
    input [31:0] rwdata,
    input [3:0] rwstrb,
    input pair,
    input hit_a,
    input hit_b,
    input [255:0] line_a,
    input [255:0] line_b,
    input d_ready,
    input d_valid,
    input [255:0] d_data,
    output ready,
    output resp_valid,
    output [255:0] resp_data,
    output [31:0] lk_addr,
    output dv,
    output dwe,
    output dline,
    output [31:0] daddr,
    output [31:0] dwdata,
    output [3:0] dwstrb,
    output fill_a_en,
    output fill_b_en,
    output [31:0] fill_addr,
    output [255:0] fill_data,
    output inv_en,
    output [31:0] inv_addr
);
    localparam [2:0] IDLE  = 3'd0;
    localparam [2:0] LOOK  = 3'd1;
    localparam [2:0] DREQ  = 3'd2;
    localparam [2:0] DWAIT = 3'd3;
    localparam [2:0] FILL  = 3'd4;
    localparam [2:0] RESP  = 3'd5;

    reg [2:0] state;
    reg we_q;
    reg line_q;
    reg pair_q;
    reg f_q;
    reg [31:0] addr_q;
    reg [31:0] wd_q;
    reg [3:0] ws_q;
    reg [255:0] data_q;

    wire sel_hit;

    assign sel_hit = pair_q ? hit_b : hit_a;

    always @(posedge clk) begin
        if (rst) begin
            state  <= IDLE;
            we_q   <= 1'b0;
            line_q <= 1'b0;
            pair_q <= 1'b0;
            f_q    <= 1'b0;
            addr_q <= 32'd0;
            wd_q   <= 32'd0;
            ws_q   <= 4'd0;
            data_q <= 256'd0;
        end else begin
            case (state)
        IDLE: begin
            if (rv) begin
                we_q   <= rwe;
                line_q <= rline;
                addr_q <= raddr;
                wd_q   <= rwdata;
                ws_q   <= rwstrb;
                pair_q <= pair;
                state  <= (rwe ? DREQ : LOOK);
            end
        end
                LOOK: begin
                    if (!we_q && line_q && sel_hit) begin
                        f_q   <= 1'b1;
                        state <= RESP;
                    end else begin
                        f_q   <= 1'b0;
                        state <= DREQ;
                    end
                end
                DREQ: begin
                    if (d_ready) begin
                        state <= DWAIT;
                    end
                end
        DWAIT: begin
            if (d_valid) begin
                data_q <= d_data;
                if (we_q)
                    state <= IDLE;
                else if (!line_q)
                    state <= RESP;
                else
                    state <= FILL;
            end
        end
                FILL: begin
                    state <= RESP;
                end
                RESP: begin
                    state <= IDLE;
                end
        default: begin
            if (rv) begin
                we_q   <= rwe;
                line_q <= rline;
                addr_q <= raddr;
                wd_q   <= rwdata;
                ws_q   <= rwstrb;
                pair_q <= pair;
                state  <= (rwe ? DREQ : LOOK);
            end
        end
            endcase
        end
    end

    assign ready = (state == IDLE) || (state == 3'd6) || (state == 3'd7);
    assign resp_valid = (state == RESP) || (state == DWAIT && d_valid && we_q);
    assign resp_data = (state == RESP)
        ? (we_q ? 256'd0 : (f_q ? (pair_q ? line_b : line_a) : data_q))
        : 256'd0;

    assign lk_addr = addr_q;

    assign dv = (state == DREQ);
    assign dwe = we_q;
    assign dline = line_q;
    assign daddr = addr_q;
    assign dwdata = wd_q;
    assign dwstrb = ws_q;

    assign fill_a_en = (state == FILL) && !pair_q;
    assign fill_b_en = (state == FILL) && pair_q;
    assign fill_addr = addr_q;
    assign fill_data = data_q;

    assign inv_en = (state == IDLE && rv && rwe);
    assign inv_addr = (state == IDLE) ? raddr : addr_q;
endmodule

module l3_ctl_fw (
    input  clk,
    input  rst,
    input  rv,
    input  rwe,
    input  rline,
    input  [31:0] raddr,
    input  [31:0] rwdata,
    input  [3:0]  rwstrb,
    input  hit,
    input  [255:0] lk_line,
    input  vic_valid,
    input  vic_dirty,
    input  [31:0] vic_addr,
    input  [255:0] vic_data,
    input  ax_ready,
    input  ax_done,
    input  [255:0] ax_data,
    output ready,
    output resp_valid,
    output [255:0] resp_data,
    output [31:0] lk_addr,
    output fill_en,
    output [31:0] fill_addr,
    output [255:0] fill_data,
    output wr_en,
    output [31:0] wr_addr,
    output [31:0] wr_data,
    output [3:0] wr_be,
    output ax_valid,
    output ax_we,
    output ax_line,
    output [31:0] ax_addr,
    output [31:0] ax_wdata,
    output [3:0] ax_wstrb,
    output [255:0] ax_wline
);

// State encoding
localparam IDLE = 4'd0,
           LOOK = 4'd1,
           WBREQ = 4'd2,
           WBWAIT = 4'd3,
           FREQ = 4'd4,
           FWAIT = 4'd5,
           FILL = 4'd6,
           WR = 4'd7,
           AREQ = 4'd8,
           AWAIT = 4'd9,
           RESP = 4'd10;

// Registers
reg [3:0] state;
reg we_q;
reg line_q;
reg [31:0] addr_q;
reg [31:0] wd_q;
reg [3:0] ws_q;

// Sequential logic: state machine and held registers
always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        we_q <= 1'b0;
        line_q <= 1'b0;
        addr_q <= 32'd0;
        wd_q <= 32'd0;
        ws_q <= 4'd0;
    end else begin
        // Default: hold current state
        state <= state;
        // State transitions
        case (state)
            IDLE: begin
                if (rv) begin
                    we_q <= rwe;
                    line_q <= rline;
                    addr_q <= raddr;
                    wd_q <= rwdata;
                    ws_q <= rwstrb;
                    state <= LOOK;
                end
            end
            LOOK: begin
                if (!we_q) begin // read
                    if (hit) state <= RESP;
                    else if (vic_valid && vic_dirty) state <= WBREQ;
                    else state <= FREQ;
                end else begin // write
                    if (hit) state <= WR;
                    else if (vic_valid && vic_dirty) state <= WBREQ;
                    else state <= FREQ;
                end
            end
            WBREQ: begin
                if (ax_ready) state <= WBWAIT;
            end
            WBWAIT: begin
                if (ax_done) state <= FREQ;
            end
            FREQ: begin
                if (ax_ready) state <= FWAIT;
            end
            FWAIT: begin
                if (ax_done) state <= FILL;
            end
            FILL: begin
                if (we_q) state <= WR;
                else state <= RESP;
            end
            WR: begin
                state <= IDLE;
            end
            AREQ: begin
                if (ax_ready) state <= AWAIT;
            end
            AWAIT: begin
                if (ax_done) state <= RESP;
            end
            RESP: begin
                state <= IDLE;
            end
            default: begin
                state <= IDLE;
            end
        endcase
    end
end

// Combinational outputs
assign ready = (state == IDLE);

assign resp_valid = (state == RESP || state == WR);

assign resp_data = (state == RESP) ?
    (we_q ? 256'd0 :
        (line_q ? lk_line :
            {224'd0, lk_line[(({5'd0, addr_q[4:2]} + 8'd1) * 8'd32 - 1) -: 32]})) :
    256'd0;

assign lk_addr = addr_q;

assign fill_en = (state == FILL);
assign fill_addr = addr_q;
assign fill_data = ax_data;

assign wr_en = (state == WR);
assign wr_addr = addr_q;
assign wr_data = wd_q;
assign wr_be = ws_q;

assign ax_valid = (state == WBREQ) || (state == FREQ) || (state == AREQ);
assign ax_we = (state == WBREQ) || (state == AREQ);
assign ax_line = (state == WBREQ) || (state == FREQ);

assign ax_addr = (state == WBREQ) ? vic_addr :
                 (state == FREQ) ? (addr_q & ~32'h1F) :
                 (state == AREQ) ? (addr_q & ~32'h3) :
                 32'd0;

assign ax_wdata = wd_q;
assign ax_wstrb = ws_q;
assign ax_wline = vic_data;

endmodule

