module c0_core_gate (
    input  wire clk,
    input  wire en,
    input  wire rst,
    output wire gclk
);
`ifdef VERILATOR

    reg en_latch;

    /* verilator lint_off LATCH */
    always @(clk or en or rst) begin
        if (!clk)
            en_latch = en | rst;
    end
    /* verilator lint_on LATCH */

    assign gclk = clk & en_latch;

`else
  BUFGCE #(.SIM_DEVICE("VERSAL_AI_EDGE")) u_gate (.I(clk), .CE(en | rst), .O(gclk));
`endif
endmodule

module c0_rsv_gate (
    input  wire        set_rsv,
    input  wire        clr_rsv,
    input  wire        self_grant,
    input  wire        snoop_we,
    input  wire [31:0] addr,
    input  wire        rsv_valid,
    input  wire [31:0] rsv_addr,
    output wire        set,
    output wire        clear
);

    assign set = set_rsv & self_grant;

    assign clear = (clr_rsv & self_grant) |
                   (snoop_we & ~self_grant & rsv_valid & (addr[31:2] == rsv_addr[31:2]));

endmodule

module c0_amo_rsv (
    input clk,
    input rst,
    input set,
    input clear,
    input [31:0] addr,
    output rsv_valid,
    output [31:0] rsv_addr
);

    reg rsv_valid_r;
    reg [29:0] rsv_word_r;

    always @(posedge clk) begin
        if (rst) begin
            rsv_valid_r <= 1'b0;
            rsv_word_r  <= 30'b0;
        end else if (clear) begin
            rsv_valid_r <= 1'b0;
        end else if (set) begin
            rsv_valid_r <= 1'b1;
            rsv_word_r  <= addr[31:2];
        end
    end

    assign rsv_valid = rsv_valid_r;
    assign rsv_addr  = {rsv_word_r, 2'b00};

endmodule

module c0_dcache_ctl (
    input  wire        clk,
    input  wire        rst,
    input  wire        req,
    input  wire        is_ram,
    input  wire        is_store,
    input  wire        is_amo,
    input  wire        hit,
    input  wire        hold,
    input  wire [31:0] addr,
    input  wire        done,
    input  wire [255:0] line,
    input  wire        wdone,
    input  wire [31:0] waddr,
    input  wire        self,
    input  wire        w_plain,
    output wire        serve,
    output wire        dmiss,
    output wire        rq,
    output wire [31:0] rq_addr,
    output wire        fill_en,
    output wire [31:0] fill_addr,
    output wire [255:0] fill_data,
    output wire        wr_en,
    output wire [31:0] wr_addr,
    output wire        inv_en,
    output wire [31:0] inv_addr
);

    reg [31:0] ra;
    reg        busy;

    wire is_load = req & is_ram & ~is_store & ~is_amo & ~hold;

    assign serve     = is_load & hit;
    assign dmiss     = is_load & ~hit;
    assign rq        = busy;
    assign rq_addr   = ra;
    assign fill_en   = busy & done;
    assign fill_addr = ra;
    assign fill_data = line;
    assign wr_en     = wdone & self & w_plain;
    assign wr_addr   = waddr;
    assign inv_en    = wdone & ~(self & w_plain);
    assign inv_addr  = waddr;

    always @(posedge clk) begin
        if (rst) begin
            ra   <= 32'b0;
            busy <= 1'b0;
        end else begin
            if (!busy && dmiss) begin
                ra   <= addr & ~32'h1F; // clear bits 4:0
                busy <= 1'b1;
            end else if (busy && done) begin
                busy <= 1'b0;
            end
        end
    end

endmodule

module c0_dc_rd (
    input  wire [31:0] addr,
    output wire        sel_ram,
    output wire        sel_clint,
    output wire        sel_plic,
    output wire        sel_uart,
    output wire        sel_periph,
    output wire        sel_gpu,
    output wire        is_io
);

    assign sel_ram     = (addr[31:26] == 6'b100000);
    assign sel_clint   = (addr[31:16] == 16'h0200);
    assign sel_plic    = (addr[31:26] == 6'b000011);
    assign sel_uart    = (addr[31:12] == 20'h10000);
    assign sel_periph  = (addr[31:16] == 16'h1001);
    assign sel_gpu     = (addr[31:25] == 7'b0011000);

    assign is_io = sel_clint | sel_plic | sel_uart | sel_periph | sel_gpu;

endmodule

module c0_wfi_wake (
    input  wire        clk,
    input  wire        rst,
    input  wire [31:0] inst,
    input  wire        msip,
    input  wire        mtip,
    input  wire        meip,
    input  wire [11:0] mip_sw,
    input  wire [11:0] mie,
    output wire        hold
);

// ---------------------------------------------------------------------------
// Internal signals
// ---------------------------------------------------------------------------

// pend: combine mip_sw with the three interrupt bits
wire [11:0] pend_bits;
assign pend_bits[3]  = msip;
assign pend_bits[7]  = mtip;
assign pend_bits[11] = meip;
assign pend_bits[0]  = 1'b0;
assign pend_bits[1]  = 1'b0;
assign pend_bits[2]  = 1'b0;
assign pend_bits[4]  = 1'b0;
assign pend_bits[5]  = 1'b0;
assign pend_bits[6]  = 1'b0;
assign pend_bits[8]  = 1'b0;
assign pend_bits[9]  = 1'b0;
assign pend_bits[10] = 1'b0;

wire [11:0] pend;
assign pend = mip_sw | pend_bits;

// wait_on: WFI instruction and no enabled interrupt pending
wire wait_on;
assign wait_on = (inst == 32'h10500073) && ((pend & mie) == 12'b0);

// ---------------------------------------------------------------------------
// Counter
// ---------------------------------------------------------------------------

reg [15:0] cnt;

always @(posedge clk) begin
    if (rst) begin
        cnt <= 16'd0;
    end else begin
        if (wait_on) begin
            if (cnt != 16'hFFFF)
                cnt <= cnt + 16'd1;
            else
                cnt <= cnt; // stay at max
        end else begin
            cnt <= 16'd0;
        end
    end
end

// ---------------------------------------------------------------------------
// Hold output
// ---------------------------------------------------------------------------

assign hold = wait_on && (cnt != 16'hFFFF);

endmodule

