// c0_icache: curated Set-associative array (barg_cache), written from the design by rule; no model wrote it.
module c0_icache (
  input  wire clk,
  input  wire rst,
  input  wire [63:0] lk_addr,
  output wire [1:0] lk_hit,
  output wire [63:0] lk_data,
  output wire [1:0] lk_way,
  output wire [1:0] lk_state,
  output wire [1:0] lk_dirty,
  input  wire wr_en,
  input  wire [31:0] wr_addr,
  input  wire [31:0] wr_data,
  input  wire [3:0] wr_be,
  output wire wr_hit,
  input  wire fill_en,
  input  wire [31:0] fill_addr,
  input  wire [255:0] fill_data,
  input  wire fill_state,
  output wire vic_valid,
  output wire vic_dirty,
  output wire [31:0] vic_addr,
  output wire [255:0] vic_data,
  output wire vic_state,
  input  wire inv_en,
  input  wire [31:0] inv_addr,
  input  wire inv_all,
  input  wire st_en,
  input  wire [31:0] st_addr,
  input  wire st_state,
  input  wire st_clean
);
  barg_cache #(.SET_W(5), .WAYS(2), .LINE_W(3), .READ_PORTS(2), .STATE_W(0), .DIRTY(0)) u_ip (
    .clk(clk),
    .rst(rst),
    .lk_addr(lk_addr),
    .lk_hit(lk_hit),
    .lk_data(lk_data),
    .lk_way(lk_way),
    .lk_state(lk_state),
    .lk_dirty(lk_dirty),
    .wr_en(wr_en),
    .wr_addr(wr_addr),
    .wr_data(wr_data),
    .wr_be(wr_be),
    .wr_hit(wr_hit),
    .fill_en(fill_en),
    .fill_addr(fill_addr),
    .fill_data(fill_data),
    .fill_state(fill_state),
    .vic_valid(vic_valid),
    .vic_dirty(vic_dirty),
    .vic_addr(vic_addr),
    .vic_data(vic_data),
    .vic_state(vic_state),
    .inv_en(inv_en),
    .inv_addr(inv_addr),
    .inv_all(inv_all),
    .st_en(st_en),
    .st_addr(st_addr),
    .st_state(st_state),
    .st_clean(st_clean)
  );
endmodule

// c0_dcache: curated Set-associative array (barg_cache), written from the design by rule; no model wrote it.
module c0_dcache (
  input  wire clk,
  input  wire rst,
  input  wire [31:0] lk_addr,
  output wire lk_hit,
  output wire [31:0] lk_data,
  output wire lk_way,
  output wire lk_state,
  output wire lk_dirty,
  input  wire wr_en,
  input  wire [31:0] wr_addr,
  input  wire [31:0] wr_data,
  input  wire [3:0] wr_be,
  output wire wr_hit,
  input  wire fill_en,
  input  wire [31:0] fill_addr,
  input  wire [255:0] fill_data,
  input  wire fill_state,
  output wire vic_valid,
  output wire vic_dirty,
  output wire [31:0] vic_addr,
  output wire [255:0] vic_data,
  output wire vic_state,
  input  wire inv_en,
  input  wire [31:0] inv_addr,
  input  wire inv_all,
  input  wire st_en,
  input  wire [31:0] st_addr,
  input  wire st_state,
  input  wire st_clean
);
  barg_cache #(.SET_W(5), .WAYS(2), .LINE_W(3), .READ_PORTS(1), .STATE_W(0), .DIRTY(0)) u_ip (
    .clk(clk),
    .rst(rst),
    .lk_addr(lk_addr),
    .lk_hit(lk_hit),
    .lk_data(lk_data),
    .lk_way(lk_way),
    .lk_state(lk_state),
    .lk_dirty(lk_dirty),
    .wr_en(wr_en),
    .wr_addr(wr_addr),
    .wr_data(wr_data),
    .wr_be(wr_be),
    .wr_hit(wr_hit),
    .fill_en(fill_en),
    .fill_addr(fill_addr),
    .fill_data(fill_data),
    .fill_state(fill_state),
    .vic_valid(vic_valid),
    .vic_dirty(vic_dirty),
    .vic_addr(vic_addr),
    .vic_data(vic_data),
    .vic_state(vic_state),
    .inv_en(inv_en),
    .inv_addr(inv_addr),
    .inv_all(inv_all),
    .st_en(st_en),
    .st_addr(st_addr),
    .st_state(st_state),
    .st_clean(st_clean)
  );
endmodule

module c0_pc (
  input  wire        clk,
  input  wire        rst,
  input  wire        stall,
  input  wire        redirect,
  input  wire [31:0] redirect_pc,
  input  wire        trap_redirect,
  input  wire [31:0] trap_pc,
  input  wire        is16,
  output wire [31:0] pc,
  output wire [31:0] pc_plus4
);

  reg  [31:0] pc_reg;
  wire [31:0] trap_pc_masked;
  wire [31:0] redirect_pc_masked;
  wire [31:0] pc_inc;
  wire [31:0] next_pc;

  assign trap_pc_masked     = {trap_pc[31:1],     1'b0};
  assign redirect_pc_masked = {redirect_pc[31:1], 1'b0};
  assign pc_inc             = is16 ? 32'h00000002 : 32'h00000004;
  assign next_pc            = pc_reg + pc_inc;

  always @(posedge clk) begin
    if (rst) begin
      pc_reg <= 32'h80000000;
    end else if (trap_redirect) begin
      pc_reg <= trap_pc_masked;
    end else if (redirect) begin
      pc_reg <= redirect_pc_masked;
    end else if (stall) begin
      pc_reg <= pc_reg;
    end else begin
      pc_reg <= next_pc;
    end
  end

  assign pc       = pc_reg;
  assign pc_plus4 = pc_reg + pc_inc;

endmodule

module c0_if_id (
    input        clk,
    input        rst,
    input        stall,
    input        flush,
    input  [31:0] pc_in,
    input  [31:0] pc_plus4_in,
    input  [31:0] inst_in,
    output [31:0] pc_out,
    output [31:0] pc_plus4_out,
    output [31:0] inst_out,
    output       valid_out
);

 reg [31:0] pc_q;
  reg [31:0] pc_plus4_q;
  reg [31:0] inst_q;
  reg        valid_q;

  assign pc_out       = pc_q;
  assign pc_plus4_out = pc_plus4_q;
  assign inst_out     = inst_q;
  assign valid_out    = valid_q;

  always @(posedge clk) begin
    if (rst || flush) begin
      pc_q       <= 32'd0;
      pc_plus4_q <= 32'd0;
      inst_q     <= 32'h00000013;
      valid_q    <= 1'b0;
    end else if (!stall) begin
      pc_q       <= pc_in;
      pc_plus4_q <= pc_plus4_in;
      inst_q     <= inst_in;
      valid_q    <= 1'b1;
    end
  end

endmodule

module c0_ctrl_decode (
    input  wire [31:0] inst,
    output wire [4:0]  rs1,
    output wire [4:0]  rs2,
    output wire [4:0]  rd,
    output wire        regwrite,
    output wire        alusrc,
    output wire        arith,
    output wire [2:0]  opsel,
    output wire [2:0]  immsel,
    output wire [2:0]  brsel,
    output wire [2:0]  memtype,
    output wire        memwrite,
    output wire [1:0]  memsrc,
    output wire [1:0]  pcsel,
    output wire        asel
);

    // ------------------------------------------------------------------
    // Instruction fields
    // ------------------------------------------------------------------
    wire [6:0] opcode;
    wire [2:0] funct3;
    wire       bit30;

    assign opcode = inst[6:0];
    assign funct3 = inst[14:12];
    assign bit30  = inst[30];

    // ------------------------------------------------------------------
    // Register selectors: plain slices of the instruction word
    // ------------------------------------------------------------------
    assign rs1 = inst[19:15];
    assign rs2 = inst[24:20];
    assign rd  = inst[11:7];

    // ------------------------------------------------------------------
    // Recognition terms.  An opcode listed with funct3 values is only
    // recognised for a funct3 value listed for it.  The upper-immediate
    // loads and the direct jump ignore funct3 (it is immediate data).
    // ------------------------------------------------------------------
    wire is_lui;
    wire is_auipc;
    wire is_jal;
    wire is_jalr;
    wire is_branch;
    wire is_load;
    wire is_store;
    wire is_op_imm;
    wire is_op;
    wire valid;

    assign is_lui    = (opcode == 7'b0110111);
    assign is_auipc  = (opcode == 7'b0010111);
    assign is_jal    = (opcode == 7'b1101111);
    assign is_jalr   = (opcode == 7'b1100111) && (funct3 == 3'b000);
    assign is_branch = (opcode == 7'b1100011) &&
                       ((funct3 == 3'b000) || (funct3 == 3'b001) ||
                        (funct3 == 3'b100) || (funct3 == 3'b101) ||
                        (funct3 == 3'b110) || (funct3 == 3'b111));
    assign is_load   = (opcode == 7'b0000011) &&
                       ((funct3 == 3'b000) || (funct3 == 3'b001) ||
                        (funct3 == 3'b010) || (funct3 == 3'b100) ||
                        (funct3 == 3'b101));
    assign is_store  = (opcode == 7'b0100011) &&
                       ((funct3 == 3'b000) || (funct3 == 3'b001) ||
                        (funct3 == 3'b010));
    assign is_op_imm = (opcode == 7'b0010011);
    assign is_op     = (opcode == 7'b0110011);

    assign valid = is_lui    || is_auipc || is_jal    || is_jalr   ||
                   is_branch || is_load  || is_store  || is_op_imm ||
                   is_op;

    // ------------------------------------------------------------------
    // Register write
    // ------------------------------------------------------------------
    assign regwrite = is_lui    || is_auipc || is_jal   || is_jalr  ||
                      is_load   || is_op_imm || is_op;

    // ------------------------------------------------------------------
    // Memory access: width code only from load/store, otherwise NO_ACCESS
    // ------------------------------------------------------------------
    assign memtype  = is_load  ? ((funct3 == 3'b100) ? 3'b011 :
                                  (funct3 == 3'b101) ? 3'b100 :
                                                       funct3) :
                     is_store ? funct3 : 3'b101;
    assign memwrite = is_store;

    // ------------------------------------------------------------------
    // Write-back source
    // ------------------------------------------------------------------
    assign memsrc = (is_jal || is_jalr) ? 2'b10 :
                    is_load            ? 2'b01 :
                    is_lui             ? 2'b11 :
                                         2'b00;

    // ------------------------------------------------------------------
    // Immediate layout.  Default NO_IMMEDIATE (register-register and the
    // unrecognised case).
    // ------------------------------------------------------------------
    assign immsel = is_jal                 ? 3'b100 :
                    is_branch              ? 3'b010 :
                    is_store               ? 3'b001 :
                    (is_lui || is_auipc)   ? 3'b011 :
                    (is_load || is_jalr ||
                     is_op_imm)           ? 3'b000 :
                                               3'b101;

    // ------------------------------------------------------------------
    // Next program counter.  Default NEXT.
    // ------------------------------------------------------------------
    assign pcsel = is_branch ? 2'b01 :
                   is_jal    ? 2'b10 :
                   is_jalr   ? 2'b11 :
                              2'b00;

    // ------------------------------------------------------------------
    // Branch condition.  Default NO_BRANCH (111), which is never taken.
    // ------------------------------------------------------------------
    assign brsel = is_branch ? ((funct3 == 3'b100) ? 3'b010 :
                                (funct3 == 3'b101) ? 3'b011 :
                                (funct3 == 3'b110) ? 3'b100 :
                                (funct3 == 3'b111) ? 3'b101 : funct3)
                             : 3'b111;

    // ------------------------------------------------------------------
    // Arithmetic unit operand selects.  Only these instructions use the
    // arithmetic unit: AUIPC, JALR, load, store, and both arithmetic
    // opcodes.  For all others these outputs are don't care.
    // ------------------------------------------------------------------
    assign alusrc = (is_auipc || is_jalr || is_load || is_store || is_op_imm)
                    ? 1'b1 : 1'b0;

    assign asel   = is_auipc ? 1'b1 : 1'b0;

    // ------------------------------------------------------------------
    // Arithmetic operation.  Bit 30 is read only for subtract
    // (register-register funct3 000) and for the shift-right funct3 101.
    // ------------------------------------------------------------------
    assign opsel = (is_op_imm || is_op) ? funct3 : 3'b000;

    assign arith = bit30 &
                   ((is_op     && ((funct3 == 3'b000) || (funct3 == 3'b101))) ||
                    (is_op_imm &&  (funct3 == 3'b101)));

endmodule

module c0_imm_gen (
    input  wire [31:0] inst,
    input  wire [2:0]  immsel,
    output wire [31:0] imm
);

    wire signed [31:0] imm_i;
    wire signed [31:0] imm_s;
    wire signed [31:0] imm_b;
    wire        [31:0] imm_u;
    wire signed [31:0] imm_j;
    wire signed [31:0] imm_zero;

    assign imm_i = {{20{inst[31]}}, inst[31:20]};

    assign imm_s = {{20{inst[31]}}, inst[31:25], inst[11:7]};

    assign imm_b = {{19{inst[31]}}, inst[31], inst[7], inst[30:25], inst[11:8], 1'b0};

    assign imm_u = {inst[31:12], 12'd0};

    assign imm_j = {{11{inst[31]}}, inst[31], inst[19:12], inst[20], inst[30:21], 1'b0};

    assign imm_zero = 32'd0;

    reg [31:0] imm_r;
    always @* begin
        case (immsel)
            3'b000: imm_r = imm_i;
            3'b001: imm_r = imm_s;
            3'b010: imm_r = imm_b;
            3'b011: imm_r = imm_u;
            3'b100: imm_r = imm_j;
            3'b101: imm_r = imm_zero;
            3'b110: imm_r = imm_zero;
            3'b111: imm_r = imm_zero;
            default: imm_r = imm_zero;
        endcase
    end

    assign imm = imm_r;

endmodule

module c0_regfile (
  input clk,
  input        rst,
  input        regwrite,
  input  [4:0] raddr1,
  input  [4:0] raddr2,
  input  [4:0] waddr,
  input  [31:0] wdata,
  output [31:0] rdata1,
  output [31:0] rdata2
);

  reg [31:0] mem [0:31];
  integer i;

  wire write_en;

  assign write_en = regwrite & (waddr != 5'd0);

  assign rdata1 = (raddr1 == 5'd0) ? 32'd0 :
                  ((raddr1 == waddr) && write_en) ? wdata : mem[raddr1];

  assign rdata2 = (raddr2 == 5'd0) ? 32'd0 :
                  ((raddr2 == waddr) && write_en) ? wdata : mem[raddr2];

  initial begin
    for (i = 0; i < 32; i = i + 1)
      mem[i] = 32'd0;
  end

  always @(posedge clk) begin
    if (rst) begin
      for (i = 0; i < 32; i = i + 1)
        mem[i] <= 32'd0;
    end else if (write_en) begin
      mem[waddr] <= wdata;
    end
  end

endmodule

module c0_hazard_unit (
    input      [4:0] rs1_id,
    input      [4:0] rs2_id,
    input      [4:0] rd_ex,
    input            regwrite_ex,
    input      [1:0] memsrc_ex,
    input            is_csr_ex,
    input            redirect,
    input            md_busy,
    input            wb_redirect,
    output           stall,
    output           md_stall,
    output           flush_if_id,
    output           flush_id_ex,
    output           flush_ex_mem,
    output           flush_mem_wb
);

    localparam [1:0] FROM_MEMORY = 2'b01;

    wire is_load_ex;
    wire late_result_ex;
    wire rd_nonzero;
    wire rd_match;
    wire load_use;

    assign is_load_ex  = (memsrc_ex == FROM_MEMORY);

    // The value written by the execute-stage instruction is only available
    // after the load leaves memory or after the CSR read completes.
    assign late_result_ex = is_load_ex | is_csr_ex;

    assign rd_nonzero = (rd_ex != 5'd0);

    assign rd_match = ((rd_ex == rs1_id) | (rd_ex == rs2_id));

    assign load_use = regwrite_ex & late_result_ex & rd_nonzero & rd_match;

    assign stall        = load_use | md_busy;
    assign md_stall     = md_busy;
    assign flush_if_id  = redirect | wb_redirect;
    assign flush_id_ex  = redirect | wb_redirect | load_use;
    assign flush_ex_mem = md_busy | wb_redirect;
    assign flush_mem_wb = wb_redirect;

endmodule

module c0_id_ex (
    input  wire         clk,
    input  wire         rst,
    input  wire         stall,
    input  wire         flush,
    input  wire [31:0]  pc_in,
    input  wire [31:0]  pc_plus4_in,
    input  wire [31:0]  rs1_data_in,
    input  wire [31:0]  rs2_data_in,
    input  wire [31:0]  imm_in,
    input  wire [4:0]   rs1_in,
    input  wire [4:0]   rs2_in,
    input  wire [4:0]   rd_in,
    input  wire         regwrite_in,
    input  wire         alusrc_in,
    input  wire         arith_in,
    input  wire [2:0]   opsel_in,
    input  wire         asel_in,
    input  wire [2:0]   brsel_in,
    input  wire [1:0]   pcsel_in,
    input  wire [2:0]   memtype_in,
    input  wire         memwrite_in,
    input  wire [1:0]   memsrc_in,
    input  wire [3:0]   mdop_in,
    input  wire         valid_in,
    input  wire [31:0]  inst_in,
    input  wire         xcpt_in,
    input  wire [3:0]   cause_in,
    input  wire [2:0]   csrop_in,
    input  wire         is_csr_in,
    input  wire         is_mret_in,
    input  wire         csr_imm_in,
    input  wire         irq_in,
    input  wire         is_amo_in,
    input  wire [3:0]   amo_op_in,
    output reg  [31:0]  pc_out,
    output reg  [31:0]  pc_plus4_out,
    output reg  [31:0]  rs1_data_out,
    output reg  [31:0]  rs2_data_out,
    output reg  [31:0]  imm_out,
    output reg  [4:0]   rs1_out,
    output reg  [4:0]   rs2_out,
    output reg  [4:0]   rd_out,
    output reg          regwrite_out,
    output reg          alusrc_out,
    output reg          arith_out,
    output reg  [2:0]   opsel_out,
    output reg          asel_out,
    output reg  [2:0]   brsel_out,
    output reg  [1:0]   pcsel_out,
    output reg  [2:0]   memtype_out,
    output reg          memwrite_out,
    output reg  [1:0]   memsrc_out,
    output reg  [3:0]   mdop_out,
    output reg          valid_out,
    output reg  [31:0]  inst_out,
    output reg          xcpt_out,
    output reg  [3:0]   cause_out,
    output reg  [2:0]   csrop_out,
    output reg          is_csr_out,
    output reg          is_mret_out,
    output reg          csr_imm_out,
    output reg          irq_out,
    output reg          is_amo_out,
    output reg  [3:0]   amo_op_out
);

    always @(posedge clk) begin
        if (rst || flush) begin
            pc_out          <= 32'd0;
            pc_plus4_out    <= 32'd0;
            rs1_data_out    <= 32'd0;
            rs2_data_out    <= 32'd0;
            imm_out         <= 32'd0;
            rs1_out         <= 5'd0;
            rs2_out         <= 5'd0;
            rd_out          <= 5'd0;
            regwrite_out    <= 1'b0;
            alusrc_out      <= 1'b0;
            arith_out       <= 1'b0;
            opsel_out       <= 3'd0;
            asel_out        <= 1'b0;
            brsel_out       <= 3'd7;   // NO_BRANCH
            pcsel_out       <= 2'd0;   // NEXT
            memtype_out     <= 3'd5;   // NO_ACCESS
            memwrite_out    <= 1'b0;   // NO_STORE
            memsrc_out      <= 2'd0;
            mdop_out        <= 4'd0;   // MD_NONE
            valid_out       <= 1'b0;
            inst_out        <= 32'd0;
            xcpt_out        <= 1'b0;
            cause_out       <= 4'd0;
            csrop_out       <= 3'd0;   // CSR_NONE
            is_csr_out      <= 1'b0;
            is_mret_out     <= 1'b0;
            csr_imm_out     <= 1'b0;
            irq_out         <= 1'b0;
            is_amo_out      <= 1'b0;
            amo_op_out      <= 4'd0;   // AMO_NONE
        end else if (!stall) begin
            pc_out          <= pc_in;
            pc_plus4_out    <= pc_plus4_in;
            rs1_data_out    <= rs1_data_in;
            rs2_data_out    <= rs2_data_in;
            imm_out         <= imm_in;
            rs1_out         <= rs1_in;
            rs2_out         <= rs2_in;
            rd_out          <= rd_in;
            regwrite_out    <= regwrite_in;
            alusrc_out      <= alusrc_in;
            arith_out       <= arith_in;
            opsel_out       <= opsel_in;
            asel_out        <= asel_in;
            brsel_out       <= brsel_in;
            pcsel_out       <= pcsel_in;
            memtype_out     <= memtype_in;
            memwrite_out    <= memwrite_in;
            memsrc_out      <= memsrc_in;
            mdop_out        <= mdop_in;
            valid_out       <= valid_in;
            inst_out        <= inst_in;
            xcpt_out        <= xcpt_in;
            cause_out       <= cause_in;
            csrop_out       <= csrop_in;
            is_csr_out      <= is_csr_in;
            is_mret_out     <= is_mret_in;
            csr_imm_out     <= csr_imm_in;
            irq_out         <= irq_in;
            is_amo_out      <= is_amo_in;
            amo_op_out      <= amo_op_in;
        end
    end

endmodule

module c0_forward_unit (
    input  wire [4:0] rs1,
    input  wire [4:0] rs2,
    input  wire [4:0] rd_mem,
    input  wire       regwrite_mem,
    input  wire [4:0] rd_wb,
    input  wire       regwrite_wb,
    output reg  [1:0] fwd_a,
    output reg  [1:0] fwd_b
);

    localparam [1:0] FROM_REGISTER = 2'b00;
    localparam [1:0] FROM_EX_MEM   = 2'b01;
    localparam [1:0] FROM_MEM_WB   = 2'b10;
    localparam [1:0] RESERVED      = 2'b11;

    wire hit_mem_a = regwrite_mem && (rd_mem != 5'd0) && (rd_mem == rs1);
    wire hit_wb_a  = regwrite_wb  && (rd_wb  != 5'd0) && (rd_wb  == rs1);
    wire hit_mem_b = regwrite_mem && (rd_mem != 5'd0) && (rd_mem == rs2);
    wire hit_wb_b  = regwrite_wb  && (rd_wb  != 5'd0) && (rd_wb  == rs2);

    always @* begin
        fwd_a = FROM_REGISTER;
        if (hit_mem_a)
            fwd_a = FROM_EX_MEM;
        else if (hit_wb_a)
            fwd_a = FROM_MEM_WB;
    end

    always @* begin
        fwd_b = FROM_REGISTER;
        if (hit_mem_b)
            fwd_b = FROM_EX_MEM;
        else if (hit_wb_b)
            fwd_b = FROM_MEM_WB;
    end

endmodule

module c0_fwd_a_mux (
    input  wire [31:0] from_reg,
    input  wire [31:0] from_mem,
    input  wire [31:0] from_wb,
    input  wire [1:0]  sel,
    output wire [31:0] y
);

assign y = (sel == 2'd2) ? from_wb :
 (sel == 2'd1) ? from_mem :
          (sel == 2'd0) ? from_reg :
          32'd0;

endmodule

module c0_fwd_b_mux (
    input  wire [31:0] from_reg,
    input  wire [31:0] from_mem,
    input  wire [31:0] from_wb,
    input  wire [1:0]  sel,
    output wire [31:0] y
);

    reg [31:0] y_r;

    always @* begin
        case (sel)
            2'b00:   y_r = from_reg;
            2'b01:   y_r = from_mem;
            2'b10:   y_r = from_wb;
            default: y_r = from_wb;
        endcase
    end

    assign y = y_r;

endmodule

module c0_alu_a_mux (
    input  wire [31:0] from_reg,
    input  wire [31:0] pc,
    input  wire        sel,
    output wire [31:0] y
);

    assign y = sel ? pc : from_reg;

endmodule

module c0_alu_core (
    input  wire [31:0] a,
    input  wire [31:0] b_reg,
    input  wire [31:0] b_imm,
    input  wire        alusrc,
    input  wire [2:0]  opsel,
    input  wire        arith,
    output reg  [31:0] y,
    output wire        zero
);

  wire [31:0] b = alusrc ? b_imm : b_reg;

  wire [31:0] add_res = a + b;
  wire [31:0] sub_res = a - b;

  wire [4:0]        shamt = b[4:0];
  wire [31:0]       shl_res = a << shamt;
  wire [31:0]       shr_res = a >> shamt;
  wire signed [31:0] sar_res = $signed(a) >>> shamt;

  wire [31:0] slt_res  = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
  wire [31:0] sltu_res = (a < b) ? 32'd1 : 32'd0;

  always @* begin
    y = 32'd0;
    case (opsel)
      3'b000: y = arith ? sub_res  : add_res;
      3'b001: y = shl_res;
      3'b010: y = slt_res;
      3'b011: y = sltu_res;
      3'b100: y = a ^ b;
      3'b101: y = arith ? sar_res   : shr_res;
      3'b110: y = a | b;
      3'b111: y = a & b;
      default: y = 32'd0;
    endcase
  end

  assign zero = (y == 32'd0);

endmodule

module c0_br_comp (
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire [2:0]  brsel,
    output reg         taken
);

    wire eq   = (a == b);
    wire lt_s = ($signed(a) < $signed(b));
    wire lt_u = (a < b);

    always @* begin
        case (brsel)
            3'b000:   taken = eq;        // BR_EQ
            3'b001:   taken = ~eq;       // BR_NE
            3'b010:   taken = lt_s;      // BR_LT  signed
            3'b011:   taken = ~lt_s;     // BR_GE  signed
            3'b100:   taken = lt_u;      // BR_LTU unsigned
            3'b101:   taken = ~lt_u;     // BR_GEU unsigned
            3'b110:   taken = 1'b0;      // reserved
            3'b111:   taken = 1'b0;      // NO_BRANCH
            default:  taken = 1'b0;
        endcase
    end

endmodule

module c0_branch_adder (
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] sum
);

assign sum = a + b;

endmodule

module c0_branch_unit (
    input  wire [1:0]  pcsel,
    input  wire        taken,
    input  wire [31:0] branch_target,
    input  wire [31:0] jalr_target,
    output reg         redirect,
    output reg  [31:0] redirect_pc
);

    always @* begin
        redirect    = 1'b0;
        redirect_pc = 32'd0;
        case (pcsel)
            2'b00: begin // NEXT
                redirect    = 1'b0;
                redirect_pc = branch_target;
            end
            2'b01: begin // BRANCH
                redirect    = taken;
                redirect_pc = branch_target;
            end
            2'b10: begin // JUMP
                redirect    = 1'b1;
                redirect_pc = branch_target;
            end
            2'b11: begin // JUMPREG
                redirect    = 1'b1;
                redirect_pc = {jalr_target[31:1], 1'b0};
            end
            default: begin
                redirect    = 1'b0;
                redirect_pc = branch_target;
            end
        endcase
    end

endmodule

module c0_ex_result_mux (
    input  wire [31:0] alu,
    input  wire [31:0] loaded,
    input  wire [31:0] pc_plus4,
    input  wire [31:0] imm,
    input  wire [1:0]  sel,
    output wire [31:0] y
);

    reg [31:0] y_r;

    always @* begin
        case (sel)
            2'b00: y_r = alu;       // FROM_ALU
            2'b01:   y_r = loaded;    // FROM_MEMORY
            2'b10:   y_r = pc_plus4;  // FROM_PC
            default: y_r = imm;       // FROM_IMMEDIATE
        endcase
    end

    assign y = y_r;

endmodule

module c0_ex_mem (
    input  wire        clk,
    input  wire        rst,
    input  wire        flush,
    input  wire [31:0] alu_y_in,
    input  wire [31:0] result_in,
    input  wire [31:0] store_data_in,
    input  wire [4:0]  rd_in,
    input  wire        regwrite_in,
    input  wire        memwrite_in,
    input  wire [2:0]  memtype_in,
    input  wire [1:0]  memsrc_in,
    input  wire [31:0] pc_in,
    input  wire [31:0] tval_in,
    input  wire [31:0] csr_wdata_in,
    input  wire        valid_in,
    input  wire [31:0] inst_in,
    input  wire        xcpt_in,
    input  wire [3:0]  cause_in,
    input  wire [2:0]  csrop_in,
    input  wire        is_csr_in,
    input  wire        is_mret_in,
    output reg  [31:0] alu_y_out,
    output reg  [31:0] result_out,
    output reg  [31:0] store_data_out,
    output reg  [4:0]  rd_out,
    output reg         regwrite_out,
    output reg         memwrite_out,
    output reg  [2:0]  memtype_out,
    output reg  [1:0]  memsrc_out,
    output reg  [31:0] pc_out,
    output reg  [31:0] tval_out,
    output reg  [31:0] csr_wdata_out,
    output reg         valid_out,
    output reg  [31:0] inst_out,
    output reg         xcpt_out,
    output reg  [3:0]  cause_out,
    output reg  [2:0]  csrop_out,
    output reg         is_csr_out,
    output reg         is_mret_out,
    input  wire        irq_in,
    output reg         irq_out,
    input  wire        is_amo_in,
    output reg         is_amo_out,
    input  wire [3:0]  amo_op_in,
    output reg  [3:0]  amo_op_out
);

    always @(posedge clk) begin
        if (rst | flush) begin
            is_amo_out     <= 1'b0;
            amo_op_out     <= 4'd0;
            irq_out        <= 1'b0;
            alu_y_out      <= 32'd0;
            result_out     <= 32'd0;
            store_data_out <= 32'd0;
            rd_out         <= 5'd0;
            regwrite_out   <= 1'b0;
            memwrite_out   <= 1'b0;
            memtype_out    <= 3'd5;
            memsrc_out     <= 2'd0;
            pc_out         <= 32'd0;
            tval_out       <= 32'd0;
            csr_wdata_out  <= 32'd0;
            valid_out      <= 1'b0;
            inst_out       <= 32'd0;
            xcpt_out       <= 1'b0;
            cause_out      <= 4'd0;
            csrop_out      <= 3'd0;
            is_csr_out     <= 1'b0;
            is_mret_out    <= 1'b0;
        end else begin
            is_amo_out     <= is_amo_in;
            amo_op_out     <= amo_op_in;
            irq_out        <= irq_in;
            alu_y_out      <= alu_y_in;
            result_out     <= result_in;
            store_data_out <= store_data_in;
            rd_out         <= rd_in;
            regwrite_out   <= regwrite_in;
            memwrite_out   <= memwrite_in;
            memtype_out    <= memtype_in;
            memsrc_out     <= memsrc_in;
            pc_out         <= pc_in;
            tval_out       <= tval_in;
            csr_wdata_out  <= csr_wdata_in;
            valid_out      <= valid_in;
            inst_out       <= inst_in;
            xcpt_out       <= xcpt_in;
            cause_out      <= cause_in;
            csrop_out      <= csrop_in;
            is_csr_out     <= is_csr_in;
            is_mret_out    <= is_mret_in;
        end
    end

endmodule

module c0_mem_wb (
    input clk,
    input rst,
    input flush,
    input [31:0] result_in,
    input [31:0] mem_rdata_in,
    input [4:0] rd_in,
    input regwrite_in,
    input [1:0] memsrc_in,
    input [31:0] pc_in,
    input [31:0] tval_in,
    input [31:0] csr_wdata_in,
    input valid_in,
    input [31:0] inst_in,
    input xcpt_in,
    input [3:0] cause_in,
    input [2:0] csrop_in,
    input is_csr_in,
    input is_mret_in,
    output reg [31:0] result_out,
    output reg [31:0] mem_rdata_out,
    output reg [4:0] rd_out,
    output reg regwrite_out,
    output reg [1:0] memsrc_out,
    output reg [31:0] pc_out,
    output reg [31:0] tval_out,
    output reg [31:0] csr_wdata_out,
    output reg valid_out,
    output reg [31:0] inst_out,
    output reg xcpt_out,
    output reg [3:0] cause_out,
    output reg [2:0] csrop_out,
    output reg is_csr_out,
    output reg is_mret_out,
    input irq_in,
    output reg irq_out
);

    always @(posedge clk) begin
        if (rst || flush) begin
            result_out     <= 32'd0;
            mem_rdata_out  <= 32'd0;
            rd_out         <= 5'd0;
            regwrite_out   <= 1'b0;
            memsrc_out     <= 2'd0;
            pc_out         <= 32'd0;
            tval_out       <= 32'd0;
            csr_wdata_out  <= 32'd0;
            valid_out      <= 1'b0;
            inst_out       <= 32'd0;
            xcpt_out       <= 1'b0;
            cause_out      <= 4'd0;
            csrop_out      <= 3'd0;
            is_csr_out     <= 1'b0;
            is_mret_out    <= 1'b0;
            irq_out        <= 1'b0;
        end else begin
            result_out     <= result_in;
            mem_rdata_out  <= mem_rdata_in;
            rd_out         <= rd_in;
            regwrite_out   <= regwrite_in;
            memsrc_out     <= memsrc_in;
            pc_out         <= pc_in;
            tval_out       <= tval_in;
            csr_wdata_out  <= csr_wdata_in;
            valid_out      <= valid_in;
            inst_out       <= inst_in;
            xcpt_out       <= xcpt_in;
            cause_out      <= cause_in;
            csrop_out      <= csrop_in;
            is_csr_out     <= is_csr_in;
            is_mret_out    <= is_mret_in;
            irq_out        <= irq_in;
        end
    end

endmodule

module c0_wb_mux (
    input      wire [1:0]  memsrc,
    input      wire [31:0] alu_y,
    input      wire [31:0] mem_rdata,
    input      wire [31:0] pc_plus4,
    input      wire [31:0] imm,
    output     wire [31:0] wdata
);

    reg [31:0] sel_data;

    always @* begin
        case (memsrc)
            2'b00:   sel_data = alu_y;       // FROM_ALU
            2'b01:   sel_data = mem_rdata;   // FROM_MEMORY
            2'b10:   sel_data = pc_plus4;   // FROM_PC
            2'b11:   sel_data = imm;         // FROM_IMMEDIATE
            default: sel_data = alu_y;
        endcase
    end

    assign wdata = sel_data;

endmodule

module c0_md_decode (
    input  wire [31:0] inst,
    output wire [3:0]  mdop
);

    wire md_inst;

    assign md_inst = (inst[6:0] == 7'b0110011) && (inst[31:25] == 7'b0000001);

    assign mdop = md_inst ? {1'b1, inst[14:12]} : 4'b0000;

endmodule

module c0_booth_mul (
    input        clk,
    input        rst,
    input        start,
    input  [31:0] a,
    input  [31:0] b,
    input        a_signed,
    input        b_signed,
    output       done,
    output [31:0] lo,
    output [31:0] hi
);

    localparam [1:0] IDLE = 2'd0;
    localparam [1:0] RUN  = 2'd1;
    localparam [1:0] DONE = 2'd2;

    reg  [1:0]  state;
    reg  [32:0] M;
    reg  [33:0] Q;
    reg  [35:0] ACC;
    reg         QM;
    reg  [5:0]  cnt;

    wire [35:0] MX  = {M[32], M[32], M[32], M};
    wire [35:0] M2X = {MX[34:0], 1'b0};
    wire [2:0]  grp = {Q[1], Q[0], QM};

    reg [35:0] T;

    always @* begin
        case (grp)
            3'b000,
            3'b111: T = ACC;
            3'b001,
            3'b010: T = ACC + MX;
            3'b011:   T = ACC + M2X;
            3'b100:   T = ACC - M2X;
            3'b101,
            3'b110: T = ACC - MX;
            default:  T = ACC;
        endcase
    end

    assign done = (state == DONE);
    assign lo   = (state == DONE) ? Q[31:0]        : 32'd0;
    assign hi   = (state == DONE) ? {ACC[29:0], Q[33:32]} : 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            M     <= 33'd0;
            Q     <= 34'd0;
            ACC   <= 36'd0;
            QM    <= 1'b0;
            cnt   <= 6'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        M     <= {a[31] & a_signed, a[31:0]};
                        Q     <= {b[31] & b_signed, b[31] & b_signed, b[31:0]};
                        ACC   <= 36'd0;
                        QM    <= 1'b0;
                        cnt   <= 6'd0;
                        state <= RUN;
                    end
                end
                RUN: begin
                    ACC <= {T[35], T[35], T[35:2]};
                    Q   <= {T[1:0], Q[33:2]};
                    QM  <= Q[1];
                    cnt <= cnt + 6'd1;
                    if (cnt == 6'd16)
                        state <= DONE;
                end
                DONE: begin
                    state <= IDLE;
                end
                default: begin
                    state <= IDLE;
                    M     <= 33'd0;
                    Q     <= 34'd0;
                    ACC   <= 36'd0;
                    QM    <= 1'b0;
                    cnt   <= 6'd0;
                end
            endcase
        end
    end

endmodule

module c0_iter_div (
    input clk,
    input rst,
    input start,
    input [31:0] a,
    input [31:0] b,
    input is_signed,
    output done,
    output [31:0] quotient,
    output [31:0] remainder
);

    localparam [1:0] IDLE = 2'd0,
                     RUN  = 2'd1,
                     DONE = 2'd2;

    reg [1:0]  state;
    reg [32:0] R;
    reg [31:0] Q;
    reg [31:0] D;
    reg [31:0] A_reg;
    reg        neg_q;
    reg        neg_r;
    reg        by_zero;
    reg [5:0]  cnt;

    wire [31:0] neg_a  = ~a + 32'd1;
    wire [31:0] neg_b  = ~b + 32'd1;
    wire        a_neg  = is_signed & a[31];
    wire        b_neg  = is_signed & b[31];

    wire [32:0] S     = {R[31:0], Q[31]};
    wire [32:0] Dext  = {1'b0, D};
    wire        ge    = (S >= Dext);
    wire        q_bit = ge;
    wire [32:0] Rstep = ge ? (S - Dext) : S;

    assign done = (state == DONE);

    assign quotient = (state != DONE) ? 32'd0 :
                      (by_zero ? 32'hFFFF_FFFF :
                                 (neg_q ? (~Q + 32'd1) : Q));

    assign remainder = (state != DONE) ? 32'd0 :
                       (by_zero ? A_reg :
                                   (neg_r ? (~R[31:0] + 32'd1) : R[31:0]));

    always @(posedge clk) begin
        if (rst) begin
            state   <= IDLE;
            R       <= 33'd0;
            Q       <= 32'd0;
            D       <= 32'd0;
            A_reg   <= 32'd0;
            neg_q   <= 1'b0;
            neg_r   <= 1'b0;
            by_zero <= 1'b0;
            cnt     <= 6'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        Q       <= a_neg ? neg_a : a;
                        D       <= b_neg ? neg_b : b;
                        R       <= 33'd0;
                        A_reg   <= a;
                        neg_q   <= is_signed & (a[31] ^ b[31]);
                        neg_r   <= a_neg;
                        by_zero <= (b == 32'd0);
                        cnt     <= 6'd0;
                        state   <= RUN;
                    end
                end

                RUN: begin
                    R     <= Rstep;
                    Q     <= {Q[30:0], q_bit};
                    cnt   <= cnt + 6'd1;
                    state <= (cnt == 6'd31) ? DONE : RUN;
                end

                DONE: begin
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module c0_md_ctrl (
    input  wire [3:0]  mdop,
    input  wire        mul_done,
    input  wire        div_done,
    input  wire [31:0] mul_lo,
    input  wire [31:0] mul_hi,
    input  wire [31:0] quotient,
    input  wire [31:0] remainder,
    output wire        is_md,
    output wire        start_mul,
    output wire        start_div,
    output wire        mul_a_signed,
    output wire        mul_b_signed,
    output wire        div_signed,
    output wire        busy,
    output reg  [31:0] md_result
);

    wire is_mul;
    wire is_div;
    wire md_done;

    assign is_md        = mdop[3];
    assign is_mul       = mdop[3] & ~mdop[2];
    assign is_div       = mdop[3] &  mdop[2];
    assign start_mul    = is_md & ~mdop[2];
    assign start_div    = is_md &  mdop[2];

    assign mul_a_signed = (mdop == 4'b1000) | (mdop == 4'b1001) | (mdop == 4'b1010);
    assign mul_b_signed = (mdop == 4'b1000) | (mdop == 4'b1001);
    assign div_signed   = (mdop == 4'b1100) | (mdop == 4'b1110);

    assign md_done      = start_mul ? mul_done : (start_div ? div_done : 1'b0);
    assign busy         = is_md & ~md_done;

    always @(*) begin
        case (mdop)
            4'b0000: md_result = 32'd0;
            4'b0001: md_result = 32'd0;
            4'b0010: md_result = 32'd0;
            4'b0011: md_result = 32'd0;
            4'b0100: md_result = 32'd0;
            4'b0101: md_result = 32'd0;
            4'b0110: md_result = 32'd0;
            4'b0111: md_result = 32'd0;
            4'b1000: md_result = mul_lo;
            4'b1001: md_result = mul_hi;
            4'b1010: md_result = mul_hi;
            4'b1011: md_result = mul_hi;
            4'b1100: md_result = quotient;
            4'b1101: md_result = quotient;
            4'b1110: md_result = remainder;
            4'b1111: md_result = remainder;
            default: md_result = 32'd0;
        endcase
    end

endmodule

module c0_alu_md_mux (
    input  wire [31:0] from_alu,
    input  wire [31:0] from_md,
    input  wire        sel,
    output wire [31:0] y
);

    assign y = sel ? from_md : from_alu;

endmodule

module c0_regwrite_merge (
    input  wire ctrl_regwrite,
    input  wire is_csr,
    input  wire is_amo,
    output wire regwrite
);
    assign regwrite = ctrl_regwrite | is_csr | is_amo;
endmodule

module c0_csr_operand (
    input  wire [31:0] rs1_value,
    input  wire [4:0]  rs1_field,
    input  wire        use_imm,
    output wire [31:0] csr_wdata
);

    assign csr_wdata = use_imm ? {27'd0, rs1_field} : rs1_value;

endmodule

module c0_md_reset (
    input  sys_reset,
    input  kill,
    output unit_reset
);

assign unit_reset = sys_reset | kill;

endmodule

module c0_kill_gate (
    input  wire        regwrite,
    input  wire        memwrite,
    input  wire        kill_wb,
    input  wire        kill_mem,
    output wire        regwrite_out,
    output wire        memwrite_out
);

    assign regwrite_out = regwrite & ~kill_wb;
    assign memwrite_out = memwrite & ~kill_mem;

endmodule

module c0_wb_csr_mux (
    input  wire [31:0] from_wb,
    input  wire [31:0] from_csr,
    input  wire        sel,
    output wire [31:0] y
);

    assign y = sel ? from_csr : from_wb;

endmodule

module c0_csr_inflight (
    input  wire ex_is_csr,
    input  wire ex_is_mret,
    input  wire mem_is_csr,
    input  wire mem_is_mret,
    input  wire wb_is_csr,
    input  wire wb_is_mret,
    output wire busy
);

    assign busy = ex_is_csr  | ex_is_mret  |
                  mem_is_csr | mem_is_mret |
                  wb_is_csr  | wb_is_mret;

endmodule

module c0_irq_gate (
    input valid,
    input dec_xcpt,
    input [3:0] dec_cause,
    input pending,
    input [3:0] irq_cause,
    input busy,
    output xcpt,
    output [3:0] cause,
    output irq
);

    wire take;

    assign take = valid & pending & ~busy;

    assign irq = take;
    assign xcpt = take | dec_xcpt;
    assign cause = take ? irq_cause : dec_cause;

endmodule

module c0_fetch_next_word (
    input  [31:0] pc,
    output [31:0] hi_addr
);

assign hi_addr = pc + 32'd4;

endmodule

module c0_fetch_align (
    input  [31:0] pc,
    input  [31:0] word_lo,
    input  [31:0] word_hi,
    output [31:0] inst,
    output        is16
);

    wire pc_bit1;
    assign pc_bit1 = pc[1];

    reg [31:0] inst_reg;
    always @* begin
        if (pc_bit1 == 1'b0) begin
            inst_reg = word_lo;
        end else begin
            // inst = {word_hi[15:0], word_lo[31:16]}
            inst_reg = {word_hi[15:0], word_lo[31:16]};
        end
    end

    assign inst = inst_reg;
    assign is16 = (inst[1:0] != 2'b11);

endmodule

module c0_rvc_q0(inst, word);

input  [31:0] inst;
output [31:0] word;
reg    [31:0] word;

wire [15:0] h;
wire [2:0]  f3;
wire [4:0]  rdp;
wire [4:0]  rs1p;
wire [4:0]  rs2p;
wire [9:0]  imm10;
wire [6:0]  imm7;

assign h     = {inst[15:2], 2'b00};
assign f3    = h[15:13];
assign rdp   = {2'b01, h[4:2]};
assign rs1p  = {2'b01, h[9:7]};
assign rs2p  = {2'b01, h[4:2]};
assign imm10 = {h[10:7], h[12:11], h[5], h[6], 2'b00};
assign imm7  = {h[5], h[12:10], h[6], 2'b00};

always @* begin
    case (f3)
        3'b000: begin
            if (imm10 == 10'd0)
                word = {16'b0, h};
            else
                word = {2'b00, imm10, 5'd2, 3'b000, rdp, 7'b0010011};
        end
        3'b010: begin
            word = {5'd0, imm7, rs1p, 3'b010, rdp, 7'b0000011};
        end
        3'b110: begin
            word = {5'd0, imm7[6:5], rs2p, rs1p, 3'b010, imm7[4:0], 7'b0100011};
        end
        3'b001: begin
            word = {16'b0, h};
        end
        3'b011: begin
            word = {16'b0, h};
        end
        3'b100: begin
            word = {16'b0, h};
        end
        3'b101: begin
            word = {16'b0, h};
        end
        3'b111: begin
            word = {16'b0, h};
        end
        default: begin
            word = {16'b0, h};
        end
    endcase
end

endmodule

module c0_rvc_q1 (
  input  [31:0] inst,
  output [31:0] word
);

  // Compressed instruction h = {inst[15:2], 2'b01}
  wire [15:0] h = {inst[15:2], 2'b01};

  // Common fields
  wire [2:0] f3 = h[15:13];
  wire [4:0] rd = h[11:7];

  // Immediate fields
  wire [5:0] imm6      = {h[12], h[6:2]};
  wire [11:0] simm12   = {{6{imm6[5]}}, imm6};        // sign-extend imm6 to 12

  // Compact register fields (f3 == 100)
  wire [2:0] rdq_field = h[9:7];
  wire [2:0] rs2_field = h[4:2];
  wire [4:0] rdq       = {2'b01, rdq_field};         // rdq = rdq_field + 8
  wire [4:0] rs2q      = {2'b01, rs2_field};         // rs2q = rs2_field + 8
  wire [4:0] shamt     = h[6:2];

  // J-type (C.JAL / C.J)
  wire [11:0] off12_j  = {h[12], h[8], h[10:9], h[6], h[7], h[2], h[11], h[5:3], 1'b0};
  wire [20:0] joff21   = {{9{off12_j[11]}}, off12_j};

  // B-type (C.BEQZ / C.BNEZ)
  wire [8:0]  off9_b   = {h[12], h[6:5], h[2], h[11:10], h[4:3], 1'b0};
  wire [12:0] boff13   = {{4{off9_b[8]}}, off9_b};
  wire [4:0]  rs1q_b   = {2'b01, h[9:7]};           // rs1q = h[9:7] + 8

  // ADDI16SP / LUI
  wire [9:0]  imm10_sp = {h[12], h[4:3], h[5], h[2], h[6], 4'b0000};
  wire [11:0] simm12_sp= {{2{imm10_sp[9]}}, imm10_sp}; // sign-extend imm10 to 12
  wire [19:0] imm20_lui= {{14{imm6[5]}}, imm6};      // sign-extend imm6 to 20

  reg [31:0] word_r;

  always @* begin
    // Default: reserved or not available -> zero-extend h
    word_r = {16'b0000000000000000, h};

    case (f3)
      // f3 = 000: C.ADDI and C.NOP
      3'b000: begin
        // I-type addi rd, rd, simm12 (opcode 0010011, funct3 000)
        word_r = {simm12, rd, 3'b000, rd, 7'b0010011};
      end

      // f3 = 001: C.JAL
      3'b001: begin
        // J-type jal rd = x1, immediate joff21 (opcode 1101111)
        word_r = {joff21[20], joff21[10:1], joff21[11], joff21[19:12], 5'd1, 7'b1101111};
      end

      // f3 = 010: C.LI
      3'b010: begin
        // I-type addi rd, x0, simm12 (opcode 0010011, funct3 000)
        word_r = {simm12, 5'd0, 3'b000, rd, 7'b0010011};
      end

      // f3 = 011: C.ADDI16SP or C.LUI
      3'b011: begin
        if (rd == 5'd2) begin
          // C.ADDI16SP
          if (imm10_sp == 10'b0000000000) begin
            // reserved -> zero-extend h
            word_r = {16'b0000000000000000, h};
          end else begin
            // I-type addi x2, x2, simm12_sp (opcode 0010011, funct3 000)
            word_r = {simm12_sp, 5'd2, 3'b000, 5'd2, 7'b0010011};
          end
        end else begin
          // C.LUI
          if (imm6 == 6'b000000) begin
            // reserved -> zero-extend h
            word_r = {16'b0000000000000000, h};
          end else begin
            // U-type lui rd with imm20_lui (opcode 0110111)
            word_r = {imm20_lui, rd, 7'b0110111};
          end
        end
      end

      // f3 = 100: arithmetic group on compact registers
      3'b100: begin
        case (h[11:10])
          // 00: C.SRLI
          2'b00: begin
            if (h[12] == 1'b1) begin
              // reserved -> zero-extend h
              word_r = {16'b0000000000000000, h};
            end else begin
              // I-type srli rdq, rdq, shamt: immediate {7'b0000000, shamt} (opcode 0010011, funct3 101)
              word_r = {7'b0000000, shamt, rdq, 3'b101, rdq, 7'b0010011};
            end
          end

          // 01: C.SRAI
          2'b01: begin
            if (h[12] == 1'b1) begin
              // reserved -> zero-extend h
              word_r = {16'b0000000000000000, h};
            end else begin
              // I-type srai rdq, rdq, shamt: immediate {7'b0100000, shamt} (opcode 0010011, funct3 101)
              word_r = {7'b0100000, shamt, rdq, 3'b101, rdq, 7'b0010011};
            end
          end

          // 10: C.ANDI
          2'b10: begin
            // I-type andi rdq, rdq, simm12 (opcode 0010011, funct3 111)
            word_r = {simm12, rdq, 3'b111, rdq, 7'b0010011};
          end

          // 11: R-type group
          2'b11: begin
            if (h[12] == 1'b1) begin
              // reserved -> zero-extend h
              word_r = {16'b0000000000000000, h};
            end else begin
              case (h[6:5])
                // 00: sub
                2'b00: begin
                  // R-type: funct7 0100000, rs2 rs2q, rs1 rdq, funct3 000, rd rdq, opcode 0110011
                  word_r = {7'b0100000, rs2q, rdq, 3'b000, rdq, 7'b0110011};
                end
                // 01: xor
                2'b01: begin
                  // R-type: funct7 0000000, funct3 100
                  word_r = {7'b0000000, rs2q, rdq, 3'b100, rdq, 7'b0110011};
                end
                // 10: or
                2'b10: begin
                  // R-type: funct7 0000000, funct3 110
                  word_r = {7'b0000000, rs2q, rdq, 3'b110, rdq, 7'b0110011};
                end
                // 11: and
                2'b11: begin
                  // R-type: funct7 0000000, funct3 111
                  word_r = {7'b0000000, rs2q, rdq, 3'b111, rdq, 7'b0110011};
                end
                default: begin
                  word_r = {16'b0000000000000000, h};
                end
              endcase
            end
          end

          default: begin
            word_r = {16'b0000000000000000, h};
          end
        endcase
      end

      // f3 = 101: C.J
      3'b101: begin
        // J-type jal rd = x0, immediate joff21 (opcode 1101111)
        word_r = {joff21[20], joff21[10:1], joff21[11], joff21[19:12], 5'd0, 7'b1101111};
      end

      // f3 = 110: C.BEQZ
      3'b110: begin
        // B-type branch: immediate boff13, rs1 rs1q_b, rs2 x0, opcode 1100011, funct3 000 (beq)
        word_r = {boff13[12], boff13[10:5], 5'd0, rs1q_b, 3'b000, boff13[4:1], boff13[11], 7'b1100011};
      end

      // f3 = 111: C.BNEZ
      3'b111: begin
        // B-type branch: immediate boff13, rs1 rs1q_b, rs2 x0, opcode 1100011, funct3 001 (bne)
        word_r = {boff13[12], boff13[10:5], 5'd0, rs1q_b, 3'b001, boff13[4:1], boff13[11], 7'b1100011};
      end

      default: begin
        word_r = {16'b0000000000000000, h};
      end
    endcase
  end

  assign word = word_r;

endmodule

module c0_rvc_q2 (
  input  [31:0] inst,
  output [31:0] word
);

  // Build h = {inst[15:2], 2'b10}
  wire [15:0] h;
  assign h = {inst[15:2], 2'b10};

  // Fields
  wire [2:0] f3;
  wire [4:0] rd;
  wire [4:0] rs2;
  assign f3 = h[15:13];
  assign rd = h[11:7];
  assign rs2 = h[6:2];

  // Decoded immediates
  wire [7:0]  off8_lwsp;
  wire [7:0]  off8_swsp;
  wire [4:0]  shamt;
  assign off8_lwsp = {h[3:2], h[12], h[6:4], 2'b00};
  assign off8_swsp = {h[8:7], h[12:9], 2'b00};
  assign shamt      = h[6:2];

  reg [31:0] word_r;

  always @* begin
    word_r = {16'b0000000000000000, h}; // default: reserved/not available -> zero-extend h

    case (f3)
      3'b000: begin
        // C.SLLI: reserved if h[12] is 1
        if (h[12] == 1'b0) begin
          // I-type slli rd, rd, shamt: imm = {7'b0000000, shamt}, opcode 0010011, funct3 001, rs1 = rd
          word_r = {{7'b0000000}, shamt, rd, 3'b001, rd, 7'b0010011};
        end else begin
          // reserved
          word_r = {16'b0000000000000000, h};
        end
      end

      3'b010: begin
        // C.LWSP: reserved when rd == 0
        if (rd == 5'b00000) begin
          word_r = {16'b0000000000000000, h};
        end else begin
          // I-type lw rd, off8_lwsp(x2): imm zero-extended to 12 bits = {4'b0000, off8_lwsp}, rs1 = x2, funct3 010, opcode 0000011
          word_r = {{4'b0000}, off8_lwsp, 5'd2, 3'b010, rd, 7'b0000011};
        end
      end

      3'b100: begin
        if (h[12] == 1'b0) begin
          if (rs2 == 5'b00000) begin
            // C.JR: reserved when rd == 0
            if (rd == 5'b00000) begin
              word_r = {16'b0000000000000000, h};
            end else begin
              // I-type jalr x0, 0(rd): opcode 1100111, funct3 000, immediate 0, rd = x0, rs1 = rd
              word_r = {12'b000000000000, rd, 3'b000, 5'd0, 7'b1100111};
            end
          end else begin
            // C.MV: R-type add rd, x0, rs2
            word_r = {7'b0000000, rs2, 5'd0, 3'b000, rd, 7'b0110011};
          end
        end else begin // h[12] == 1
          if (rs2 == 5'b00000) begin
            if (rd == 5'b00000) begin
              // C.EBREAK
              word_r = 32'h00100073;
            end else begin
              // C.JALR: I-type jalr x1, 0(rd)
              word_r = {12'b000000000000, rd, 3'b000, 5'd1, 7'b1100111};
            end
          end else begin
            // C.ADD: R-type add rd, rd, rs2
            word_r = {7'b0000000, rs2, rd, 3'b000, rd, 7'b0110011};
          end
        end
      end

      3'b110: begin
        // C.SWSP: S-type sw rs2, off8_swsp(x2)
        // imm = {4'b0000, off8_swsp}, split into imm[11:5] and imm[4:0]
        word_r = {{4'b0000}, off8_swsp[7:5], rs2, 5'd2, 3'b010, off8_swsp[4:0], 7'b0100011};
      end

      3'b001,
      3'b011,
      3'b101,
      3'b111: begin
        // reserved or needs floating-point extension
        word_r = {16'b0000000000000000, h};
      end

      default: begin
        word_r = {16'b0000000000000000, h};
      end
    endcase
  end

  assign word = word_r;

endmodule

module c0_rvc_select (
  input  [31:0] inst,
  input  [31:0] q0,
  input  [31:0] q1,
  input  [31:0] q2,
  output [31:0] inst_out
);

  reg [31:0] inst_out_r;

  always @* begin
    case (inst[1:0])
      2'b00:   inst_out_r = q0;
      2'b01:   inst_out_r = q1;
      2'b10:   inst_out_r = q2;
      2'b11:   inst_out_r = inst;
      default: inst_out_r = inst;
    endcase
  end

  assign inst_out = inst_out_r;

endmodule

module c0_io_load(
  input  [31:0] raw,
  input  [2:0]  memtype,
  output [31:0] rdata
);

  wire [7:0]  byte_raw  = raw[7:0];
  wire [15:0] half_raw  = raw[15:0];
  wire        byte_sign = byte_raw[7];
  wire        half_sign = half_raw[15];
  wire [23:0] byte_sext = {24{byte_sign}};
  wire [15:0] half_sext = {16{half_sign}};
  
  reg [31:0] rdata_r;
  
  always @* begin
    case (memtype)
      3'b000: // MEM_BYTE - sign extended
        rdata_r = {{24{byte_raw[7]}}, byte_raw};
      3'b001: // MEM_HALF - sign extended
        rdata_r = {{16{half_raw[15]}}, half_raw};
      3'b010: // MEM_WORD
        rdata_r = raw;
      3'b011: // MEM_BYTE_U - zero extended
        rdata_r = {24'b0, byte_raw};
      3'b100: // MEM_HALF_U - zero extended
        rdata_r = {16'b0, half_raw};
      3'b101: // NO_ACCESS - behaves as MEM_WORD
        rdata_r = raw;
      3'b110: // reserved - behaves as MEM_WORD
        rdata_r = raw;
      3'b111: // reserved - behaves as MEM_WORD
        rdata_r = raw;
      default: // should never happen
        rdata_r = raw;
    endcase
  end
  
  assign rdata = rdata_r;

endmodule

module c0_load_sel (
  input  [31:0] from_ram,
  input  [31:0] from_io,
  input         sel,
  output [31:0] y
);

  assign y = sel ? from_io : from_ram;

endmodule

module c0_amo_ctl (
    input        is_amo,
    input  [2:0] immsel,
    input        alusrc,
    input        arith,
    input  [2:0] opsel,
    input        asel,
    input  [2:0] memtype,
    input  [1:0] memsrc,
    input        memwrite,
    output [2:0] immsel_out,
    output       alusrc_out,
    output       arith_out,
    output [2:0] opsel_out,
    output       asel_out,
    output [2:0] memtype_out,
    output [1:0] memsrc_out,
    output       memwrite_out
);

    assign immsel_out    = is_amo ? 3'b101 : immsel;
    assign alusrc_out    = is_amo ? 1'b1   : alusrc;
    assign arith_out     = is_amo ? 1'b0   : arith;
    assign opsel_out     = is_amo ? 3'b000 : opsel;
    assign asel_out      = is_amo ? 1'b0   : asel;
    assign memtype_out   = is_amo ? 3'b010 : memtype;
    assign memsrc_out    = is_amo ? 2'b01  : memsrc;
    assign memwrite_out  = is_amo ? 1'b0   : memwrite;

endmodule

module c0_amo_active (
    input valid,
    input is_amo,
    input sel_ram,
    input xcpt,
    input kill,
    output active
);

    assign active = valid & is_amo & sel_ram & (~xcpt) & (~kill);

endmodule

module c0_amo_core (
    input  wire        active,
    input  wire        is_amo,
    input  wire [3:0]  amo_op,
    input  wire [31:0] rs2,
    input  wire [31:0] old,
    input  wire        kill,
    input  wire        match,
    output reg  [31:0] wdata,
    output reg         we,
    output reg         use_sc,
    output reg  [31:0] sc_result,
    output reg         set_rsv,
    output reg         clr_rsv
);

    localparam [3:0] AMO_NONE  = 4'b0000;
    localparam [3:0] AMO_LR    = 4'b0001;
    localparam [3:0] AMO_SC    = 4'b0010;
    localparam [3:0] AMO_SWAP  = 4'b0011;
    localparam [3:0] AMO_ADD   = 4'b0100;
    localparam [3:0] AMO_XOR   = 4'b0101;
    localparam [3:0] AMO_AND   = 4'b0110;
    localparam [3:0] AMO_OR    = 4'b0111;
    localparam [3:0] AMO_MIN   = 4'b1000;
    localparam [3:0] AMO_MAX   = 4'b1001;
    localparam [3:0] AMO_MINU  = 4'b1010;
    localparam [3:0] AMO_MAXU  = 4'b1011;

    always @* begin
        // Default assignments
        wdata    = 32'd0;
        we       = 1'b0;
        use_sc   = 1'b0;
        sc_result= 32'd0;
        set_rsv  = 1'b0;
        clr_rsv  = 1'b0;

        // use_sc: 1 when is_amo and amo_op is AMO_SC
        use_sc = is_amo && (amo_op == AMO_SC);

        // sc_result: 0 when match, else 1
        sc_result = match ? 32'd0 : 32'd1;

        // set_rsv: active and amo_op == AMO_LR
        set_rsv = active && (amo_op == AMO_LR);

        // clr_rsv: kill OR (active and amo_op == AMO_SC)
        clr_rsv = kill || (active && (amo_op == AMO_SC));

        // wdata depends on amo_op (combinational, independent of active)
        case (amo_op)
            AMO_SWAP:  wdata = rs2;
            AMO_ADD:   wdata = old + rs2;
            AMO_XOR:   wdata = old ^ rs2;
            AMO_AND:   wdata = old & rs2;
            AMO_OR:    wdata = old | rs2;
            AMO_MIN:   wdata = ($signed(old) < $signed(rs2)) ? old : rs2;
            AMO_MAX:   wdata = ($signed(old) > $signed(rs2)) ? old : rs2;
            AMO_MINU:  wdata = (old < rs2) ? old : rs2;
            AMO_MAXU:  wdata = (old > rs2) ? old : rs2;
            AMO_SC:    wdata = rs2;
            default:   wdata = rs2; // AMO_NONE, AMO_LR, reserved
        endcase

        // we depends on active and amo_op
        if (active) begin
            case (amo_op)
                AMO_SWAP,
                AMO_ADD,
                AMO_XOR,
                AMO_AND,
                AMO_OR,
                AMO_MIN,
                AMO_MAX,
                AMO_MINU,
                AMO_MAXU: we = 1'b1;
                AMO_SC:   we = match;
                default:  we = 1'b0;
            endcase
        end
    end

endmodule

module c0_amo_match (
    input [31:0] addr,
    input [31:0] rsv_addr,
    input rsv_valid,
    output match
);

    assign match = rsv_valid & (addr[31:2] == rsv_addr[31:2]);

endmodule

module c0_wdata_sel (
    input [31:0] from_store,
    input [31:0] from_amo,
    input sel,
    output [31:0] y
);

assign y = sel ? from_amo : from_store;

endmodule

module c0_sc_sel (
    input [31:0] from_load,
    input [31:0] from_sc,
    input sel,
    output [31:0] y
);

    assign y = sel ? from_sc : from_load;

endmodule

module c0_ram_we_merge (
    input store_we,
    input amo_we,
    output we
);

    assign we = store_we | amo_we;

endmodule

module c0_mem_req (
    input  wire        valid,
    input  wire        xcpt,
    input  wire        kill,
    input  wire [1:0]  memsrc,
    input  wire        memwrite,
    input  wire        is_amo,
    output wire        req
);

    assign req = valid & ~xcpt & ~kill & ( (memsrc == 2'b01) | memwrite | is_amo );

endmodule

module c0_pmp_regs16 (
    input          clk,
    input          rst,
    input          we,
    input  [31:0]  inst,
    input  [5:0]   sel,
    input  [31:0]  nval,
    output [31:0]  rdata,
    output [127:0] cfg_all,
    output [511:0] addr_all
);

    reg [7:0]  cfg  [0:15];
    reg [31:0] addr [0:15];

    wire [11:0] a;
    wire        wr;
    reg  [31:0] rdata_r;

    integer i, j;

    assign a  = inst[31:20];
    assign wr = we && ((sel == 6'd42) || (sel == 6'd43) || (sel == 6'd45));
    assign rdata = rdata_r;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : gen_cfg_out
            assign cfg_all[8*g + 7 : 8*g] = cfg[g];
        end
        for (g = 0; g < 16; g = g + 1) begin : gen_addr_out
            assign addr_all[32*g + 31 : 32*g] = addr[g];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 16; i = i + 1) begin
                cfg[i]  <= 8'd0;
                addr[i] <= 32'd0;
            end
        end else begin
            if (wr) begin
                for (i = 0; i < 4; i = i + 1) begin
                    if (a == (12'h3A0 + i[11:0])) begin
                        for (j = 0; j < 4; j = j + 1) begin
                            if (cfg[i*4 + j][7] == 1'b1) begin
                                cfg[i*4 + j] <= cfg[i*4 + j];
                            end else if ((nval[8*j + 0] == 1'b0) && (nval[8*j + 1] == 1'b1)) begin
                                cfg[i*4 + j] <= cfg[i*4 + j];
                            end else begin
                                cfg[i*4 + j] <= nval[8*j +: 8] & 8'h9F;
                            end
                        end
                    end
                end
                for (i = 0; i < 16; i = i + 1) begin
                    if (a == (12'h3B0 + i[11:0])) begin
                        if (cfg[i][7] == 1'b1) begin
                            addr[i] <= addr[i];
                        end else if ((i < 15) && (cfg[i+1][7] == 1'b1) && (cfg[i+1][4:3] == 2'b01)) begin
                            addr[i] <= addr[i];
                        end else begin
                            addr[i] <= nval;
                        end
                    end
                end
            end
        end
    end

    always @* begin
        rdata_r = 32'd0;
        if ((a >= 12'h3A0) && (a <= 12'h3A3)) begin
            rdata_r = {cfg[{a[1:0], 2'b11}],
                       cfg[{a[1:0], 2'b10}],
                       cfg[{a[1:0], 2'b01}],
                       cfg[{a[1:0], 2'b00}]};
        end else if ((a >= 12'h3B0) && (a <= 12'h3BF)) begin
            rdata_r = addr[a[3:0]];
        end
    end

endmodule

module c0_pmp_k (
    input  wire        store,      // 1-bit input
    output wire [1:0]  kind_f,     // 2-bit output
    output wire [1:0]  kind_d,     // 2-bit output
    output wire [1:0]  kind_l,     // 2-bit output
    output wire [1:0]  priv_s,     // 2-bit output
    output wire        one         // 1-bit output
);

// Constant assignments
assign kind_f = 2'b00;          // always 00
assign kind_l = 2'b01;          // always 01
assign priv_s = 2'b01;          // always 01
assign one    = 1'b1;           // always 1

// kind_d depends on store
assign kind_d = store ? 2'b10 : 2'b01;

endmodule

module c0_pmp_check_ilo(
    input  [31:0] pa,
    input  [1:0]  kind,
    input  [1:0]  priv,
    input         en,
    input  [127:0] cfg_all,
    input  [511:0] addr_all,
    output reg    deny
);

    integer i;
    reg [31:0] w;
    reg [31:0] addr_i;
    reg [7:0]  c;
    reg [1:0]  mode;
    reg [31:0] prev;
    reg [31:0] m;
    reg        match_i;
    reg        allow_i;
    reg        locked;
    reg        found;
    reg        matched_allow;
    reg        matched_locked;

    always @* begin
        deny = 1'b0;                 // default
        if (!en) begin
            deny = 1'b0;
        end else begin
    w = {2'b0, pa[31:2]};
    found = 1'b0;
            matched_allow = 1'b0;
            matched_locked = 1'b0;

            for (i = 0; i < 16; i = i + 1) begin
                if (!found) begin
                    c      = cfg_all[8*i +: 8];
                    mode   = c[4:3];
                    addr_i = addr_all[32*i +: 32];
                    prev   = (i == 0) ? 32'd0 : addr_all[32*(i-1) +: 32];

                    // compute match
                    case (mode)
                        2'b01: begin // mode 1
                            match_i = (prev <= w) && (w < addr_i);
                        end
                        2'b10: begin // mode 2
                            match_i = (w == addr_i);
                        end
                        2'b11: begin // mode 3
                            m = addr_i ^ (addr_i + 32'd1);
                            match_i = ((w & ~m) == (addr_i & ~m));
                        end
                        default: match_i = 1'b0; // mode 0 never matches
                    endcase

                    // compute allow
                    case (kind)
                        2'b00: allow_i = c[2];
                        2'b01: allow_i = c[0];
                        default: allow_i = c[1]; // kind 10 or 11
                    endcase

                    locked = c[7];

                    if (match_i) begin
                        found = 1'b1;
                        matched_allow = allow_i;
                        matched_locked = locked;
                    end
                end
            end

            if (found) begin
                deny = ((priv != 2'b11) || matched_locked) && !matched_allow;
            end else begin
                deny = (priv != 2'b11);
            end
        end
    end

endmodule

