module c0_sys_decode (
    input  wire [31:0] inst,
    input  wire [1:0]  priv,
    output reg         xcpt,
    output reg [3:0]   cause,
    output reg [2:0]   csrop,
    output reg         csr_imm,
    output reg         is_csr,
    output reg         is_mret,
    output reg         is_amo,
    output reg [3:0]   amo_op
);

    wire [6:0] opcode  = inst[6:0];
    wire [2:0] funct3  = inst[14:12];
    wire [6:0] funct7  = inst[31:25];
    wire [4:0] rs1     = inst[19:15];
    wire [4:0] rs2     = inst[24:20];

    reg illegal_flag;

    always @* begin
        // Defaults
        xcpt     = 1'b0;
        cause    = 4'b0;
        csrop    = 3'b0;
        csr_imm  = 1'b0;
        is_csr   = 1'b0;
        is_mret  = 1'b0;
        is_amo   = 1'b0;
        amo_op   = 4'b0;
        illegal_flag = 1'b0;

        // Independent: is_mret
        if (inst == 32'h30200073)
            is_mret = 1'b1;

        // Independent: is_amo and amo_op
        if (opcode == 7'b0101111 && funct3 == 3'b010) begin
            case (inst[31:27])
                5'b00010: if (inst[24:20] == 5'b00000) begin is_amo = 1'b1; amo_op = 4'b0001; end // AMO_LR
                5'b00011: begin is_amo = 1'b1; amo_op = 4'b0010; end // AMO_SC
                5'b00001: begin is_amo = 1'b1; amo_op = 4'b0011; end // AMO_SWAP
                5'b00000: begin is_amo = 1'b1; amo_op = 4'b0100; end // AMO_ADD
                5'b00100: begin is_amo = 1'b1; amo_op = 4'b0101; end // AMO_XOR
                5'b01100: begin is_amo = 1'b1; amo_op = 4'b0110; end // AMO_AND
                5'b01000: begin is_amo = 1'b1; amo_op = 4'b0111; end // AMO_OR
                5'b10000: begin is_amo = 1'b1; amo_op = 4'b1000; end // AMO_MIN
                5'b10100: begin is_amo = 1'b1; amo_op = 4'b1001; end // AMO_MAX
                5'b11000: begin is_amo = 1'b1; amo_op = 4'b1010; end // AMO_MINU
                5'b11100: begin is_amo = 1'b1; amo_op = 4'b1011; end // AMO_MAXU
                default: begin is_amo = 1'b0; amo_op = 4'b0; end
            endcase
        end

        // Priority decoding for exception/CSR outputs
        // 1. Fetch-fault word
        if (opcode == 7'b0001011 && (funct3 == 3'b001 || funct3 == 3'b010)) begin
            xcpt  = 1'b1;
            cause = (funct3 == 3'b001) ? 4'd12 : 4'd1;
        end
        // 2. ebreak
        else if (inst == 32'h00100073) begin
            xcpt  = 1'b1;
            cause = 4'd3;
        end
        // 3. ecall
        else if (inst == 32'h00000073) begin
            xcpt = 1'b1;
            case (priv)
                2'b00: cause = 4'd8;
                2'b01: cause = 4'd9;
                2'b10, 2'b11: cause = 4'd11;
                default: cause = 4'd11;
            endcase
        end
        // 4. sret
        else if (inst == 32'h10200073) begin
            csrop = 3'b101;
        end
        // 5. sfence.vma
        else if (opcode == 7'b1110011 && funct3 == 3'b000 && funct7 == 7'b0001001 && inst[11:7] == 5'b00000) begin
            csrop = 3'b110;
        end
        // 6. fence.i
        else if (opcode == 7'b0001111 && funct3 == 3'b001) begin
            csrop = 3'b111;
        end
        // 7. CSR instructions
        else if (opcode == 7'b1110011 && (funct3 == 3'b001 || funct3 == 3'b010 || funct3 == 3'b011 ||
                                           funct3 == 3'b101 || funct3 == 3'b110 || funct3 == 3'b111)) begin
            is_csr  = 1'b1;
            csr_imm = funct3[2];
            case (funct3[1:0])
                2'b01: csrop = 3'b010;                       // CSR_WRITE
                2'b10: csrop = (rs1 != 5'b0) ? 3'b011 : 3'b001; // CSR_SET / CSR_READ
                2'b11: csrop = (rs1 != 5'b0) ? 3'b100 : 3'b001; // CSR_CLEAR / CSR_READ
                default: csrop = 3'b000;
            endcase
        end
        // 8. All other legal instructions (produce zeros) or illegal
        else begin
            case (opcode)
                7'b0110111: ; // LUI
                7'b0010111: ; // AUIPC
                7'b1101111: ; // JAL
                7'b1100111: if (funct3 != 3'b000) illegal_flag = 1'b1; // JALR
                7'b1100011: if (!(funct3 == 3'b000 || funct3 == 3'b001 || funct3 == 3'b100 ||
                                   funct3 == 3'b101 || funct3 == 3'b110 || funct3 == 3'b111)) illegal_flag = 1'b1; // Branch
                7'b0000011: if (!(funct3 == 3'b000 || funct3 == 3'b001 || funct3 == 3'b010 ||
                                   funct3 == 3'b100 || funct3 == 3'b101)) illegal_flag = 1'b1; // Load
                7'b0100011: if (!(funct3 == 3'b000 || funct3 == 3'b001 || funct3 == 3'b010)) illegal_flag = 1'b1; // Store
                7'b0010011: begin // Imm arithmetic
                    if (funct3 == 3'b000 || funct3 == 3'b010 || funct3 == 3'b011 ||
                        funct3 == 3'b100 || funct3 == 3'b110 || funct3 == 3'b111) ;
                    else if (funct3 == 3'b001 && funct7 == 7'b0000000) ;
                    else if (funct3 == 3'b101 && (funct7 == 7'b0000000 || funct7 == 7'b0100000)) ;
                    else illegal_flag = 1'b1;
                end
                7'b0110011: begin // Register arithmetic
                    if (funct7 == 7'b0000000) ;
                    else if (funct7 == 7'b0100000 && (funct3 == 3'b000 || funct3 == 3'b101)) ;
                    else if (funct7 == 7'b0000001) ;
                    else illegal_flag = 1'b1;
                end
                7'b0001111: if (funct3 != 3'b000) illegal_flag = 1'b1; // Fence (funct3=000)
                7'b0101111: if (!(funct3 == 3'b010 && is_amo)) illegal_flag = 1'b1; // Atomic (only legal if is_amo)
                7'b1110011: begin // System
                    if (funct3 == 3'b000) begin
                        // Only mret and wfi are legal here (others handled above)
                        if (!(inst == 32'h30200073 || inst == 32'h10500073)) illegal_flag = 1'b1;
                    end
                    else begin
                        // CSR funct3 handled above
                        illegal_flag = 1'b1;
                    end
                end
                default: illegal_flag = 1'b1;
            endcase

            if (illegal_flag) begin
                xcpt  = 1'b1;
                cause = 4'd2; // ILLEGAL_INSTRUCTION
            end
        end
    end

endmodule

module c0_ex_xcpt
(
    input  wire          id_xcpt,
    input  wire [3:0]    id_cause,
    input  wire          id_irq,
    input  wire [31:0]   inst,
    input  wire [31:0]   pc,
    input  wire [2:0]    memtype,
    input  wire          memwrite,
    input  wire [31:0]   alu_y,
    input  wire          d_pf,
    input  wire          d_af,
    input  wire          d_store,
    output wire          xcpt,
    output wire [3:0]    cause,
    output wire [31:0]   tval,
    output wire          memwrite_out
);

    // Misaligned access detection
    wire misaligned;
    assign misaligned =
        (((memtype == 3'b010) || (memtype == 3'b110) || (memtype == 3'b111)) &&
         (alu_y[1:0] != 2'b00)) ||
        (((memtype == 3'b001) || (memtype == 3'b100)) &&
         (alu_y[0] == 1'b1));

    // Priority logic
    reg          xcpt_reg;
    reg  [3:0]   cause_reg;
    reg  [31:0]  tval_reg;
    reg          memwrite_out_reg;

    always @*
    begin
        // Default values
        xcpt_reg          = 1'b0;
        cause_reg         = 4'b0;
        tval_reg          = 32'b0;
        memwrite_out_reg  = memwrite;

        if (id_xcpt)
        begin
            xcpt_reg = 1'b1;
            cause_reg = id_cause;
            if (id_irq)
                tval_reg = 32'b0;
            else
            begin
                case (id_cause)
                    4'd2: tval_reg = inst;
                    4'd3: tval_reg = pc;
                    4'd1,
                    4'd12: tval_reg = inst[20] ? (pc + 32'd2) : pc;
                    default: tval_reg = 32'b0;
                endcase
            end
        end
        else if (misaligned)
        begin
            xcpt_reg = 1'b1;
            cause_reg = d_store ? 4'd6 : 4'd4;
            tval_reg = alu_y;
        end
        else if (d_pf)
        begin
            xcpt_reg = 1'b1;
            cause_reg = d_store ? 4'd15 : 4'd13;
            tval_reg = alu_y;
        end
        else if (d_af)
        begin
            xcpt_reg = 1'b1;
            cause_reg = d_store ? 4'd7 : 4'd5;
            tval_reg = alu_y;
        end
        else
        begin
            xcpt_reg = 1'b0;
            cause_reg = 4'b0;
            tval_reg = 32'b0;
        end

        // memwrite_out is cleared when an exception is generated
        if (xcpt_reg)
            memwrite_out_reg = 1'b0;
    end

    // Drive outputs
    assign xcpt          = xcpt_reg;
    assign cause         = cause_reg;
    assign tval          = tval_reg;
    assign memwrite_out  = memwrite_out_reg;

endmodule

module c0_csr_sel2 (
    input  wire [31:0] inst,
    input  wire [2:0]  csrop,
    input  wire [1:0]  priv,
    input  wire        tvm,
    input  wire [2:0]  mcounteren,
    input  wire [2:0]  scounteren,
    output reg  [5:0]  sel,
    output reg         illegal
);

    reg        is_access, is_write, bad;
    reg [1:0]  b;

    always @* begin
        // Default assignments to avoid latches
        b = 2'd0;
        illegal = 1'b0;

        // Decode CSR address (inst[31:20]) to sel number
        case (inst[31:20])
            12'h300: sel = 6'd1;   // mstatus
            12'h301: sel = 6'd2;   // misa
            12'h302: sel = 6'd3;   // medeleg
            12'h303: sel = 6'd4;   // mideleg
            12'h304: sel = 6'd5;   // mie
            12'h305: sel = 6'd6;   // mtvec
            12'h306: sel = 6'd7;   // mcounteren
            12'h340: sel = 6'd8;   // mscratch
            12'h341: sel = 6'd9;   // mepc
            12'h342: sel = 6'd10;  // mcause
            12'h343: sel = 6'd11;  // mtval
            12'h344: sel = 6'd12;  // mip
            12'hB00: sel = 6'd13;  // mcycle
            12'hB02: sel = 6'd14;  // minstret
            12'hB80: sel = 6'd15;  // mcycleh
            12'hB82: sel = 6'd16;  // minstreth
            12'hC00: sel = 6'd17;  // cycle
            12'hC01: sel = 6'd18;  // time
            12'hC02: sel = 6'd19;  // instret
            12'hC80: sel = 6'd20;  // cycleh
            12'hC81: sel = 6'd21;  // timeh
            12'hC82: sel = 6'd22;  // instreth
            12'hF11: sel = 6'd23;  // mvendorid
            12'hF12: sel = 6'd24;  // marchid
            12'hF13: sel = 6'd25;  // mimpid
            12'hF14: sel = 6'd26;  // mhartid
            12'h100: sel = 6'd27;  // sstatus
            12'h104: sel = 6'd28;  // sie
            12'h105: sel = 6'd29;  // stvec
            12'h106: sel = 6'd30;  // scounteren
            12'h140: sel = 6'd31;  // sscratch
            12'h141: sel = 6'd32;  // sepc
            12'h142: sel = 6'd33;  // scause
            12'h143: sel = 6'd34;  // stval
            12'h144: sel = 6'd35;  // sip
            12'h180: sel = 6'd36;  // satp
            12'h7A0: sel = 6'd37;  // tselect
            12'h7A1: sel = 6'd38;  // tdata1
            12'h7A2: sel = 6'd39;  // tdata2
            12'h7A3: sel = 6'd40;  // tdata3
            12'h320: sel = 6'd41;  // mcountinhibit
            12'h3A0: sel = 6'd42;  // pmpcfg0
            12'h3B0: sel = 6'd43;  // pmpaddr0
            default: sel = 6'd0;   // no register
        endcase

        // Determine if this instruction is a CSR access or write
        is_access = (csrop == 3'b001) || (csrop == 3'b010) || (csrop == 3'b011) || (csrop == 3'b100);
        is_write  = (csrop == 3'b010) || (csrop == 3'b011) || (csrop == 3'b100);

        // Check for bad access conditions
        bad = 1'b0;
        if (sel == 6'd0) begin
            bad = 1'b1;                                 // no such register
        end else if (priv < inst[29:28]) begin          // priv < a[9:8]
            bad = 1'b1;
        end else if (is_write && inst[31:30] == 2'b11) begin // write to read-only (a[11:10]==11)
            bad = 1'b1;
        end else if (sel == 6'd36 && priv == 2'b01 && tvm) begin // satp with S-mode and TVM=1
            bad = 1'b1;
        end else if (sel >= 6'd17 && sel <= 6'd22 && priv != 2'b11) begin // counter access from non-M mode
            case (sel)
                6'd17, 6'd20: b = 2'd0; // cycle, cycleh
                6'd18, 6'd21: b = 2'd1; // time, timeh
                6'd19, 6'd22: b = 2'd2; // instret, instreth
                default:      b = 2'd0;
            endcase
            if (mcounteren[b] == 1'b0) begin
                bad = 1'b1;
            end else if (priv == 2'b00 && scounteren[b] == 1'b0) begin
                bad = 1'b1;
            end
        end

        illegal = is_access && bad;
    end

endmodule

module c0_csr_hw (
    input  [31:0] inst,
    input  [2:0]  csrop,
    input  [1:0]  priv,
    input  [5:0]  sel_in,
    input         ill_in,
    output [5:0]  sel_out,
    output        ill_out
);

    wire [11:0] a = inst[31:20];

    wire hw =
        (a == 12'h310) ||
        (a == 12'h30A) ||
        (a == 12'h31A) ||
        (a == 12'h10A) ||
        ((a >= 12'h323) && (a <= 12'h33F)) ||
        ((a >= 12'hB03) && (a <= 12'hB1F)) ||
        ((a >= 12'hB83) && (a <= 12'hB9F)) ||
        ((a >= 12'hC03) && (a <= 12'hC1F)) ||
        ((a >= 12'hC83) && (a <= 12'hC9F));

    wire pmp_a = ((a >= 12'h3A1) && (a <= 12'h3A3));
    wire pmp_b = ((a >= 12'h3B1) && (a <= 12'h3BF));

    reg csr_access;
    reg csr_write;
    always @* begin
        case (csrop)
            3'b000: begin csr_access = 1'b0; csr_write = 1'b0; end
            3'b001: begin csr_access = 1'b1; csr_write = 1'b0; end
            3'b010: begin csr_access = 1'b1; csr_write = 1'b1; end
            3'b011: begin csr_access = 1'b1; csr_write = 1'b1; end
            3'b100: begin csr_access = 1'b1; csr_write = 1'b1; end
            3'b101: begin csr_access = 1'b0; csr_write = 1'b0; end
            3'b110: begin csr_access = 1'b0; csr_write = 1'b0; end
            3'b111: begin csr_access = 1'b0; csr_write = 1'b0; end
        endcase
    end

    wire not_m    = (priv != 2'b11);
    wire readonly = (a[11:10] == 2'b11);
    wire zero_sel = (sel_in == 6'd0);

    wire hw_ill  = (csr_access && not_m) || (csr_write && readonly);
    wire pmp_ill = csr_access && not_m;

    assign sel_out = (zero_sel && hw)    ? 6'd44 :
                     (zero_sel && pmp_a) ? 6'd42 :
                     (zero_sel && pmp_b) ? 6'd43 :
                                           sel_in;

    assign ill_out = (zero_sel && hw)    ? hw_ill  :
                     (zero_sel && pmp_a) ? pmp_ill :
                     (zero_sel && pmp_b) ? pmp_ill :
                                           ill_in;

endmodule

module c0_csr_alu (
    input  wire [31:0] old,
    input  wire [31:0] src,
    input  wire [2:0]  csrop,
    output wire [31:0] nval
);

    reg [31:0] nval_reg;

    always @* begin
        case (csrop)
            3'b010: nval_reg = src;                 // CSR write
            3'b011: nval_reg = old | src;           // CSR set bits
            3'b100: nval_reg = old & ~src;          // CSR clear bits
            default: nval_reg = old;                // none, read only, sret, sfence.vma, fence.i
        endcase
    end

    assign nval = nval_reg;

endmodule

module c0_irq_select (
    input  wire [11:0] mip,
    input  wire [11:0] mie,
    input  wire [11:0] mideleg,
    input  wire [1:0]  priv,
    input  wire        mstatus_mie,
    input  wire        mstatus_sie,
    output reg         pending,
    output reg  [3:0]  cause
);

    // Interrupt numbers (odd bits only)
    localparam [3:0] IRQ_SSI = 4'd1;   // Supervisor software
    localparam [3:0] IRQ_MSI = 4'd3;   // Machine software
    localparam [3:0] IRQ_STI = 4'd5;   // Supervisor timer
    localparam [3:0] IRQ_MTI = 4'd7;   // Machine timer
    localparam [3:0] IRQ_SEI = 4'd9;   // Supervisor external
    localparam [3:0] IRQ_MEI = 4'd11;  // Machine external

    integer i;
    reg take_irq;

    always @* begin
        pending = 1'b0;
        cause   = 4'd0;
        take_irq = 1'b0;

        // Priority order: 11 (MEI), 3 (MSI), 7 (MTI), 9 (SEI), 1 (SSI), 5 (STI)
        // Check MEI (11)
        if (!take_irq && mip[11] && mie[11]) begin
            if (mideleg[11]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd11; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd11; take_irq = 1'b1;
                end
            end
        end
        // Check MSI (3)
        if (!take_irq && mip[3] && mie[3]) begin
            if (mideleg[3]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd3; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd3; take_irq = 1'b1;
                end
            end
        end
        // Check MTI (7)
        if (!take_irq && mip[7] && mie[7]) begin
            if (mideleg[7]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd7; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd7; take_irq = 1'b1;
                end
            end
        end
        // Check SEI (9)
        if (!take_irq && mip[9] && mie[9]) begin
            if (mideleg[9]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd9; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd9; take_irq = 1'b1;
                end
            end
        end
        // Check SSI (1)
        if (!take_irq && mip[1] && mie[1]) begin
            if (mideleg[1]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd1; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd1; take_irq = 1'b1;
                end
            end
        end
        // Check STI (5)
        if (!take_irq && mip[5] && mie[5]) begin
            if (mideleg[5]) begin
                if (priv == 2'd0 || (priv == 2'd1 && mstatus_sie)) begin
                    pending = 1'b1; cause = 4'd5; take_irq = 1'b1;
                end
            end else begin
                if (priv != 2'd3 || (priv == 2'd3 && mstatus_mie)) begin
                    pending = 1'b1; cause = 4'd5; take_irq = 1'b1;
                end
            end
        end
    end

endmodule

module c0_mstatus_reg (
    input  wire        clk,
    input  wire        rst,
    input  wire        trap_m,
    input  wire        trap_s,
    input  wire        mret,
    input  wire        sret,
    input  wire        we_m,
    input  wire        we_s,
    input  wire [31:0] wdata,
    output reg  [1:0]  priv,
    output reg  [31:0] mstatus,
    output wire        mie,
    output wire        sie,
    output wire        mprv,
    output wire [1:0]  mpp,
    output wire        sum,
    output wire        mxr,
    output wire        tvm,
    output wire        tw,
    output wire        tsr
);

    assign mie  = mstatus[3];
    assign sie  = mstatus[1];
    assign mprv = mstatus[17];
    assign mpp  = mstatus[12:11];
    assign sum  = mstatus[18];
    assign mxr  = mstatus[19];
    assign tvm  = mstatus[20];
    assign tw   = mstatus[21];
    assign tsr  = mstatus[22];

    always @(posedge clk) begin
        if (rst) begin
            priv     <= 2'b11;
            mstatus  <= 32'b0;
        end else if (trap_m) begin
            mstatus[7]   <= mstatus[3];   // MPIE <= old MIE
            mstatus[3]   <= 1'b0;         // MIE  <= 0
            mstatus[12:11] <= priv;       // MPP  <= old priv
            priv         <= 2'b11;        // priv <= 3 (M-mode)
        end else if (trap_s) begin
            mstatus[5]   <= mstatus[1];   // SPIE <= old SIE
            mstatus[1]   <= 1'b0;         // SIE  <= 0
            mstatus[8]   <= priv[0];      // SPP  <= bit 0 of old priv
            priv         <= 2'b01;        // priv <= 1 (S-mode)
        end else if (mret) begin
            priv         <= mstatus[12:11]; // priv <= old MPP
            mstatus[3]   <= mstatus[7];     // MIE  <= old MPIE
            mstatus[7]   <= 1'b1;           // MPIE <= 1
            mstatus[12:11] <= 2'b00;        // MPP  <= 0
            if (mstatus[12:11] != 2'b11)    // if old MPP != 3
                mstatus[17] <= 1'b0;        // MPRV <= 0
        end else if (sret) begin
            priv         <= {1'b0, mstatus[8]}; // priv <= old SPP (0 or 1)
            mstatus[1]   <= mstatus[5];         // SIE  <= old SPIE
            mstatus[5]   <= 1'b1;               // SPIE <= 1
            mstatus[8]   <= 1'b0;               // SPP  <= 0
            mstatus[17]  <= 1'b0;               // MPRV <= 0
        end else if (we_m) begin
            mstatus[1]   <= wdata[1];   // SIE
            mstatus[3]   <= wdata[3];   // MIE
            mstatus[5]   <= wdata[5];   // SPIE
            mstatus[7]   <= wdata[7];   // MPIE
            mstatus[8]   <= wdata[8];   // SPP
            if (wdata[12:11] != 2'b10)  // if wdata MPP != 2'b10
                mstatus[12:11] <= wdata[12:11]; // MPP
            mstatus[17]  <= wdata[17];  // MPRV
            mstatus[18]  <= wdata[18];  // SUM
            mstatus[19]  <= wdata[19];  // MXR
            mstatus[20]  <= wdata[20];  // TVM
            mstatus[21]  <= wdata[21];  // TW
            mstatus[22]  <= wdata[22];  // TSR
        end else if (we_s) begin
            mstatus[1]   <= wdata[1];   // SIE
            mstatus[5]   <= wdata[5];   // SPIE
            mstatus[8]   <= wdata[8];   // SPP
            mstatus[18]  <= wdata[18];  // SUM
            mstatus[19]  <= wdata[19];  // MXR
        end
    end

endmodule

module c0_trap_unit (
    input  wire        valid,
    input  wire        xcpt,
    input  wire        irq,
    input  wire [3:0]  cause,
    input  wire [31:0] pc,
    input  wire [31:0] tval,
    input  wire [31:0] inst,
    input  wire [2:0]  csrop,
    input  wire        is_mret,
    input  wire        illegal_csr,
    input  wire [1:0]  priv,
    input  wire        tsr,
    input  wire        tvm,
    input  wire [15:0] medeleg,
    input  wire [11:0] mideleg,
    input  wire [31:0] mtvec,
    input  wire [31:0] stvec,
    input  wire [31:0] mepc,
    input  wire [31:0] sepc,
    output wire        redirect,
    output wire        kill,
    output wire [31:0] redirect_pc,
    output wire        trap_m,
    output wire        trap_s,
    output wire        mret,
    output wire        sret,
    output wire        csr_we,
    output wire        sfence,
    output wire        retire,
    output wire [31:0] epc,
    output wire [31:0] cause_val,
    output wire [31:0] tval_out
);

    reg        illegal;
    reg        trap;
    reg [3:0]  c;
    reg        is_int;
    reg [31:0] t;
    reg        deleg;
    reg        trap_s_r, trap_m_r;
    reg        mret_r, sret_r;
    reg        csr_we_r, sfence_r;
    reg        refetch;
    reg        redirect_r, kill_r;
    reg        retire_r;
    reg [31:0] epc_r;
    reg [31:0] cause_val_r;
    reg [31:0] tval_out_r;
    reg [31:0] redirect_pc_r;

    // Vector function
    function [31:0] vector;
        input [31:0] v;
        input        is_int;
        input [3:0]  c;
        begin
            vector = (v & 32'hFFFFFFFC) + ((is_int && v[0]) ? (c * 4) : 32'd0);
        end
    endfunction

    always @* begin
        // illegal
        illegal = illegal_csr |
                  (is_mret && (priv != 2'b11)) |
                  ((csrop == 3'b101) && (priv == 2'b00 || (priv == 2'b01 && tsr))) |
                  ((csrop == 3'b110) && (priv == 2'b00 || (priv == 2'b01 && tvm)));

        // trap
        trap = valid && (xcpt || illegal);

        // c
        c = xcpt ? cause : 4'd2;

        // is_int
        is_int = xcpt && irq;

        // t
        if (is_int)
            t = 32'd0;
        else if (xcpt)
            t = tval;
        else
            t = inst;

        // deleg
        if (priv != 2'b11) begin
            if (is_int)
                deleg = mideleg[c]; // c up to 11, mideleg 12 bits
            else
                deleg = medeleg[c]; // c up to 15, medeleg 16 bits
        end else begin
            deleg = 1'b0;
        end

        // trap_s, trap_m
        trap_s_r = trap && deleg;
        trap_m_r = trap && !deleg;

        // mret, sret
        mret_r = valid && !trap && is_mret;
        sret_r = valid && !trap && (csrop == 3'b101);

        // csr_we
        csr_we_r = valid && !trap && (csrop == 3'b010 || csrop == 3'b011 || csrop == 3'b100);

        // sfence
        sfence_r = valid && !trap && (csrop == 3'b110);

        // refetch
        refetch = valid && !trap && (csrop == 3'b010 || csrop == 3'b011 || csrop == 3'b100 || csrop == 3'b110 || csrop == 3'b111);

        // redirect
        redirect_r = trap || mret_r || sret_r || refetch;

        // kill
        kill_r = trap || mret_r || sret_r;

        // retire
        retire_r = valid && !trap;

        // epc
        epc_r = pc & 32'hFFFFFFFE;

        // cause_val
        cause_val_r = {is_int, 27'd0, c};

        // tval_out
        tval_out_r = t;

        // redirect_pc
        if (trap_m_r)
            redirect_pc_r = vector(mtvec, is_int, c);
        else if (trap_s_r)
            redirect_pc_r = vector(stvec, is_int, c);
        else if (mret_r)
            redirect_pc_r = mepc;
        else if (sret_r)
            redirect_pc_r = sepc;
        else
            redirect_pc_r = pc + 32'd4;
    end

    assign redirect    = redirect_r;
    assign kill        = kill_r;
    assign redirect_pc = redirect_pc_r;
    assign trap_m      = trap_m_r;
    assign trap_s      = trap_s_r;
    assign mret        = mret_r;
    assign sret        = sret_r;
    assign csr_we      = csr_we_r;
    assign sfence      = sfence_r;
    assign retire      = retire_r;
    assign epc         = epc_r;
    assign cause_val   = cause_val_r;
    assign tval_out    = tval_out_r;

endmodule

module c0_csr_mregs (
    input  wire         clk,
    input  wire         rst,
    input  wire [5:0]   sel,
    input  wire         we,
    input  wire [31:0]  nval,
    input  wire         trap_m,
    input  wire [31:0]  epc,
    input  wire [31:0]  cause_val,
    input  wire [31:0]  tval,
    output reg  [31:0]  mtvec,
    output reg  [31:0]  mscratch,
    output reg  [31:0]  mepc,
    output reg  [31:0]  mcause,
    output reg  [31:0]  mtval,
    output reg  [11:0]  mie,
    output reg  [15:0]  medeleg,
    output reg  [11:0]  mideleg,
    output reg  [2:0]   mcounteren,
    output reg  [11:0]  mip_sw
);

    always @(posedge clk) begin
        if (rst) begin
            mtvec      <= 32'd0;
            mscratch   <= 32'd0;
            mepc       <= 32'd0;
            mcause     <= 32'd0;
            mtval      <= 32'd0;
            mie        <= 12'd0;
            medeleg    <= 16'd0;
            mideleg    <= 12'd0;
            mcounteren <= 3'd0;
            mip_sw     <= 12'd0;
        end else if (trap_m) begin
            mepc   <= epc & 32'hFFFFFFFE;
            mcause <= cause_val;
            mtval  <= tval;
        end else if (we) begin
            case (sel)
                6'd3:   medeleg    <= nval[15:0] & 16'hB3FF;
                6'd4:   mideleg    <= nval[11:0] & 12'h222;
                6'd5:   mie        <= nval[11:0] & 12'hAAA;
                6'd6:   mtvec      <= nval & 32'hFFFFFFFD;
                6'd7:   mcounteren <= nval[2:0];
                6'd8:   mscratch   <= nval;
                6'd9:   mepc       <= nval & 32'hFFFFFFFE;
                6'd10:  mcause     <= nval;
                6'd11:  mtval      <= nval;
                6'd12:  mip_sw     <= (mip_sw & 12'h200) | (nval[11:0] & 12'h022);
                6'd28:  mie        <= (mie & ~mideleg) | (nval[11:0] & mideleg & 12'h222);
                6'd35:  mip_sw     <= (mip_sw & ~(mideleg & 12'h2)) | (nval[11:0] & mideleg & 12'h2);
                default: ;
            endcase
        end
    end

endmodule

module c0_csr_sregs (
    input  wire         clk,
    input  wire         rst,
    input  wire [5:0]   sel,
    input  wire         we,
    input  wire [31:0]  nval,
    input  wire         trap_s,
    input  wire [31:0]  epc,
    input  wire [31:0]  cause_val,
    input  wire [31:0]  tval,
    output reg  [31:0]  stvec,
    output reg  [31:0]  sscratch,
    output reg  [31:0]  sepc,
    output reg  [31:0]  scause,
    output reg  [31:0]  stval,
    output reg  [31:0]  satp,
    output reg  [2:0]   scounteren
);

    always @(posedge clk) begin
        if (rst) begin
            stvec       <= 32'd0;
            sscratch    <= 32'd0;
            sepc        <= 32'd0;
            scause      <= 32'd0;
            stval       <= 32'd0;
            satp        <= 32'd0;
            scounteren  <= 3'd0;
        end else if (trap_s) begin
            sepc   <= epc & 32'hFFFFFFFE;   // clear bit 0
            scause <= cause_val;
            stval  <= tval;
        end else if (we) begin
            case (sel)
                6'd29:  stvec      <= nval & 32'hFFFFFFFD;   // clear bit 1
                6'd30:  scounteren <= nval[2:0];
                6'd31:  sscratch   <= nval;
                6'd32:  sepc       <= nval & 32'hFFFFFFFE;   // clear bit 0
                6'd33:  scause     <= nval;
                6'd34:  stval      <= nval;
                6'd36:  satp       <= nval & 32'h803FFFFF;
                default: ; // no change
            endcase
        end
    end

endmodule

module c0_counters (
    input  wire         clk,
    input  wire         rst,
    input  wire         retire,
    input  wire         we,
    input  wire [5:0]   sel,
    input  wire [31:0]  nval,
    output wire [63:0]  mcycle,
    output wire [63:0]  minstret
);

    reg [63:0] mcycle_reg, minstret_reg;

    wire we_mcycle   = we && (sel == 6'd13 || sel == 6'd15);
    wire we_minstret = we && (sel == 6'd14 || sel == 6'd16);

    wire [63:0] mcycle_next   = we_mcycle   ? (sel == 6'd13 ? {mcycle_reg[63:32], nval} : {nval, mcycle_reg[31:0]}) : mcycle_reg + 1;
    wire [63:0] minstret_next = we_minstret ? (sel == 6'd14 ? {minstret_reg[63:32], nval} : {nval, minstret_reg[31:0]}) : minstret_reg + (retire ? 1 : 0);

    always @(posedge clk) begin
        if (rst) begin
            mcycle_reg   <= 64'd0;
            minstret_reg <= 64'd0;
        end else begin
            mcycle_reg   <= mcycle_next;
            minstret_reg <= minstret_next;
        end
    end

    assign mcycle   = mcycle_reg;
    assign minstret = minstret_reg;

endmodule

module c0_mip_merge_s (
    input  wire [11:0] mip_sw,
    input  wire        meip,
    input  wire        mtip,
    input  wire        msip,
    input  wire        seip,
    output wire [11:0] mip
);

    assign mip[0]  = 1'b0;
    assign mip[1]  = mip_sw[1];
    assign mip[2]  = 1'b0;
    assign mip[3]  = msip;
    assign mip[4]  = 1'b0;
    assign mip[5]  = mip_sw[5];
    assign mip[6]  = 1'b0;
    assign mip[7]  = mtip;
    assign mip[8]  = 1'b0;
    assign mip[9]  = mip_sw[9] | seip;
    assign mip[10] = 1'b0;
    assign mip[11] = meip;

endmodule

module c0_csr_rmux (
    input  wire [5:0]   sel,
    input  wire [31:0]  mstatus,
    input  wire [15:0]  medeleg,
    input  wire [11:0]  mideleg,
    input  wire [11:0]  mie,
    input  wire [31:0]  mtvec,
    input  wire [2:0]   mcounteren,
    input  wire [31:0]  mscratch,
    input  wire [31:0]  mepc,
    input  wire [31:0]  mcause,
    input  wire [31:0]  mtval,
    input  wire [11:0]  mip,
    input  wire [63:0]  mcycle,
    input  wire [63:0]  minstret,
    input  wire [63:0]  mtime,
    input  wire [1:0]   hartid,
    input  wire [31:0]  stvec,
    input  wire [2:0]   scounteren,
    input  wire [31:0]  sscratch,
    input  wire [31:0]  sepc,
    input  wire [31:0]  scause,
    input  wire [31:0]  stval,
    input  wire [31:0]  satp,
    input  wire [31:0]  pmpcfg0,
    input  wire [31:0]  pmpaddr0,
    output reg  [31:0]  rdata
);

always @* begin
    rdata = 32'd0;
    case (sel)
        6'd1:   rdata = mstatus;
        6'd2:   rdata = 32'h40141105;
        6'd3:   rdata = {16'd0, medeleg};
        6'd4:   rdata = {20'd0, mideleg};
        6'd5:   rdata = {20'd0, mie};
        6'd6:   rdata = mtvec;
        6'd7:   rdata = {29'd0, mcounteren};
        6'd8:   rdata = mscratch;
        6'd9:   rdata = mepc;
        6'd10:  rdata = mcause;
        6'd11:  rdata = mtval;
        6'd12:  rdata = {20'd0, mip};
        6'd13:  rdata = mcycle[31:0];
        6'd14:  rdata = minstret[31:0];
        6'd15:  rdata = mcycle[63:32];
        6'd16:  rdata = minstret[63:32];
        6'd17:  rdata = mcycle[31:0];
        6'd18:  rdata = mtime[31:0];
        6'd19:  rdata = minstret[31:0];
        6'd20:  rdata = mcycle[63:32];
        6'd21:  rdata = mtime[63:32];
        6'd22:  rdata = minstret[63:32];
        6'd23:  rdata = 32'd0;
        6'd24:  rdata = 32'd0;
        6'd25:  rdata = 32'd0;
        6'd26:  rdata = {30'd0, hartid};
        6'd27:  rdata = mstatus & 32'h000C0122;
        6'd28:  rdata = {20'd0, (mie & mideleg)};
        6'd29:  rdata = stvec;
        6'd30:  rdata = {29'd0, scounteren};
        6'd31:  rdata = sscratch;
        6'd32:  rdata = sepc;
        6'd33:  rdata = scause;
        6'd34:  rdata = stval;
        6'd35:  rdata = {20'd0, (mip & mideleg)};
        6'd36:  rdata = satp;
        6'd37:  rdata = 32'd0;
        6'd38:  rdata = 32'd0;
        6'd39:  rdata = 32'd0;
        6'd40:  rdata = 32'd0;
        6'd41:  rdata = 32'd0;
        6'd42:  rdata = pmpcfg0;
        6'd43:  rdata = pmpaddr0;
        default: rdata = 32'd0;
    endcase
end

endmodule

module c0_status_we (
    input csr_we,
    input [5:0] sel,
    output we_m,
    output we_s
);

    // we_m is 1 when csr_we is 1 and sel is 1
    assign we_m = csr_we & (sel == 6'd1);

    // we_s is 1 when csr_we is 1 and sel is 27
    assign we_s = csr_we & (sel == 6'd27);

endmodule

module c0_satp_split (
    input  [31:0] satp,
    output mode,
    output [21:0] ppn
);

    assign mode = satp[31];
    assign ppn = satp[21:0];

endmodule

module c0_xlate_on (
    input  wire [1:0] priv,
    input  wire       mprv,
    input  wire [1:0] mpp,
    input  wire       satp_mode,
    output wire       xlate_i,
    output wire       xlate_d,
    output wire [1:0] dpriv,
    output wire [1:0] kind_i
);

    assign dpriv = (mprv && (priv == 2'b11)) ? mpp : priv;
    assign xlate_i = satp_mode && (priv != 2'b11);
    assign xlate_d = satp_mode && (dpriv != 2'b11);
    assign kind_i = 2'b00;

endmodule

module c0_dkind (
    input valid,
    input [1:0] memsrc,
    input memwrite,
    input is_amo,
    input [3:0] amo_op,
    output access,
    output store,
    output [1:0] kind
);

    // access is 1 when valid is 1 and (memsrc 01 means a load; memwrite 1 a store; is_amo 1 an atomic instruction)
    // Assuming "memsrc 01" refers to the value 1 (3'd1) since memsrc is 3 bits.
    assign access = valid & (memsrc == 2'd1 | memwrite | is_amo);

    // store is 1 when memwrite is 1, or is_amo is 1 and amo_op is not 0001.
    assign store = memwrite | (is_amo & (amo_op != 4'b0001));

    // kind (2 bits) is 10 when store is 1 and 01 otherwise.
    // kind is 3 bits wide, so we set kind[2] to 0.
    assign kind[1:0] = store ? 2'b10 : 2'b01;

endmodule

module c0_dfault_gate (
    input  wire access,
    input  wire xlate,
    input  wire pf,
    input  wire af,
    output wire pf_o,
    output wire af_o
);

    // Page fault output: active only when access and translation are enabled
    assign pf_o = pf & access & xlate;

    // Access fault output: active only when access and translation are enabled
    assign af_o = af & access & xlate;

endmodule

module c0_ifault(
    input  [31:0] inst,
    input         is16,
    input  [31:0] pc,
    input  [31:0] word_lo,
    input         xlate,
    input         lo_pf,
    input         lo_af,
    input         hi_pf,
    input         hi_af,
    input         pmp_lo,
    input         pmp_hi,
    output reg [31:0] inst_out,
    output reg        is16_out
);

    // Determine if the next word is needed
    wire need_hi = pc[1] & (word_lo[17:16] == 2'b11);

    // Fault word constants
wire [31:0] fault_page_pc   = 32'b0 | 32'b0001011 | (32'b001 << 12) | (32'b0 << 20);
wire [31:0] fault_access_pc = 32'b0 | 32'b0001011 | (32'b010 << 12) | (32'b0 << 20);
wire [31:0] fault_page_hi   = 32'b0 | 32'b0001011 | (32'b001 << 12) | (32'b1 << 20);
wire [31:0] fault_access_hi = 32'b0 | 32'b0001011 | (32'b010 << 12) | (32'b1 << 20);

    // Combinational logic
    always @* begin
        // Default: pass through
        inst_out = inst;
        is16_out = is16;

        // Priority order
        if (xlate && lo_pf) begin
            inst_out = fault_page_pc;
            is16_out = 1'b0;
        end else if ((xlate && lo_af) || pmp_lo) begin
            inst_out = fault_access_pc;
            is16_out = 1'b0;
        end else if (xlate && need_hi && hi_pf) begin
            inst_out = fault_page_hi;
            is16_out = 1'b0;
        end else if (need_hi && ((xlate && hi_af) || pmp_hi)) begin
            inst_out = fault_access_hi;
            is16_out = 1'b0;
        end
    end

endmodule

module c0_mmu_ctl (
    input xlate_i,
    input xlate_d,
    input d_access,
    input [31:0] word_lo,
    input lo_miss,
    input hi_miss,
    input d_miss,
    input ptw_busy,
    input [31:0] pc,
    input [31:0] hi_addr,
    input [31:0] d_va,
    output stall,
    output walk_start,
    output [31:0] walk_va
);

    // Intermediate signals
    wire need_hi;
    wire lm;
    wire hm;
    wire dm;

    // 1. need_hi: 1 when bit 1 of pc is 1 and bits 17:16 of word_lo are 11
    assign need_hi = pc[1] & (word_lo[17:16] == 2'b11);

    // 2. lm: xlate_i AND lo_miss
    assign lm = xlate_i & lo_miss;

    // 3. hm: xlate_i AND NOT lo_miss AND need_hi AND hi_miss
    assign hm = xlate_i & ~lo_miss & need_hi & hi_miss;

    // 4. dm: xlate_d AND d_access AND d_miss
    assign dm = xlate_d & d_access & d_miss;

    // 5. stall: ptw_busy OR lm OR hm OR dm
    assign stall = ptw_busy | lm | hm | dm;

    // 6. walk_start: NOT ptw_busy AND (lm OR hm OR dm)
    assign walk_start = ~ptw_busy & (lm | hm | dm);

    // 7. walk_va (32 bits):
    // dm=1 -> d_va
    // else lm=1 -> pc
    // else hm=1 -> hi_addr
    // else -> 0
    assign walk_va = dm ? d_va :
                      lm ? pc :
                      hm ? hi_addr :
                      32'b0;

endmodule

module c0_pa_mux_ilo (
    input  wire        xlate,
    input  wire [31:0] va,
