module c1_xfault_ilo (
    input  wire        hit,
    input  wire        perm_fault,
    input  wire        wfault,
    input  wire        waccess,
    input  wire [19:0] wvpn,
    input  wire [31:0] va,
    output wire        pf,
    output wire        af,
    output wire        miss
);

    wire held;
    assign held = wfault & (wvpn == va[31:12]);

    assign pf   = hit ? perm_fault : (held & ~waccess);
    assign af   = ~hit & held & waccess;
    assign miss = ~hit & ~held;

endmodule

module c1_xfault_ihi (
    input  wire        hit,
    input  wire        perm_fault,
    input  wire        wfault,
    input  wire        waccess,
    input  wire [19:0] wvpn,
