module c2_ptw (
    input clk,
    input rst,
    input start,
    input [31:0] vaddr,
    input [21:0] satp_ppn,
    input grant,
    input [31:0] rdata,
    input clear,
    input deny,
    output busy,
    output req,
    output [31:0] addr,
    output fill,
    output [19:0] fill_vpn,
    output [21:0] fill_ppn,
    output fill_mega,
    output [7:0] fill_flags,
    output fault,
    output fault_access,
    output [19:0] fault_vpn
);
    localparam [1:0] IDLE = 2'd0;
    localparam [1:0] L1   = 2'd1;
    localparam [1:0] L0   = 2'd2;

    reg [1:0] st;
    reg [33:0] a;
    reg [31:0] va;
    reg fault_r;
    reg facc;
    reg [19:0] fvpn_r;

    wire in_ram;
    wire active;
    wire v_pte;
    wire r_pte;
    wire w_pte;
    wire x_pte;
    wire [21:0] pte_ppn;
    wire valid_leaf;

    assign in_ram = (a[33:26] == 8'b0010_0000);
    assign active = (st == L1) || (st == L0);

    assign v_pte = rdata[0];
    assign r_pte = rdata[1];
    assign w_pte = rdata[2];
    assign x_pte = rdata[3];
    assign pte_ppn = rdata[31:10];

    assign valid_leaf =
        v_pte &&
        !((!r_pte) && w_pte) &&
        (r_pte || x_pte) &&
        !((st == L1) && (pte_ppn[9:0] != 10'd0));

    assign busy = (st != IDLE);
    assign req = active && in_ram;
    assign addr = req ? a[31:0] : 32'd0;

    assign fill = req && grant && valid_leaf;
    assign fill_vpn = fill ? va[31:12] : 20'd0;
    assign fill_ppn = fill ? pte_ppn : 22'd0;
    assign fill_mega = fill && (st == L1);
    assign fill_flags = fill ? rdata[7:0] : 8'd0;

    assign fault = fault_r;
    assign fault_access = facc;
    assign fault_vpn = fvpn_r;

    always @(posedge clk) begin
        if (rst) begin
            st <= IDLE;
            a <= 34'd0;
            va <= 32'd0;
            fault_r <= 1'b0;
            facc <= 1'b0;
            fvpn_r <= 20'd0;
        end else if (clear) begin
            st <= IDLE;
            fault_r <= 1'b0;
        end else begin
            case (st)
                IDLE: begin
                    if (start) begin
                        st <= L1;
                        va <= vaddr;
                        a <= {satp_ppn, 12'd0} + {22'd0, vaddr[31:22], 2'b00};
                        fault_r <= 1'b0;
                    end
                end

                L1, L0: begin
                    if (!in_ram || deny) begin
                        st <= IDLE;
                        fault_r <= 1'b1;
                        facc <= 1'b1;
                        fvpn_r <= va[31:12];
                    end else if (grant) begin
                        if (!v_pte || ((!r_pte) && w_pte)) begin
                            st <= IDLE;
                            fault_r <= 1'b1;
                            facc <= 1'b0;
                            fvpn_r <= va[31:12];
                        end else if (r_pte || x_pte) begin
                            if ((st == L1) && (pte_ppn[9:0] != 10'd0)) begin
                                st <= IDLE;
                                fault_r <= 1'b1;
                                facc <= 1'b0;
                                fvpn_r <= va[31:12];
                            end else begin
                                st <= IDLE;
                            end
                        end else begin
                            if ((st == L0) || rdata[7] || rdata[6] || rdata[4]) begin
                                st <= IDLE;
                                fault_r <= 1'b1;
                                facc <= 1'b0;
                                fvpn_r <= va[31:12];
                            end else begin
                                st <= L0;
                                a <= {pte_ppn, 12'd0} + {22'd0, va[21:12], 2'b00};
                            end
                        end
                    end
                end

                default: begin
                    st <= IDLE;
                end
            endcase
        end
    end
endmodule

module c2_hart_memif (
    input  wire        core_req,
    input  wire        mmu_stall,
    input  wire        imiss,
    input  wire        ptw_req,
    input  wire        ifq,
    input  wire        grant,
    output wire        req,
    output wire [1:0]  kind,
    output wire        stall,
    output wire        run
);

    wire core_eff = core_req & ~mmu_stall & ~imiss;
    assign req   = core_eff | ptw_req | ifq;
    assign kind  = (ifq)      ? 2'b10 :
                   (ptw_req)  ? 2'b01 :
                                2'b00;
    assign stall = mmu_stall | imiss;
    assign run   = ~core_req | grant;

endmodule

module c2_ifetch_ctl (
    input  wire         clk,
    input  wire         rst,
    input  wire         hit_lo,
    input  wire         hit_hi,
    input  wire         need_hi,
    input  wire         hold,
    input  wire [31:0]  lo_addr,
    input  wire [31:0]  hi_addr,
    input  wire         done,
    input  wire [255:0] line,
    input  wire         fence,
    input  wire         adv,
    output wire         imiss,
    output wire         rq,
    output wire [31:0]  rq_addr,
    output wire         fill_en,
    output wire [31:0]  fill_addr,
    output wire [255:0] fill_data,
    output wire         inv_all
);

    reg  [31:0] ra;
    reg         busy;

    wire miss_lo = ~hit_lo;
    wire miss_hi = need_hi & ~hit_hi;
    wire imiss_int = (miss_lo | miss_hi) & ~hold;

    assign imiss     = imiss_int;
    assign rq        = busy;
    assign fill_en   = busy & done;
    assign rq_addr   = ra;
    assign fill_addr = ra;
    assign fill_data = line;
    assign inv_all   = fence & adv;

    always @(posedge clk) begin
        if (rst) begin
            ra   <= 32'd0;
            busy <= 1'b0;
        end else begin
            if (!busy && imiss_int) begin
                ra   <= miss_lo ? (lo_addr & 32'hFFFFFFE0) : (hi_addr & 32'hFFFFFFE0);
                busy <= 1'b1;
            end else if (busy && done) begin
                busy <= 1'b0;
            end
        end
    end

endmodule

module c2_cat_lk (
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [63:0] y
);

    assign y = {b, a};

endmodule

module c2_sp_lk (
    input  [63:0] y,
    output [31:0] lo,
    output [31:0] hi
);

    assign lo = y[31:0];
    assign hi = y[63:32];

endmodule

module c2_sp_hit (
    input  wire [1:0] y,
    output wire       b0,
    output wire       b1
);

    assign b0 = y[0];
    assign b1 = y[1];

endmodule

module c2_rload (
    input  wire [31:0] word,
    input  wire [2:0]  memtype,
    input  wire [31:0] addr,
    output reg  [31:0] rdata
);

    always @* begin
        // default
        rdata = 32'd0;

        case (memtype)
            3'b000: begin // byte, sign-extended
                case (addr[1:0])
                    2'b00: rdata = {{24{word[7]}},  word[7:0]};
                    2'b01: rdata = {{24{word[15]}}, word[15:8]};
                    2'b10: rdata = {{24{word[23]}}, word[23:16]};
                    2'b11: rdata = {{24{word[31]}}, word[31:24]};
                endcase
            end
            3'b001: begin // half-word, sign-extended
                case (addr[1])
                    1'b0: rdata = {{16{word[15]}},  word[15:0]};
                    1'b1: rdata = {{16{word[31]}},  word[31:16]};
                endcase
            end
            3'b010: begin // word
                rdata = word;
            end
            3'b011: begin // byte, zero-extended
                case (addr[1:0])
                    2'b00: rdata = {24'd0, word[7:0]};
                    2'b01: rdata = {24'd0, word[15:8]};
                    2'b10: rdata = {24'd0, word[23:16]};
                    2'b11: rdata = {24'd0, word[31:24]};
                endcase
            end
            3'b100: begin // half-word, zero-extended
                case (addr[1])
                    1'b0: rdata = {16'd0, word[15:0]};
                    1'b1: rdata = {16'd0, word[31:16]};
                endcase
            end
            3'b101: begin // no access
                rdata = 32'd0;
            end
            3'b110: begin // word
                rdata = word;
            end
            3'b111: begin // word
                rdata = word;
            end
            default: begin
                rdata = 32'd0;
            end
        endcase
    end

endmodule

module c2_en_and (
    input run,
    input stall,
    output en
);

    assign en = run & (~stall);

endmodule

module c2_en_and_clr (
    input run,
    input stall,
    output en
);

    assign en = run & (~stall);

endmodule

module c2_en_and_sf (
    input run,
    input stall,
    output en
);

    assign en = run & (~stall);

endmodule

module c2_core_gate (
    input  wire clk,
    input  wire en,
    input  wire rst,
    output wire gclk
);
`ifdef VERILATOR

    reg en_latch;

    /* verilator lint_off LATCH */
    always @(clk or en or rst) begin
        if (!clk)
            en_latch = en | rst;
    end
    /* verilator lint_on LATCH */

    assign gclk = clk & en_latch;

`else
  BUFGCE #(.SIM_DEVICE("VERSAL_AI_EDGE")) u_gate (.I(clk), .CE(en | rst), .O(gclk));
`endif
endmodule

module c2_rsv_gate (
    input  wire        set_rsv,
    input  wire        clr_rsv,
    input  wire        self_grant,
    input  wire        snoop_we,
    input  wire [31:0] addr,
    input  wire        rsv_valid,
    input  wire [31:0] rsv_addr,
    output wire        set,
    output wire        clear
);

    assign set = set_rsv & self_grant;

    assign clear = (clr_rsv & self_grant) |
                   (snoop_we & ~self_grant & rsv_valid & (addr[31:2] == rsv_addr[31:2]));

endmodule

module c2_amo_rsv (
    input clk,
    input rst,
    input set,
    input clear,
    input [31:0] addr,
    output rsv_valid,
    output [31:0] rsv_addr
);

    reg rsv_valid_r;
    reg [29:0] rsv_word_r;

    always @(posedge clk) begin
        if (rst) begin
            rsv_valid_r <= 1'b0;
            rsv_word_r  <= 30'b0;
        end else if (clear) begin
            rsv_valid_r <= 1'b0;
        end else if (set) begin
            rsv_valid_r <= 1'b1;
            rsv_word_r  <= addr[31:2];
        end
    end

    assign rsv_valid = rsv_valid_r;
    assign rsv_addr  = {rsv_word_r, 2'b00};

endmodule

module c2_dcache_ctl (
    input  wire        clk,
    input  wire        rst,
    input  wire        req,
    input  wire        is_ram,
    input  wire        is_store,
    input  wire        is_amo,
    input  wire        hit,
    input  wire        hold,
    input  wire [31:0] addr,
    input  wire        done,
    input  wire [255:0] line,
    input  wire        wdone,
    input  wire [31:0] waddr,
    input  wire        self,
    input  wire        w_plain,
    output wire        serve,
    output wire        dmiss,
    output wire        rq,
    output wire [31:0] rq_addr,
    output wire        fill_en,
    output wire [31:0] fill_addr,
    output wire [255:0] fill_data,
    output wire        wr_en,
    output wire [31:0] wr_addr,
    output wire        inv_en,
    output wire [31:0] inv_addr
);

    reg [31:0] ra;
    reg        busy;

    wire is_load = req & is_ram & ~is_store & ~is_amo & ~hold;

    assign serve     = is_load & hit;
    assign dmiss     = is_load & ~hit;
    assign rq        = busy;
    assign rq_addr   = ra;
    assign fill_en   = busy & done;
    assign fill_addr = ra;
    assign fill_data = line;
    assign wr_en     = wdone & self & w_plain;
    assign wr_addr   = waddr;
    assign inv_en    = wdone & ~(self & w_plain);
    assign inv_addr  = waddr;

    always @(posedge clk) begin
        if (rst) begin
            ra   <= 32'b0;
            busy <= 1'b0;
        end else begin
            if (!busy && dmiss) begin
                ra   <= addr & ~32'h1F; // clear bits 4:0
                busy <= 1'b1;
            end else if (busy && done) begin
                busy <= 1'b0;
            end
        end
    end

endmodule

module c2_dc_rd (
    input  wire [31:0] addr,
    output wire        sel_ram,
    output wire        sel_clint,
    output wire        sel_plic,
    output wire        sel_uart,
    output wire        sel_periph,
    output wire        sel_gpu,
    output wire        is_io
);

    assign sel_ram     = (addr[31:26] == 6'b100000);
    assign sel_clint   = (addr[31:16] == 16'h0200);
    assign sel_plic    = (addr[31:26] == 6'b000011);
    assign sel_uart    = (addr[31:12] == 20'h10000);
    assign sel_periph  = (addr[31:16] == 16'h1001);
    assign sel_gpu     = (addr[31:25] == 7'b0011000);

    assign is_io = sel_clint | sel_plic | sel_uart | sel_periph | sel_gpu;

endmodule

module c2_wfi_wake (
    input  wire        clk,
    input  wire        rst,
    input  wire [31:0] inst,
    input  wire        msip,
    input  wire        mtip,
    input  wire        meip,
    input  wire [11:0] mip_sw,
    input  wire [11:0] mie,
    output wire        hold
);

// ---------------------------------------------------------------------------
// Internal signals
// ---------------------------------------------------------------------------

// pend: combine mip_sw with the three interrupt bits
wire [11:0] pend_bits;
assign pend_bits[3]  = msip;
assign pend_bits[7]  = mtip;
assign pend_bits[11] = meip;
assign pend_bits[0]  = 1'b0;
assign pend_bits[1]  = 1'b0;
assign pend_bits[2]  = 1'b0;
assign pend_bits[4]  = 1'b0;
assign pend_bits[5]  = 1'b0;
assign pend_bits[6]  = 1'b0;
assign pend_bits[8]  = 1'b0;
assign pend_bits[9]  = 1'b0;
assign pend_bits[10] = 1'b0;

wire [11:0] pend;
assign pend = mip_sw | pend_bits;

// wait_on: WFI instruction and no enabled interrupt pending
wire wait_on;
assign wait_on = (inst == 32'h10500073) && ((pend & mie) == 12'b0);

// ---------------------------------------------------------------------------
// Counter
// ---------------------------------------------------------------------------

reg [15:0] cnt;

always @(posedge clk) begin
    if (rst) begin
        cnt <= 16'd0;
    end else begin
        if (wait_on) begin
            if (cnt != 16'hFFFF)
                cnt <= cnt + 16'd1;
            else
                cnt <= cnt; // stay at max
        end else begin
            cnt <= 16'd0;
        end
    end
end

// ---------------------------------------------------------------------------
// Hold output
// ---------------------------------------------------------------------------

assign hold = wait_on && (cnt != 16'hFFFF);

endmodule

