    output wire [15:0] rdata
);

    reg [15:0] mem [0:19199];
    reg [15:0] rdata_reg;

    integer i;
    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
        rdata_reg = 16'd0;
    end

    wire wsel = (waddr < 15'd19200);
    wire rsel = (raddr < 15'd19200);

    always @(posedge clk) begin
        if (we && wsel)
            mem[waddr] <= wdata;
        rdata_reg <= rsel ? mem[raddr] : 16'd0;
    end

    assign rdata = rdata_reg;

endmodule

module simt_gpu_core0__vdbank1 (
    input clk,
    input we,
    input [14:0] waddr,
    input [15:0] wdata,
    input [14:0] raddr,
    output reg [15:0] rdata
);

    reg [15:0] mem [0:19199];
    integer i;

    wire [14:0] rindex;
    wire [15:0] rdata_next;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
    end

    assign rindex = (raddr < 15'd19200) ? raddr : 15'd0;
    assign rdata_next = (raddr < 15'd19200) ? mem[rindex] : 16'd0;

    always @(posedge clk) begin
        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
        rdata <= rdata_next;
    end

endmodule

module simt_gpu_core0__vdbank2 (
    input wire clk,
    input wire we,
    input wire [14:0] waddr,
    input wire [15:0] wdata,
    input wire [14:0] raddr,
    output reg [15:0] rdata
);

    reg [15:0] mem [0:19199];
    integer i;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
    end

    always @(posedge clk) begin
        rdata <= (raddr < 15'd19200) ? mem[raddr] : 16'd0;
        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
    end

endmodule

module simt_gpu_core0__vdbank3 (
    input clk,
    input we,
    input [14:0] waddr,
    input [15:0] wdata,
    input [14:0] raddr,
    output reg [15:0] rdata
);
    localparam integer DEPTH = 19200;

    reg [15:0] mem [0:DEPTH-1];
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = 16'd0;
        rdata = 16'd0;
    end

    always @(posedge clk) begin
        if (raddr < 15'd19200)
            rdata <= mem[raddr];
        else
            rdata <= 16'd0;

        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
    end
endmodule

