module simt_gpu_core3__warp_sched (
    input wire clk,
    input wire rst,
    input wire start,
    input wire enable,
    input wire [3:0] active,
    input wire [3:0] inflight,
    input wire [3:0] waiting,
    output wire fire,
    output wire [1:0] fwid
);

    reg [1:0] ptr;
    wire [3:0] ready;
    wire [1:0] cand0;
    wire [1:0] cand1;
    wire [1:0] cand2;

    assign ready = active & ~inflight & ~waiting;

    assign cand0 = ptr + 2'd1;
    assign cand1 = ptr + 2'd2;
    assign cand2 = ptr + 2'd3;

    assign fire = enable && (|ready);

    assign fwid = fire ? (ready[cand0] ? cand0 :
                          ready[cand1] ? cand1 :
                          ready[cand2] ? cand2 :
                          ready[ptr]   ? ptr   : 2'd0)
                      : 2'd0;

    always @(posedge clk) begin
        if (rst || start)
            ptr <= 2'd3;
        else if (fire)
            ptr <= fwid;
        else
            ptr <= ptr;
    end

endmodule

module simt_gpu_core3__warp_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        start,
    input  wire [31:0] start_pc,
    input  wire        fire,
    input  wire [1:0]  fwid,
    input  wire        commit,
    input  wire [1:0]  cwid,
    input  wire [31:0] c_pc,
    input  wire [3:0]  c_tmask,
    input  wire [3:0]  spawn_mask,
    input  wire [31:0] spawn_pc,
    output wire [31:0] sel_pc,
    output wire [3:0]  sel_tmask,
    output wire [3:0]  active,
    output wire [3:0]  inflight,
    output wire        busy
);

    reg [31:0] pc  [0:3];
    reg [3:0]  tmask [0:3];
    reg [3:0]  infl;

    assign inflight = infl;
    // active bit w = (tmask[w] != 0)
    wire [3:0] act;
    assign act[0] = (tmask[0] != 4'b0000);
    assign act[1] = (tmask[1] != 4'b0000);
    assign act[2] = (tmask[2] != 4'b0000);
    assign act[3] = (tmask[3] != 4'b0000);
    assign active = act;

    assign busy = (act != 4'b0000) | (infl != 4'b0000);

    assign sel_pc    = pc[fwid];
    assign sel_tmask = tmask[fwid];

    // spawn condition per warp, from values before this edge
    wire [3:0] spawn_hit;
    assign spawn_hit[0] = spawn_mask[0] & (tmask[0] == 4'b0000) & ~infl[0];
    assign spawn_hit[1] = spawn_mask[1] & (tmask[1] == 4'b0000) & ~infl[1];
    assign spawn_hit[2] = spawn_mask[2] & (tmask[2] == 4'b0000) & ~infl[2];
    assign spawn_hit[3] = spawn_mask[3] & (tmask[3] == 4'b0000) & ~infl[3];

    integer w;
    always @(posedge clk) begin
        if (rst) begin
            pc[0] <= 32'd0; pc[1] <= 32'd0; pc[2] <= 32'd0; pc[3] <= 32'd0;
            tmask[0] <= 4'b0000; tmask[1] <= 4'b0000;
            tmask[2] <= 4'b0000; tmask[3] <= 4'b0000;
            infl <= 4'b0000;
        end else if (start) begin
            pc[0] <= start_pc;
            tmask[0] <= 4'b0001;
            pc[1] <= 32'd0; pc[2] <= 32'd0; pc[3] <= 32'd0;
            tmask[1] <= 4'b0000; tmask[2] <= 4'b0000; tmask[3] <= 4'b0000;
            infl <= 4'b0000;
        end else begin
            for (w = 0; w < 4; w = w + 1) begin
                // default: hold
                pc[w]   <= pc[w];
                tmask[w] <= tmask[w];
                // commit
                if (commit && (cwid == w[1:0])) begin
                    pc[w]   <= c_pc;
                    tmask[w] <= c_tmask;
                    infl[w] <= 1'b0;
                end
                // fire (in-flight only; does not touch pc/mask)
                if (fire && (fwid == w[1:0])) begin
                    infl[w] <= 1'b1;
                end
                // spawn overrides commit pc/mask
                if (spawn_hit[w]) begin
                    pc[w]   <= spawn_pc;
                    tmask[w] <= 4'b0001;
                end
            end
        end
    end

endmodule

module simt_gpu_core3__pipe_ctrl (
    input  wire        running,
    input  wire        dx_valid,
    input  wire [2:0]  unit,
    input  wire        div_ready,
    input  wire        lsu_ready,
    input  wire [31:0] sel_pc,
    input  wire [31:0] sf_pc,
    output wire        stall,
    output wire        advance,
    output wire        sched_en,
    output wire [8:0]  fetch_idx,
    input  wire        g_busy
);
    wire div_wait = dx_valid & (unit == 3'b010) & ~div_ready;
    wire lsu_wait = dx_valid & (unit == 3'b011) & ~lsu_ready;
    wire x_busy = div_wait | lsu_wait | g_busy;

    assign stall    = x_busy;
    assign advance  = dx_valid & ~x_busy;
    assign sched_en = running & ~x_busy;
    assign fetch_idx = x_busy ? sf_pc[10:2] : sel_pc[10:2];

endmodule

module simt_gpu_core3__imem (
    input clk,
    input [8:0] raddr,
    output reg [31:0] rdata,
    input we,
    input [8:0] waddr,
    input [31:0] wdata
);

    reg [31:0] mem [0:511];
    integer i;

    initial begin
        for (i = 0; i < 512; i = i + 1)
            mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (we)
            mem[waddr] <= wdata;
        rdata <= mem[raddr];
    end

endmodule

module simt_gpu_core3__sf_reg (
    input  wire        clk,
    input  wire        rst,
    input  wire        clear,
    input  wire        hold,
    input  wire        valid_in,
    input  wire [1:0]  wid_in,
    input  wire [31:0] pc_in,
    input  wire [3:0]  tmask_in,
    output reg         valid_out,
    output reg  [1:0]  wid_out,
    output reg  [31:0] pc_out,
    output reg  [3:0]  tmask_out
);

always @(posedge clk) begin
    if (rst || clear) begin
        valid_out <= 1'b0;
        wid_out   <= 2'b00;
        pc_out    <= 32'h00000000;
        tmask_out <= 4'b0000;
    end else if (hold) begin
        valid_out <= valid_out;
        wid_out   <= wid_out;
        pc_out    <= pc_out;
        tmask_out <= tmask_out;
    end else begin
        valid_out <= valid_in;
        wid_out   <= wid_in;
        pc_out    <= pc_in;
        tmask_out <= tmask_in;
    end
end

endmodule

module simt_gpu_core3__decode (
    input  wire [31:0] inst,
    output wire [4:0]  rs1,
    output wire [4:0]  rs2,
    output wire [4:0]  rd,
    output wire [2:0]  immsel,
    output wire [2:0]  unit,
    output wire [3:0]  alu_op,
    output wire        a_sel,
    output wire        b_sel,
    output wire [2:0]  wb_src,
    output wire        regwrite,
    output wire [1:0]  ctrl,
    output wire [2:0]  br_op,
    output wire        mem_store,
    output wire [2:0]  mem_size,
    output wire [1:0]  md_op,
    output wire [2:0]  simt_op,
    output wire [1:0]  simt_mode,
    output wire [1:0]  tensor_op,
    output wire [11:0] csr_addr,
    output wire        illegal,
    output wire        gfx,
    output wire [2:0]  gfx_op
);

    wire [6:0] op  = inst[6:0];
    wire [2:0] f3  = inst[14:12];
    wire [6:0] f7  = inst[31:25];

    assign rs1       = inst[19:15];
    assign rs2       = inst[24:20];
    assign rd        = inst[11:7];
    assign br_op     = f3;
    assign mem_size  = f3;
    assign md_op     = f3[1:0];
    assign simt_op   = f3;
    assign simt_mode = inst[26:25];
    assign tensor_op = f3[1:0];
    assign csr_addr  = inst[31:20];
    assign gfx_op    = f3;

    reg        r_immsel;
    reg [2:0]  r_immsel3;
    reg [2:0]  r_unit;
    reg [3:0]  r_alu_op;
    reg        r_a_sel;
    reg        r_b_sel;
    reg [2:0]  r_wb_src;
    reg        r_regwrite;
    reg [1:0]  r_ctrl;
    reg        r_mem_store;
    reg        r_illegal;
    reg        r_gfx;

    always @* begin
        r_immsel3   = 3'd5;
        r_unit      = 3'd7;
        r_alu_op    = 4'd0;
        r_a_sel     = 1'b0;
        r_b_sel     = 1'b0;
        r_wb_src    = 3'd0;
        r_regwrite  = 1'b0;
        r_ctrl      = 2'd0;
        r_mem_store = 1'b0;
        r_illegal   = 1'b0;
        r_gfx       = 1'b0;

        case (op)
            7'h37: begin // LUI
                r_unit     = 3'd0;
                r_alu_op   = 4'd10;
                r_b_sel    = 1'b1;
                r_immsel3  = 3'd3;
                r_regwrite = 1'b1;
            end
            7'h17: begin // AUIPC
                r_unit     = 3'd0;
                r_alu_op   = 4'd0;
                r_a_sel    = 1'b1;
                r_b_sel    = 1'b1;
                r_immsel3  = 3'd3;
                r_regwrite = 1'b1;
            end
            7'h6F: begin // JAL
                r_unit     = 3'd0;
                r_a_sel    = 1'b1;
                r_b_sel    = 1'b1;
                r_immsel3  = 3'd4;
                r_wb_src   = 3'd7;
                r_regwrite = 1'b1;
                r_ctrl     = 2'd2;
            end
            7'h67: begin // JALR
                if (f3 == 3'd0) begin
                    r_unit     = 3'd0;
                    r_b_sel    = 1'b1;
                    r_immsel3  = 3'd0;
                    r_wb_src   = 3'd7;
                    r_regwrite = 1'b1;
                    r_ctrl     = 2'd3;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h63: begin // Branch
                if (f3 != 3'd2 && f3 != 3'd3) begin
                    r_unit    = 3'd0;
                    r_immsel3 = 3'd2;
                    r_ctrl    = 2'd1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h03: begin // Load
                if (f3 == 3'd0 || f3 == 3'd1 || f3 == 3'd2 || f3 == 3'd4 || f3 == 3'd5) begin
                    r_unit     = 3'd3;
                    r_b_sel    = 1'b1;
                    r_immsel3  = 3'd0;
                    r_wb_src   = 3'd3;
                    r_regwrite = 1'b1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h23: begin // Store
                if (f3 == 3'd0 || f3 == 3'd1 || f3 == 3'd2) begin
                    r_unit      = 3'd3;
                    r_b_sel     = 1'b1;
                    r_immsel3   = 3'd1;
                    r_mem_store = 1'b1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h13: begin // OP-IMM
                case (f3)
                    3'd0: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd0; end
                    3'd2: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd3; end
                    3'd3: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd4; end
                    3'd4: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd5; end
                    3'd6: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd8; end
                    3'd7: begin r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd9; end
                    3'd1: begin
                        if (f7 == 7'd0) begin
                            r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd2;
                        end else begin
                            r_illegal = 1'b1;
                        end
                    end
                    3'd5: begin
                        if (f7 == 7'd0) begin
                            r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd6;
                        end else if (f7 == 7'h20) begin
                            r_unit = 3'd0; r_b_sel = 1'b1; r_immsel3 = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd7;
                        end else begin
                            r_illegal = 1'b1;
                        end
                    end
                    default: r_illegal = 1'b1;
                endcase
            end
            7'h33: begin // OP
                if (f7 == 7'd0) begin
                    r_unit     = 3'd0;
                    r_regwrite = 1'b1;
                    case (f3)
                        3'd0: r_alu_op = 4'd0;
                        3'd1: r_alu_op = 4'd2;
                        3'd2: r_alu_op = 4'd3;
                        3'd3: r_alu_op = 4'd4;
                        3'd4: r_alu_op = 4'd5;
                        3'd5: r_alu_op = 4'd6;
                        3'd6: r_alu_op = 4'd8;
                        3'd7: r_alu_op = 4'd9;
                    endcase
                end else if (f7 == 7'h20) begin
                    if (f3 == 3'd0) begin
                        r_unit = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd1;
                    end else if (f3 == 3'd5) begin
                        r_unit = 3'd0; r_regwrite = 1'b1; r_alu_op = 4'd7;
                    end else begin
                        r_illegal = 1'b1;
                    end
                end else if (f7 == 7'd1) begin
                    r_regwrite = 1'b1;
                    if (f3 < 3'd4) begin
                        r_unit  = 3'd1;
                        r_wb_src = 3'd1;
                    end else begin
                        r_unit  = 3'd2;
                        r_wb_src = 3'd2;
                    end
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h0F: begin // FENCE
            end
            7'h73: begin // SYSTEM
                if ((f3 == 3'd2 || f3 == 3'd3 || f3 == 3'd6 || f3 == 3'd7) && inst[19:15] == 5'd0) begin
                    r_unit     = 3'd6;
                    r_wb_src   = 3'd6;
                    r_regwrite = 1'b1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h0B: begin // SIMT
                if ((f3 <= 3'd4 && f7 == 7'd0) ||
                    (f3 == 3'd5 && f7 <= 7'd2) ||
                    (f3 == 3'd6 && f7 <= 7'd3)) begin
                    r_unit   = 3'd4;
                    r_wb_src = 3'd4;
                    if (f3 == 3'd5 || f3 == 3'd6)
                        r_regwrite = 1'b1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h2B: begin // Tensor
                if (f7 == 7'd0 && f3 <= 3'd3) begin
                    if ((f3 == 3'd0 && inst[11:7] == 5'd0) ||
                        (f3 == 3'd1) ||
                        (f3 == 3'd2 && inst[11:7] == 5'd0) ||
                        (f3 == 3'd3 && inst[11:7] == 5'd0 && inst[19:15] == 5'd0 && inst[24:20] == 5'd0)) begin
                        r_unit   = 3'd5;
                        r_wb_src = 3'd5;
                        if (f3 == 3'd1)
                            r_regwrite = 1'b1;
                    end else begin
                        r_illegal = 1'b1;
                    end
                end else begin
                    r_illegal = 1'b1;
                end
            end
            7'h5B: begin // Graphics
                if (f7 == 7'd0 && (f3 == 3'd0 || f3 == 3'd5)) begin
                    if (inst[11:7] == 5'd0) begin
                        r_gfx = 1'b1;
                    end else begin
                        r_illegal = 1'b1;
                    end
                end else if (f7 == 7'd0 && (f3 == 3'd1 || f3 == 3'd3 || f3 == 3'd4 || f3 == 3'd6)) begin
                    r_gfx      = 1'b1;
                    r_regwrite = 1'b1;
                end else begin
                    r_illegal = 1'b1;
                end
            end
            default: begin
                r_illegal = 1'b1;
            end
        endcase
    end

    assign immsel    = r_immsel3;
    assign unit      = r_unit;
    assign alu_op    = r_alu_op;
    assign a_sel     = r_a_sel;
    assign b_sel     = r_b_sel;
    assign wb_src    = r_wb_src;
    assign regwrite  = r_regwrite;
    assign ctrl      = r_ctrl;
    assign mem_store = r_mem_store;
    assign illegal   = r_illegal;
    assign gfx       = r_gfx;

endmodule

module simt_gpu_core3__imm_gen (
    input  [31:0] inst,
    input  [2:0]  immsel,
    output reg [31:0] imm
);

    always @* begin
        case (immsel)
            3'b000: imm = {{20{inst[31]}}, inst[31:20]};
            3'b001: imm = {{20{inst[31]}}, inst[31:25], inst[11:7]};
            3'b010: imm = {{19{inst[31]}}, inst[31], inst[7], inst[30:25], inst[11:8], 1'b0};
            3'b011: imm = {inst[31:12], 12'd0};
            3'b100: imm = {{11{inst[31]}}, inst[31], inst[19:12], inst[20], inst[30:21], 1'b0};
            3'b101: imm = 32'd0;
            3'b110: imm = 32'd0;
            3'b111: imm = 32'd0;
            default: imm = 32'd0;
        endcase
    end

endmodule

module simt_gpu_core3__regfile0 (
    input clk,
    input [6:0] raddr,
    output [31:0] rdata,
    input [6:0] raddr2,
    output [31:0] rdata2,
    input we,
    input [6:0] waddr,
    input [31:0] wdata
);

    reg [31:0] mem [0:127];
    integer i;

    initial begin
        for (i = 0; i < 128; i = i + 1)
            mem[i] = 32'd0;
    end

    assign rdata = mem[raddr];
    assign rdata2 = mem[raddr2];

    always @(posedge clk) begin
        if (we)
            mem[waddr] <= wdata;
    end

endmodule

module simt_gpu_core3__regfile1 (
    input clk,
    input [6:0] raddr,
    output [31:0] rdata,
    input [6:0] raddr2,
    output [31:0] rdata2,
    input we,
    input [6:0] waddr,
    input [31:0] wdata
);

    reg [31:0] mem [0:127];
    integer i;

    assign rdata = mem[raddr];
    assign rdata2 = mem[raddr2];

    always @(posedge clk) begin
        if (we) begin
            mem[waddr] <= wdata;
        end
    end

    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            mem[i] = 32'd0;
        end
    end

endmodule

module simt_gpu_core3__regfile2(
    input clk,
    input [6:0] raddr,
    output [31:0] rdata,
    input [6:0] raddr2,
    output [31:0] rdata2,
    input we,
    input [6:0] waddr,
    input [31:0] wdata
);

    reg [31:0] mem [0:127];
    integer i;

    initial begin
        for (i = 0; i < 128; i = i + 1)
            mem[i] = 32'd0;
    end

    assign rdata = mem[raddr];
    assign rdata2 = mem[raddr2];

    always @(posedge clk) begin
        if (we)
            mem[waddr] <= wdata;
    end

endmodule

module simt_gpu_core3__regfile3 (
  input  wire        clk,
  input  wire [6:0]  raddr,
  output wire [31:0] rdata,
  input  wire [6:0]  raddr2,
  output wire [31:0] rdata2,
  input  wire        we,
  input  wire [6:0]  waddr,
  input  wire [31:0] wdata
);

  reg [31:0] mem [0:127];

  // Synchronous write
  always @(posedge clk) begin
    if (we) begin
      mem[waddr] <= wdata;
    end
  end

  // Asynchronous reads
  assign rdata  = mem[raddr];
  assign rdata2 = mem[raddr2];

endmodule

module simt_gpu_core3__operand (
  input  [1:0]   wid,
  input  [4:0]   rs1,
  input  [4:0]   rs2,
  input  [31:0]  rdata1_0,
  input  [31:0]  rdata1_1,
  input  [31:0]  rdata1_2,
  input  [31:0]  rdata1_3,
  input  [31:0]  rdata2_0,
  input  [31:0]  rdata2_1,
  input  [31:0]  rdata2_2,
  input  [31:0]  rdata2_3,
  output [6:0]   raddr1,
  output [6:0]   raddr2,
  output [127:0] a,
  output [127:0] b
);

  assign raddr1 = {wid, rs1};
  assign raddr2 = {wid, rs2};

  wire [127:0] a_gather;
  wire [127:0] b_gather;

  assign a_gather = {rdata1_3, rdata1_2, rdata1_1, rdata1_0};
  assign b_gather = {rdata2_3, rdata2_2, rdata2_1, rdata2_0};

  assign a = (rs1 == 5'd0) ? 128'd0 : a_gather;
  assign b = (rs2 == 5'd0) ? 128'd0 : b_gather;

endmodule

module simt_gpu_core3__dx_reg (
    input clk,
    input rst,
    input clear,
    input hold,
    input valid_in,
    input [1:0] wid_in,
    input [31:0] pc_in,
    input [3:0] tmask_in,
    input [4:0] rd_in,
    input [2:0] unit_in,
    input [3:0] alu_op_in,
    input a_sel_in,
    input b_sel_in,
    input [2:0] wb_src_in,
    input regwrite_in,
    input [1:0] ctrl_in,
    input [2:0] br_op_in,
    input mem_store_in,
    input [2:0] mem_size_in,
    input [1:0] md_op_in,
    input [2:0] simt_op_in,
    input [1:0] simt_mode_in,
    input [1:0] tensor_op_in,
    input gfx_in,
    input [2:0] gfx_op_in,
    input [11:0] csr_addr_in,
    input illegal_in,
    input [31:0] imm_in,
    input [127:0] a_in,
    input [127:0] b_in,
    output reg valid_out,
    output reg [1:0] wid_out,
    output reg [31:0] pc_out,
    output reg [3:0] tmask_out,
    output reg [4:0] rd_out,
    output reg [2:0] unit_out,
    output reg [3:0] alu_op_out,
    output reg a_sel_out,
    output reg b_sel_out,
    output reg [2:0] wb_src_out,
    output reg regwrite_out,
    output reg [1:0] ctrl_out,
    output reg [2:0] br_op_out,
    output reg mem_store_out,
    output reg [2:0] mem_size_out,
    output reg [1:0] md_op_out,
    output reg [2:0] simt_op_out,
    output reg [1:0] simt_mode_out,
    output reg [1:0] tensor_op_out,
    output reg gfx_out,
    output reg [2:0] gfx_op_out,
    output reg [11:0] csr_addr_out,
    output reg illegal_out,
    output reg [31:0] imm_out,
    output reg [127:0] a_out,
    output reg [127:0] b_out
);
    always @(posedge clk) begin
        if (rst || clear) begin
            valid_out <= 1'b0;
            wid_out <= 2'd0;
            pc_out <= 32'd0;
            tmask_out <= 4'd0;
            rd_out <= 5'd0;
            unit_out <= 3'd0;
            alu_op_out <= 4'd0;
            a_sel_out <= 1'b0;
            b_sel_out <= 1'b0;
            wb_src_out <= 3'd0;
            regwrite_out <= 1'b0;
            ctrl_out <= 2'd0;
            br_op_out <= 3'd0;
            mem_store_out <= 1'b0;
            mem_size_out <= 3'd0;
            md_op_out <= 2'd0;
            simt_op_out <= 3'd0;
            simt_mode_out <= 2'd0;
            tensor_op_out <= 2'd0;
            gfx_out <= 1'b0;
            gfx_op_out <= 3'd0;
            csr_addr_out <= 12'd0;
            illegal_out <= 1'b0;
            imm_out <= 32'd0;
            a_out <= 128'd0;
            b_out <= 128'd0;
        end else if (!hold) begin
            valid_out <= valid_in;
            wid_out <= wid_in;
            pc_out <= pc_in;
            tmask_out <= tmask_in;
            rd_out <= rd_in;
            unit_out <= unit_in;
            alu_op_out <= alu_op_in;
            a_sel_out <= a_sel_in;
            b_sel_out <= b_sel_in;
            wb_src_out <= wb_src_in;
            regwrite_out <= regwrite_in;
            ctrl_out <= ctrl_in;
            br_op_out <= br_op_in;
            mem_store_out <= mem_store_in;
            mem_size_out <= mem_size_in;
            md_op_out <= md_op_in;
            simt_op_out <= simt_op_in;
            simt_mode_out <= simt_mode_in;
            tensor_op_out <= tensor_op_in;
            gfx_out <= gfx_in;
            gfx_op_out <= gfx_op_in;
            csr_addr_out <= csr_addr_in;
            illegal_out <= illegal_in;
            imm_out <= imm_in;
            a_out <= a_in;
            b_out <= b_in;
        end
    end
endmodule

module simt_gpu_core3__valu (
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire [31:0]  imm,
    input  wire [31:0]  pc,
    input  wire         a_sel,
    input  wire         b_sel,
    input  wire [3:0]   alu_op,
    input  wire [2:0]   br_op,
    output wire [127:0] y,
    output wire [3:0]   taken
);
    integer i;

    wire [31:0] x [0:3];
    wire [31:0] z [0:3];
    reg  [31:0] r [0:3];

    generate
        genvar g;
        for (g = 0; g < 4; g = g + 1) begin : lanes
            assign x[g] = a_sel ? pc : a[32*g +: 32];
            assign z[g] = b_sel ? imm : b[32*g +: 32];
        end
    endgenerate

    always @* begin
        for (i = 0; i < 4; i = i + 1) begin
            case (alu_op)
                4'b0000: r[i] = x[i] + z[i];
                4'b0001: r[i] = x[i] - z[i];
                4'b0010: r[i] = x[i] << z[i][4:0];
                4'b0011: r[i] = ($signed(x[i]) < $signed(z[i])) ? 32'd1 : 32'd0;
                4'b0100: r[i] = (x[i] < z[i]) ? 32'd1 : 32'd0;
                4'b0101: r[i] = x[i] ^ z[i];
                4'b0110: r[i] = x[i] >> z[i][4:0];
                4'b0111: r[i] = $signed(x[i]) >>> z[i][4:0];
                4'b1000: r[i] = x[i] | z[i];
                4'b1001: r[i] = x[i] & z[i];
                4'b1010: r[i] = z[i];
                default: r[i] = 32'd0;
            endcase
        end
    end

    assign y = {r[3], r[2], r[1], r[0]};

    reg [3:0] t;
    always @* begin
        t = 4'b0000;
        for (i = 0; i < 4; i = i + 1) begin
            case (br_op)
                3'b000: t[i] = (a[32*i +: 32] == b[32*i +: 32]);
                3'b001: t[i] = (a[32*i +: 32] != b[32*i +: 32]);
                3'b010: t[i] = 1'b0;
                3'b011: t[i] = 1'b0;
                3'b100: t[i] = $signed(a[32*i +: 32]) < $signed(b[32*i +: 32]);
                3'b101: t[i] = $signed(a[32*i +: 32]) >= $signed(b[32*i +: 32]);
                3'b110: t[i] = (a[32*i +: 32] < b[32*i +: 32]);
                3'b111: t[i] = (a[32*i +: 32] >= b[32*i +: 32]);
            endcase
        end
    end
    assign taken = t;

endmodule

module simt_gpu_core3__vmul (
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire [1:0]   md_op,
    output wire [127:0] y
);
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : g_lane
            wire [31:0] x = a[32*i +: 32];
            wire [31:0] z = b[32*i +: 32];

            wire [63:0] p_ss = $signed({x[31], x}) * $signed({z[31], z});
            wire [63:0] p_su = $signed({x[31], x}) * $signed({1'b0, z});
            wire [63:0] p_uu = {1'b0, x} * {1'b0, z};

            reg [31:0] r;
            always @* begin
                case (md_op)
                    2'd0: r = p_ss[31:0];
                    2'd1: r = p_ss[63:32];
                    2'd2: r = p_su[63:32];
                    default: r = p_uu[63:32];
                endcase
            end

            assign y[32*i +: 32] = r;
        end
    endgenerate
endmodule

module simt_gpu_core3__vdiv (
    input clk,
    input rst,
    input clear,
    input valid,
    input [2:0] unit,
    input [1:0] md_op,
    input [127:0] a,
    input [127:0] b,
    input advance,
    output ready,
    output [127:0] y
);

localparam [1:0] ST_IDLE = 2'd0;
localparam [1:0] ST_BUSY = 2'd1;
localparam [1:0] ST_DONE = 2'd2;

reg [1:0] state;
reg [4:0] count;
reg [1:0] op;

wire start = valid && (unit == 3'b010);
wire md_signed = (md_op == 2'd0) || (md_op == 2'd2);

always @(posedge clk) begin
    if (rst || clear) begin
        state <= ST_IDLE;
        count <= 5'd0;
        op <= 2'd0;
    end else begin
        case (state)
            ST_IDLE: begin
                if (start) begin
                    op <= md_op;
                    count <= 5'd0;
                    state <= ST_BUSY;
                end
            end
            ST_BUSY: begin
                if (count == 5'd31)
                    state <= ST_DONE;
                else
                    count <= count + 5'd1;
            end
            ST_DONE: begin
                if (advance)
                    state <= ST_IDLE;
            end
            default: state <= ST_IDLE;
        endcase
    end
end

assign ready = (state == ST_DONE);

genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : lanes
        wire [31:0] a_lane = a[32*i +: 32];
        wire [31:0] b_lane = b[32*i +: 32];
        wire [31:0] abs_a = a_lane[31] ? (~a_lane + 32'd1) : a_lane;
        wire [31:0] abs_b = b_lane[31] ? (~b_lane + 32'd1) : b_lane;

        reg [31:0] x_orig;
        reg [31:0] z_orig;
        reg [31:0] z_mag;
        reg [31:0] dividend;
        reg [31:0] quo;
        reg [32:0] rem;

        wire [32:0] rem_shift = {rem[31:0], dividend[31]};
        wire [32:0] z_ext = {1'b0, z_mag};
        wire [32:0] rem_sub = rem_shift - z_ext;
        wire [31:0] quo_neg = ~quo + 32'd1;
        wire [31:0] rem_neg = ~rem[31:0] + 32'd1;

        always @(posedge clk) begin
            if (rst || clear) begin
                x_orig <= 32'd0;
                z_orig <= 32'd0;
                z_mag <= 32'd0;
                dividend <= 32'd0;
                quo <= 32'd0;
                rem <= 33'd0;
            end else if (state == ST_IDLE && start) begin
                x_orig <= a_lane;
                z_orig <= b_lane;
                z_mag <= md_signed ? abs_b : b_lane;
                dividend <= md_signed ? abs_a : a_lane;
                quo <= 32'd0;
                rem <= 33'd0;
            end else if (state == ST_BUSY) begin
                dividend <= {dividend[30:0], 1'b0};
                if (rem_shift >= z_ext) begin
                    rem <= rem_sub;
                    quo <= {quo[30:0], 1'b1};
                end else begin
                    rem <= rem_shift;
                    quo <= {quo[30:0], 1'b0};
                end
            end
        end

        wire [31:0] lane_y;
        assign lane_y =
            (op == 2'd0) ? ((z_orig == 32'd0) ? 32'hFFFFFFFF :
                ((x_orig == 32'h80000000 && z_orig == 32'hFFFFFFFF) ? 32'h80000000 :
                    ((x_orig[31] ^ z_orig[31]) ? quo_neg : quo))) :
            (op == 2'd1) ? ((z_orig == 32'd0) ? 32'hFFFFFFFF : quo) :
            (op == 2'd2) ? ((z_orig == 32'd0) ? x_orig :
                ((x_orig == 32'h80000000 && z_orig == 32'hFFFFFFFF) ? 32'd0 :
                    (x_orig[31] ? rem_neg : rem[31:0]))) :
            ((z_orig == 32'd0) ? x_orig : rem[31:0]);

        assign y[32*i +: 32] = (state == ST_DONE) ? lane_y : 32'd0;
    end
endgenerate

endmodule

module simt_gpu_core3__branch_unit (
    input  wire [1:0]  ctrl,
    input  wire [3:0]  taken,
    input  wire [3:0]  tmask,
    input  wire [31:0] pc,
    input  wire [31:0] imm,
    input  wire [127:0] a,
    output wire [31:0] next_pc,
    output wire [31:0] link,
    output wire        diverged
);
    // lowest-numbered active lane
    wire [1:0] l = tmask[0] ? 2'd0 :
                   tmask[1] ? 2'd1 :
                   tmask[2] ? 2'd2 : 2'd3;
     wire taken_l = taken[l];
     wire [31:0] jalr_pc = (a[l*32 +: 32] + imm) & 32'hFFFFFFFE;
    wire [31:0] jalr_pc0 = (a[0*32 +: 32] + imm) & 32'hFFFFFFFE;
    wire [31:0] jalr_pc1 = (a[1*32 +: 32] + imm) & 32'hFFFFFFFE;
    wire [31:0] jalr_pc2 = (a[2*32 +: 32] + imm) & 32'hFFFFFFFE;
    wire [31:0] jalr_pc3 = (a[3*32 +: 32] + imm) & 32'hFFFFFFFE;
  
    assign link = pc + 32'd4;
 
    reg [31:0] npc;
    always @* begin
        case (ctrl)
            2'b00: npc = pc + 32'd4;                       // NONE
            2'b01: npc = taken_l ? (pc + imm) : (pc + 32'd4); // BRANCH
            2'b10: npc = pc + imm;                         // JAL
            2'b11: npc = jalr_pc;                          // JALR
            default: npc = pc + 32'd4;
        endcase
    end
 
    assign next_pc = (tmask == 4'b0000) ? (pc + 32'd4) : npc;

    // diverged: two active lanes would choose different next pcs (branch taken bits differ)
    reg div;
    always @* begin
         div = 1'b0;
         if (ctrl == 2'b01 && tmask != 4'b0000) begin
            if (tmask[0] && tmask[1] && (taken[0] != taken[1])) div = 1'b1;
            if (tmask[0] && tmask[2] && (taken[0] != taken[2])) div = 1'b1;
            if (tmask[0] && tmask[3] && (taken[0] != taken[3])) div = 1'b1;
            if (tmask[1] && tmask[2] && (taken[1] != taken[2])) div = 1'b1;
            if (tmask[1] && tmask[3] && (taken[1] != taken[3])) div = 1'b1;
            if (tmask[2] && tmask[3] && (taken[2] != taken[3])) div = 1'b1;
        end
        if (ctrl == 2'b11 && tmask != 4'b0000) begin
            if (tmask[0] && tmask[1] && (jalr_pc0 != jalr_pc1)) div = 1'b1;
            if (tmask[0] && tmask[2] && (jalr_pc0 != jalr_pc2)) div = 1'b1;
            if (tmask[0] && tmask[3] && (jalr_pc0 != jalr_pc3)) div = 1'b1;
            if (tmask[1] && tmask[2] && (jalr_pc1 != jalr_pc2)) div = 1'b1;
            if (tmask[1] && tmask[3] && (jalr_pc1 != jalr_pc3)) div = 1'b1;
            if (tmask[2] && tmask[3] && (jalr_pc2 != jalr_pc3)) div = 1'b1;
        end
    end

    assign diverged = div;
endmodule

module simt_gpu_core3__vote_shfl (
    input  [2:0]  simt_op,
    input  [1:0]  simt_mode,
    input  [3:0]  tmask,
    input  [127:0] a,
    input  [127:0] b,
    output [127:0] y
);

    integer l;
    reg [31:0] lane_y [0:3];
    reg [127:0] y_r;

    // ballot: active lanes whose lane of a is nonzero
    wire [3:0] nz;
    assign nz[0] = tmask[0] & (a[31:0]    != 32'd0);
    assign nz[1] = tmask[1] & (a[63:32]   != 32'd0);
    assign nz[2] = tmask[2] & (a[95:64]   != 32'd0);
    assign nz[3] = tmask[3] & (a[127:96]  != 32'd0);

    wire [3:0] ballot = nz;

    // vote result value
    reg [31:0] vote_val;
    always @* begin
        case (simt_mode)
            2'd0: vote_val = (ballot != 4'd0) ? 32'd1 : 32'd0;
            2'd1: vote_val = (ballot == tmask) ? 32'd1 : 32'd0;
            2'd2: vote_val = {28'd0, ballot};
            default: vote_val = 32'd0;
        endcase
    end

    // shuffle source lane per destination lane
    reg [1:0] s0, s1, s2, s3;
    wire [31:0] k0 = b[31:0];
    wire [31:0] k1 = b[63:32];
    wire [31:0] k2 = b[95:64];
    wire [31:0] k3 = b[127:96];

    // 3-bit arithmetic so the >= 4 / > l checks are real comparisons
    wire [2:0] big0 = {1'b0, k0[1:0]};
    wire [2:0] big1 = {1'b0, k1[1:0]};
    wire [2:0] big2 = {1'b0, k2[1:0]};
    wire [2:0] big3 = {1'b0, k3[1:0]};

    always @* begin
        case (simt_mode)
            2'd0: begin // idx: s = k mod 4
                s0 = k0[1:0];
                s1 = k1[1:0];
                s2 = k2[1:0];
                s3 = k3[1:0];
            end
            2'd1: begin // xor: s = (l xor k) mod 4
                s0 = 2'd0 ^ k0[1:0];
                s1 = 2'd1 ^ k1[1:0];
                s2 = 2'd2 ^ k2[1:0];
                s3 = 2'd3 ^ k3[1:0];
            end
            2'd2: begin // up: s = l - k, or l if k > l (k >= 4 or k > l)
                s0 = ((k0[31:2] != 30'd0) || (big0 > 3'd0)) ? 2'd0 : (2'd0 - k0[1:0]);
                s1 = ((k1[31:2] != 30'd0) || (big1 > 3'd1)) ? 2'd1 : (2'd1 - k1[1:0]);
                s2 = ((k2[31:2] != 30'd0) || (big2 > 3'd2)) ? 2'd2 : (2'd2 - k2[1:0]);
                s3 = ((k3[31:2] != 30'd0) || (big3 > 3'd3)) ? 2'd3 : (2'd3 - k3[1:0]);
            end
            default: begin // down: s = l + k, or l if l + k >= 4
                s0 = ((k0[31:2] != 30'd0) || ((3'd0 + big0) >= 3'd4)) ? 2'd0 : (2'd0 + k0[1:0]);
                s1 = ((k1[31:2] != 30'd0) || ((3'd1 + big1) >= 3'd4)) ? 2'd1 : (2'd1 + k1[1:0]);
                s2 = ((k2[31:2] != 30'd0) || ((3'd2 + big2) >= 3'd4)) ? 2'd2 : (2'd2 + k2[1:0]);
                s3 = ((k3[31:2] != 30'd0) || ((3'd3 + big3) >= 3'd4)) ? 2'd3 : (2'd3 + k3[1:0]);
            end
        endcase
    end

    always @* begin
        for (l = 0; l < 4; l = l + 1)
            lane_y[l] = 32'd0;
        case (simt_op)
            3'b101: begin // VOTE
                lane_y[0] = vote_val;
                lane_y[1] = vote_val;
                lane_y[2] = vote_val;
                lane_y[3] = vote_val;
            end
            3'b110: begin // SHFL
                lane_y[0] = a[s0*32 +: 32];
                lane_y[1] = a[s1*32 +: 32];
                lane_y[2] = a[s2*32 +: 32];
                lane_y[3] = a[s3*32 +: 32];
            end
            default: begin
                lane_y[0] = 32'd0;
                lane_y[1] = 32'd0;
                lane_y[2] = 32'd0;
                lane_y[3] = 32'd0;
            end
        endcase
    end

    assign y = {lane_y[3], lane_y[2], lane_y[1], lane_y[0]};

endmodule

module simt_gpu_core3__simt_ctrl (
    input  wire        valid,
    input  wire [2:0]  unit,
    input  wire        advance,
    input  wire [2:0]  simt_op,
    input  wire [3:0]  tmask,
    input  wire [31:0] pc,
    input  wire [31:0] br_next_pc,
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire [3:0]  top_mask,
    input  wire [31:0] top_pc,
    input  wire        top_fall,
    input  wire [3:0]  depth,
    output wire [31:0] c_pc,
    output wire [3:0]  c_tmask,
    output wire [1:0]  push,
    output wire [3:0]  e0_mask,
    output wire [31:0] e0_pc,
    output wire        e0_fall,
    output wire [3:0]  e1_mask,
    output wire [31:0] e1_pc,
    output wire        e1_fall,
    output wire        pop,
    output wire        clear,
    output wire [3:0]  spawn_mask,
    output wire [31:0] spawn_pc,
    output wire        bar_arrive,
    output wire [1:0]  bar_id,
    output wire [2:0]  bar_count,
    output wire        err
);

    // lowest-numbered active lane
    wire l0 = tmask[0] | (tmask == 4'b0000);        // lane 0 when no lane is active
    wire l1 = ~tmask[0] & tmask[1];
    wire l2 = ~tmask[0] & ~tmask[1] & tmask[2];
    wire l3 = ~tmask[0] & ~tmask[1] & ~tmask[2] & tmask[3];

    wire [31:0] fa = l0 ? a[31:0]   :
                     l1 ? a[63:32]  :
                     l2 ? a[95:64]  :
                          a[127:96];
    wire [31:0] fb = l0 ? b[31:0]   :
                     l1 ? b[63:32]  :
                     l2 ? b[95:64]  :
                          b[127:96];

    wire [31:0] p4 = pc + 32'd4;
    wire        is_simt = valid & (unit == 3'b100);

    // split predicate
    wire [3:0] pred = {a[127:96] != 32'd0, a[95:64] != 32'd0,
                       a[63:32]  != 32'd0, a[31:0]  != 32'd0};
    wire [3:0] sp_T = tmask & pred;
    wire [3:0] sp_F = tmask & ~pred;
    wire       t_nonz = |sp_T;
    wire       f_nonz = |sp_F;
    wire [1:0] sp_n   = (t_nonz & f_nonz) ? 2'd2 : 2'd1;
    wire       sp_ovf = (depth + {2'd0, sp_n}) > 4'd8;

    reg [31:0] c_pc_r;
    reg [3:0]  c_tmask_r;
    reg [1:0]  push_r;
    reg [3:0]  e0_mask_r;
    reg [31:0] e0_pc_r;
    reg        e0_fall_r;
    reg [3:0]  e1_mask_r;
    reg [31:0] e1_pc_r;
    reg        e1_fall_r;
    reg        pop_r;
    reg        clear_r;
    reg [3:0]  spawn_mask_r;
    reg [31:0] spawn_pc_r;
    reg        bar_arrive_r;
    reg [1:0]  bar_id_r;
    reg [2:0]  bar_count_r;
    reg        err_r;

    always @* begin
        c_pc_r       = br_next_pc;
        c_tmask_r    = tmask;
        push_r       = 2'd0;
        e0_mask_r    = 4'd0;
        e0_pc_r      = 32'd0;
        e0_fall_r    = 1'b0;
        e1_mask_r    = 4'd0;
        e1_pc_r      = 32'd0;
        e1_fall_r    = 1'b0;
        pop_r        = 1'b0;
        clear_r      = 1'b0;
        spawn_mask_r = 4'd0;
        spawn_pc_r   = 32'd0;
        bar_arrive_r = 1'b0;
        bar_id_r     = 2'd0;
        bar_count_r  = 3'd0;
        err_r        = 1'b0;

        if (is_simt) begin
            c_pc_r = p4;
            case (simt_op)
                3'b000: begin // TMC
                    c_tmask_r = fa[3:0];
                    clear_r   = (fa[3:0] == 4'd0);
                end
                3'b001: begin // WSPAWN
                    spawn_mask_r[3] = (32'd3 < fa);
                    spawn_mask_r[2] = (32'd2 < fa);
                    spawn_mask_r[1] = (32'd1 < fa);
                    spawn_mask_r[0] = 1'b0;
                    spawn_pc_r      = fb;
                end
                3'b010: begin // SPLIT
                    if (sp_ovf) begin
                        err_r = 1'b1;
                    end else begin
                        push_r    = sp_n;
                        e0_mask_r = tmask;
                        e0_pc_r   = 32'd0;
                        e0_fall_r = 1'b1;
                        if (sp_n == 2'd2) begin
                            e1_mask_r = sp_F;
                            e1_pc_r   = p4;
                            e1_fall_r = 1'b0;
                            c_tmask_r = sp_T;
                        end
                    end
                end
                3'b011: begin // JOIN
                    if (depth == 4'd0) begin
                        err_r = 1'b1;
                    end else begin
                        pop_r     = 1'b1;
                        c_tmask_r = top_mask;
                        c_pc_r    = top_fall ? p4 : top_pc;
                    end
                end
                3'b100: begin // BAR
                    bar_arrive_r = 1'b1;
                    bar_id_r     = fa[1:0];
                    bar_count_r  = (fb < 32'd7) ? fb[2:0] : 3'd7;
                    err_r        = (fa > 32'd3);
                end
                3'b101: begin // VOTE
                end
                3'b110: begin // SHFL
                end
                default: begin // 111
                end
            endcase
        end
    end

    assign c_pc       = c_pc_r;
    assign c_tmask    = c_tmask_r;
    assign push       = advance ? push_r : 2'd0;
    assign e0_mask    = e0_mask_r;
    assign e0_pc      = e0_pc_r;
    assign e0_fall    = e0_fall_r;
    assign e1_mask    = e1_mask_r;
    assign e1_pc      = e1_pc_r;
    assign e1_fall    = e1_fall_r;
    assign pop        = advance ? pop_r : 1'b0;
    assign clear      = advance ? clear_r : 1'b0;
    assign spawn_mask = advance ? spawn_mask_r : 4'd0;
    assign spawn_pc   = spawn_pc_r;
    assign bar_arrive = advance ? bar_arrive_r : 1'b0;
    assign bar_id     = bar_id_r;
    assign bar_count  = bar_count_r;
    assign err        = err_r;

endmodule

module simt_gpu_core3__ipdom (
    input  wire        clk,
    input  wire        rst,
    input  wire        clear_all,
    input  wire [1:0]  wid,
    input  wire        en,
    input  wire [1:0]  push,
    input  wire [3:0]  e0_mask,
    input  wire [31:0] e0_pc,
    input  wire        e0_fall,
    input  wire [3:0]  e1_mask,
    input  wire [31:0] e1_pc,
    input  wire        e1_fall,
    input  wire        pop,
    input  wire        clear,
    output wire [3:0]  depth,
    output wire [3:0]  top_mask,
    output wire [31:0] top_pc,
    output wire        top_fall
);

    reg [3:0]  mask_mem [0:3][0:7];
    reg [31:0] pc_mem   [0:3][0:7];
    reg        fall_mem [0:3][0:7];
    reg [3:0]  cnt      [0:3];

    integer i, j;
    initial begin
        for (i = 0; i < 4; i = i + 1) begin
            cnt[i] = 4'd0;
            for (j = 0; j < 8; j = j + 1) begin
                mask_mem[i][j] = 4'd0;
                pc_mem[i][j]   = 32'd0;
                fall_mem[i][j] = 1'b0;
            end
        end
    end

     wire [1:0] w = wid;

    always @(posedge clk) begin
        if (rst || clear_all) begin
            for (i = 0; i < 4; i = i + 1)
                cnt[i] <= 4'd0;
        end else if (en) begin
            if (clear) begin
                cnt[w] <= 4'd0;
            end else if (pop) begin
                if (cnt[w] != 4'd0)
                    cnt[w] <= cnt[w] - 4'd1;
             end else if (push == 2'd1) begin
                if (cnt[w] < 4'd8) begin
                    mask_mem[w][cnt[w]] <= e0_mask;
                    pc_mem[w][cnt[w]]   <= e0_pc;
                    fall_mem[w][cnt[w]] <= e0_fall;
                    cnt[w]              <= cnt[w] + 4'd1;
                end
             end else if (push == 2'd2) begin
                if (cnt[w] < 4'd8) begin
                    mask_mem[w][cnt[w]] <= e0_mask;
                    pc_mem[w][cnt[w]]   <= e0_pc;
                    fall_mem[w][cnt[w]] <= e0_fall;
                    if (cnt[w] + 4'd1 < 4'd8) begin
                        mask_mem[w][cnt[w]+4'd1] <= e1_mask;
                        pc_mem[w][cnt[w]+4'd1]   <= e1_pc;
                        fall_mem[w][cnt[w]+4'd1] <= e1_fall;
                        cnt[w] <= cnt[w] + 4'd2;
                    end else begin
                        cnt[w] <= cnt[w] + 4'd1;
                    end
                end
            end
        end
    end

     assign depth    = cnt[w][3:0];
    assign top_mask = (cnt[w] == 4'd0) ? 4'd0 : mask_mem[w][cnt[w]-4'd1];
    assign top_pc   = (cnt[w] == 4'd0) ? 32'd0 : pc_mem[w][cnt[w]-4'd1];
    assign top_fall = (cnt[w] == 4'd0) ? 1'b0 : fall_mem[w][cnt[w]-4'd1];

endmodule

module simt_gpu_core3__barrier_unit (
    input  wire       clk,
    input  wire       rst,
    input  wire       clear_all,
    input  wire       en,
    input  wire [1:0] wid,
    input  wire [1:0] bar_id,
    input  wire [2:0] bar_count,
    output reg  [3:0] waiting
);

    reg [3:0] arrived [0:3];
    wire [3:0] m;
    wire [2:0] cnt;
    integer i;

    assign m = arrived[bar_id] | (4'b0001 << wid);

    assign cnt = {2'b00, m[0]}
               + {2'b00, m[1]}
               + {2'b00, m[2]}
               + {2'b00, m[3]};

    always @(posedge clk) begin
        if (rst || clear_all) begin
            for (i = 0; i < 4; i = i + 1) begin
                arrived[i] <= 4'b0000;
            end
            waiting <= 4'b0000;
        end else if (en) begin
            if (cnt >= bar_count) begin
                arrived[bar_id] <= 4'b0000;
                waiting <= waiting & ~m;
            end else begin
                arrived[bar_id] <= m;
                waiting <= waiting | (4'b0001 << wid);
            end
        end
    end

endmodule

module simt_gpu_core3__tensor_unit (
    input  wire         clk,
    input  wire         rst,
    input  wire         clear_all,
    input  wire         valid,
    input  wire  [2:0]  unit,
    input  wire         advance,
    input  wire  [1:0]  tensor_op,
    input  wire  [1:0]  wid,
    input  wire  [3:0]  tmask,
    input  wire  [127:0] a,
    input  wire  [127:0] b,
    output wire  [127:0] ld_y,
    output wire         err
);

    localparam TENSOR = 3'b101;

    wire is_t = valid & (unit == TENSOR);
    assign err = is_t & (tmask != 4'b1111);

    // flat accumulator: element 16*wid + 4*i + j
    reg [31:0] acc [0:63];

    integer z;
    initial begin
        for (z = 0; z < 64; z = z + 1) acc[z] = 32'd0;
    end

    // combinational read: lane i gets ACC[wid][i][c], c = lane i of a bits 1:0
    genvar gi;
    generate
        for (gi = 0; gi < 4; gi = gi + 1) begin : g_ld
            wire [1:0] c = a[32*gi +: 2];
            assign ld_y[32*gi +: 32] = acc[16*wid + 4*gi + c];
        end
    endgenerate

    integer i, j, k;
    reg [31:0] sum;
    reg [7:0] av, bv;
    reg [1:0] cs;

    always @(posedge clk) begin
        if (rst | clear_all) begin
            for (z = 0; z < 64; z = z + 1)
                acc[z] <= 32'd0;
        end else if (advance & is_t & !err) begin
            case (tensor_op)
                2'b00: begin // MMA_I8
                    for (i = 0; i < 4; i = i + 1) begin
                        for (j = 0; j < 4; j = j + 1) begin
                            sum = acc[16*wid + 4*i + j];
                            for (k = 0; k < 4; k = k + 1) begin
                                av = a[32*i + 8*k +: 8];
                                bv = b[32*j + 8*k +: 8];
                                sum = sum + {{24{av[7]}}, av} * {{24{bv[7]}}, bv};
                            end
                            acc[16*wid + 4*i + j] <= sum;
                        end
                    end
                end
                2'b01: begin // MMA_LD: nothing changes
                end
                2'b10: begin // MMA_ST
                    for (i = 0; i < 4; i = i + 1) begin
                        cs = b[32*i +: 2];
                        acc[16*wid + 4*i + cs] <= a[32*i +: 32];
                    end
                end
                2'b11: begin // MMA_ZERO
                    for (i = 0; i < 4; i = i + 1)
                        for (j = 0; j < 4; j = j + 1)
                            acc[16*wid + 4*i + j] <= 32'd0;
                end
                default: begin
                end
            endcase
        end
    end

endmodule

module simt_gpu_core3__csr (
    input  wire [11:0] csr_addr,
    input  wire        valid,
    input  wire [2:0]  unit,
    input  wire [1:0]  wid,
    input  wire [3:0]  tmask,
    input  wire [31:0] karg,
    input  wire [47:0] cycle,
    output wire [127:0] y,
    output wire        err
);
    reg [31:0] lane_val;
    reg [127:0] y_r;
    integer l;

    always @* begin
        y_r = 128'd0;
        for (l = 0; l < 4; l = l + 1) begin
            case (csr_addr)
                12'hCC0: lane_val = l[31:0];
                12'hCC1: lane_val = {30'd0, wid};
                12'hCC2: lane_val = 32'd0;
                12'hCC3: lane_val = {28'd0, tmask};
                12'hCC4: lane_val = {28'd0, wid} * 32'd4 + l[31:0];
                12'hCC5: lane_val = karg;
                12'hFC0: lane_val = 32'd4;
                12'hFC1: lane_val = 32'd4;
                12'hFC2: lane_val = 32'd1;
                12'hC00: lane_val = cycle[31:0];
                12'hC02: lane_val = cycle[31:0];
                12'hC80: lane_val = {16'd0, cycle[47:32]};
                12'hC82: lane_val = {16'd0, cycle[47:32]};
                default: lane_val = 32'd0;
            endcase
            y_r[l*32 +: 32] = lane_val;
        end
    end

    assign y = y_r;
    assign err = valid && (unit == 3'b110) &&
                 !((csr_addr == 12'hCC0) || (csr_addr == 12'hCC1) ||
                   (csr_addr == 12'hCC2) || (csr_addr == 12'hCC3) ||
                   (csr_addr == 12'hCC4) || (csr_addr == 12'hCC5) ||
                   (csr_addr == 12'hFC0) || (csr_addr == 12'hFC1) ||
                   (csr_addr == 12'hFC2) || (csr_addr == 12'hC00) ||
                   (csr_addr == 12'hC02) || (csr_addr == 12'hC80) ||
                   (csr_addr == 12'hC82));
endmodule

module simt_gpu_core3__cycle_ctr (
    input  wire        clk,
    input  wire        rst,
    input  wire        enable,
    output wire [47:0] count
);

    reg [47:0] count_r;

    always @(posedge clk) begin
        if (rst)
            count_r <= 48'd0;
        else if (enable)
            count_r <= count_r + 48'd1;
    end

    assign count = count_r;

endmodule

// lsu: the load-store unit (demos/simt-gpu/README.md section 6, golden/lsu.py).
// HAND-WRITTEN from the golden model: the BARG-generated version (rtl/generated/lsu.v) lost the upper byte of a halfword load
// served in a later cycle of a bank-conflict sequence.
module simt_gpu_core3__lsu(
    input clk, rst, clear, valid,
    input [2:0] unit,
    input mem_store,
    input [2:0] mem_size,
    input [3:0] tmask,
    input [127:0] a, b,
    input [31:0] imm,
    input advance,
    input [127:0] g_rdata, s_rdata,
    output reg [3:0] g_en, g_we,
    output reg [35:0] g_addr,
    output reg [127:0] g_wdata,
    output reg [15:0] g_be,
    output reg [3:0] s_en, s_we,
    output reg [31:0] s_addr,
    output reg [127:0] s_wdata,
    output reg [15:0] s_be,
    output reg ready,
    output reg [127:0] y,
    output reg err
);

    reg        started;
    reg [3:0]  pend, got;
    reg [127:0] cap;

    wire act = valid & (unit == 3'd3);
    wire [2:0] nbytes = (mem_size == 3'd0 || mem_size == 3'd4) ? 3'd1 :
                        (mem_size == 3'd1 || mem_size == 3'd5) ? 3'd2 : 3'd4;
    wire signed_load = (mem_size == 3'd0 || mem_size == 3'd1);

    // per-lane decode
    reg [31:0] A [0:3];
    reg [3:0]  in_g, in_s, bad;
    reg [1:0]  bank [0:3];
    reg [1:0]  off [0:3];
    reg [8:0]  widx [0:3];
    integer k, j;
    always @* begin
        for (k = 0; k < 4; k = k + 1) begin
            A[k]    = a[32*k +: 32] + imm;
            in_g[k] = (A[k][31:13] == 19'h08000);          // 0x1000_0000 .. 0x1000_1FFF
            in_s[k] = (A[k][31:12] == 20'h20000);          // 0x2000_0000 .. 0x2000_0FFF
            bank[k] = A[k][3:2];
            off[k]  = A[k][1:0];
            widx[k] = in_g[k] ? A[k][12:4] : {1'b0, A[k][11:4]};
            bad[k]  = ~(in_g[k] | in_s[k]) | ((nbytes == 3'd2) & A[k][0]) | ((nbytes == 3'd4) & (A[k][1:0] != 2'b00));
        end
    end

    wire lsu_err = act & ~started & (|(tmask & bad));
    wire [3:0] P = started ? pend : tmask;

    // the lowest-numbered lane of P mapped to each (memory, bank) is chosen
    reg [3:0] chosen;
    always @* begin
        chosen = 4'b0000;
        for (k = 0; k < 4; k = k + 1) begin
            chosen[k] = P[k];
            for (j = 0; j < 4; j = j + 1)
                if (j < k && P[j] && (in_g[j] == in_g[k]) && (bank[j] == bank[k])) chosen[k] = 1'b0;
        end
        if (!act || lsu_err) chosen = 4'b0000;
    end

    // requests to the banks
    reg [3:0] be_lane;
    always @* begin
        g_en = 4'b0; g_we = 4'b0; g_addr = 36'd0; g_wdata = 128'd0; g_be = 16'd0;
        s_en = 4'b0; s_we = 4'b0; s_addr = 32'd0; s_wdata = 128'd0; s_be = 16'd0;
        for (k = 0; k < 4; k = k + 1) begin
            be_lane = ((4'b0001 << nbytes) - 4'b0001) << off[k];
            if (chosen[k] && in_g[k]) begin
                g_en[bank[k]] = 1'b1;
                g_we[bank[k]] = mem_store;
                g_addr[9*bank[k] +: 9] = widx[k];
                g_wdata[32*bank[k] +: 32] = b[32*k +: 32] << (8 * off[k]);
                g_be[4*bank[k] +: 4] = be_lane;
            end
            if (chosen[k] && in_s[k]) begin
                s_en[bank[k]] = 1'b1;
                s_we[bank[k]] = mem_store;
                s_addr[8*bank[k] +: 8] = widx[k][7:0];
                s_wdata[32*bank[k] +: 32] = b[32*k +: 32] << (8 * off[k]);
                s_be[4*bank[k] +: 4] = be_lane;
            end
        end
    end

    // loaded data: the lanes whose word arrives this cycle replace their lane of cap
    reg [127:0] cur;
    reg [31:0] word, shifted, ext;
    always @* begin
        cur = cap;
        for (k = 0; k < 4; k = k + 1) begin
            word = in_g[k] ? g_rdata[32*bank[k] +: 32] : s_rdata[32*bank[k] +: 32];
            shifted = word >> (8 * off[k]);
            case (nbytes)
                3'd1:    ext = signed_load ? {{24{shifted[7]}},  shifted[7:0]}  : {24'd0, shifted[7:0]};
                3'd2:    ext = signed_load ? {{16{shifted[15]}}, shifted[15:0]} : {16'd0, shifted[15:0]};
                default: ext = shifted;
            endcase
            if (got[k]) cur[32*k +: 32] = ext;
        end
    end

    always @* begin
        err   = act ? lsu_err : 1'b0;
        y     = act ? cur : cap;
        ready = act & (lsu_err | (mem_store & ((P & ~chosen) == 4'b0000)) | (~mem_store & started & (P == 4'b0000)));
    end

    always @(posedge clk) begin
        if (rst) begin
            started <= 1'b0; pend <= 4'b0; got <= 4'b0; cap <= 128'd0;
        end else if (clear | advance) begin
            started <= 1'b0; pend <= 4'b0; got <= 4'b0;
        end else if (act & ~lsu_err) begin
            started <= 1'b1;
            pend    <= P & ~chosen;
            got     <= mem_store ? 4'b0000 : chosen;
            cap     <= cur;
        end
    end

endmodule

module simt_gpu_core3__bank_mux (
    input  wire         running,
    input  wire [3:0]   g_en,
    input  wire [3:0]   g_we,
    input  wire [35:0]  g_addr,
    input  wire [127:0] g_wdata,
    input  wire [15:0]  g_be,
    input  wire [3:0]   s_en,
    input  wire [3:0]   s_we,
    input  wire [31:0]  s_addr,
    input  wire [127:0] s_wdata,
    input  wire [15:0]  s_be,
    input  wire         host_en,
    input  wire         host_we,
    input  wire [31:0]  host_addr,
    input  wire [31:0]  host_wdata,
    input  wire [31:0]  gb0_rdata,
    input  wire [31:0]  gb1_rdata,
    input  wire [31:0]  gb2_rdata,
    input  wire [31:0]  gb3_rdata,
    input  wire [31:0]  sb0_rdata,
    input  wire [31:0]  sb1_rdata,
    input  wire [31:0]  sb2_rdata,
    input  wire [31:0]  sb3_rdata,
    output wire         gb0_we,
    output wire [8:0]   gb0_addr,
    output wire [31:0]  gb0_wdata,
    output wire [3:0]   gb0_be,
    output wire         gb1_we,
    output wire [8:0]   gb1_addr,
    output wire [31:0]  gb1_wdata,
    output wire [3:0]   gb1_be,
    output wire         gb2_we,
    output wire [8:0]   gb2_addr,
    output wire [31:0]  gb2_wdata,
    output wire [3:0]   gb2_be,
    output wire         gb3_we,
    output wire [8:0]   gb3_addr,
    output wire [31:0]  gb3_wdata,
    output wire [3:0]   gb3_be,
    output wire         sb0_we,
    output wire [7:0]   sb0_addr,
    output wire [31:0]  sb0_wdata,
    output wire [3:0]   sb0_be,
    output wire         sb1_we,
    output wire [7:0]   sb1_addr,
    output wire [31:0]  sb1_wdata,
    output wire [3:0]   sb1_be,
    output wire         sb2_we,
    output wire [7:0]   sb2_addr,
    output wire [31:0]  sb2_wdata,
    output wire [3:0]   sb2_be,
    output wire         sb3_we,
    output wire [7:0]   sb3_addr,
    output wire [31:0]  sb3_wdata,
    output wire [3:0]   sb3_be,
    output wire         imem_we,
    output wire [8:0]   imem_waddr,
    output wire [31:0]  imem_wdata,
    output wire [127:0] g_rdata,
    output wire [127:0] s_rdata
);

    // Host address decode
    wire host_imem = (host_addr[31:11] == 21'd0);
    wire host_gmem = (host_addr[31:13] == 19'h08000);
    wire host_smem = (host_addr[31:12] == 20'h20000);

    wire [1:0] host_bank = host_addr[3:2];
    wire host_gwe = host_en & host_we;
    wire [8:0] host_gaddr = (host_addr - 32'h1000_0000) >> 4;
    wire [7:0] host_saddr = (host_addr - 32'h2000_0000) >> 4;

    // Global banks
    assign gb0_we    = running ? (g_en[0] & g_we[0]) : (host_gmem & host_gwe & (host_bank == 2'd0));
    assign gb0_addr  = running ? g_addr[8:0]   : host_gaddr;
    assign gb0_wdata = running ? g_wdata[31:0] : host_wdata;
    assign gb0_be    = running ? g_be[3:0]     : 4'hF;

    assign gb1_we    = running ? (g_en[1] & g_we[1]) : (host_gmem & host_gwe & (host_bank == 2'd1));
    assign gb1_addr  = running ? g_addr[17:9]  : host_gaddr;
    assign gb1_wdata = running ? g_wdata[63:32] : host_wdata;
    assign gb1_be    = running ? g_be[7:4]     : 4'hF;

    assign gb2_we    = running ? (g_en[2] & g_we[2]) : (host_gmem & host_gwe & (host_bank == 2'd2));
    assign gb2_addr  = running ? g_addr[26:18] : host_gaddr;
    assign gb2_wdata = running ? g_wdata[95:64] : host_wdata;
    assign gb2_be    = running ? g_be[11:8]    : 4'hF;

    assign gb3_we    = running ? (g_en[3] & g_we[3]) : (host_gmem & host_gwe & (host_bank == 2'd3));
    assign gb3_addr  = running ? g_addr[35:27] : host_gaddr;
    assign gb3_wdata = running ? g_wdata[127:96] : host_wdata;
    assign gb3_be    = running ? g_be[15:12]   : 4'hF;

    // Shared banks
    assign sb0_we    = running ? (s_en[0] & s_we[0]) : (host_smem & host_gwe & (host_bank == 2'd0));
    assign sb0_addr  = running ? s_addr[7:0]   : host_saddr;
    assign sb0_wdata = running ? s_wdata[31:0] : host_wdata;
    assign sb0_be    = running ? s_be[3:0]     : 4'hF;

    assign sb1_we    = running ? (s_en[1] & s_we[1]) : (host_smem & host_gwe & (host_bank == 2'd1));
    assign sb1_addr  = running ? s_addr[15:8]  : host_saddr;
    assign sb1_wdata = running ? s_wdata[63:32] : host_wdata;
    assign sb1_be    = running ? s_be[7:4]     : 4'hF;

    assign sb2_we    = running ? (s_en[2] & s_we[2]) : (host_smem & host_gwe & (host_bank == 2'd2));
    assign sb2_addr  = running ? s_addr[23:16] : host_saddr;
    assign sb2_wdata = running ? s_wdata[95:64] : host_wdata;
    assign sb2_be    = running ? s_be[11:8]    : 4'hF;

    assign sb3_we    = running ? (s_en[3] & s_we[3]) : (host_smem & host_gwe & (host_bank == 2'd3));
    assign sb3_addr  = running ? s_addr[31:24] : host_saddr;
    assign sb3_wdata = running ? s_wdata[127:96] : host_wdata;
    assign sb3_be    = running ? s_be[15:12]   : 4'hF;

    // Instruction memory write port
    assign imem_we    = running ? 1'b0 : (host_imem & host_gwe);
    assign imem_waddr = host_addr[10:2];
    assign imem_wdata = host_wdata;

    // Read data packing
    assign g_rdata = {gb3_rdata, gb2_rdata, gb1_rdata, gb0_rdata};
    assign s_rdata = {sb3_rdata, sb2_rdata, sb1_rdata, sb0_rdata};

endmodule

module simt_gpu_core3__gbank0 (
    input  wire        clk,
    input  wire [8:0]  addr,
    input  wire        we,
    input  wire [31:0] wdata,
    input  wire [3:0]  be,
    output reg  [31:0] rdata
);

    reg [31:0] mem [0:511];

    integer i;
    initial begin
        for (i = 0; i < 512; i = i + 1)
            mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (we) begin
            if (be[0]) mem[addr][7:0]   <= wdata[7:0];
            if (be[1]) mem[addr][15:8]  <= wdata[15:8];
            if (be[2]) mem[addr][23:16] <= wdata[23:16];
            if (be[3]) mem[addr][31:24] <= wdata[31:24];
        end
        rdata <= mem[addr];
    end

endmodule

