        end else begin
            rdata_r <= mem[addr];
        end
    end

    assign rdata = rdata_r;

endmodule

module simt_gpu_core3__sbank3(
    input  wire        clk,
    input  wire [7:0]  addr,
    input  wire        we,
    input  wire [31:0] wdata,
    input  wire [3:0]  be,
    output wire [31:0] rdata
);

    reg [31:0] mem [0:255];
    reg [31:0] rdata_reg;
    integer i;

    initial begin
        for (i = 0; i < 256; i = i + 1)
            mem[i] = 32'd0;
        rdata_reg = 32'd0;
    end

    always @(posedge clk) begin
        rdata_reg <= mem[addr];
        if (we) begin
            if (be[0]) mem[addr][7:0]   <= wdata[7:0];
            if (be[1]) mem[addr][15:8]  <= wdata[15:8];
            if (be[2]) mem[addr][23:16] <= wdata[23:16];
            if (be[3]) mem[addr][31:24] <= wdata[31:24];
        end
    end

    assign rdata = rdata_reg;

endmodule

module simt_gpu_core3__wb_mux (
    input  wire        advance,
    input  wire        regwrite,
    input  wire [4:0]  rd,
    input  wire [1:0]  wid,
    input  wire [3:0]  tmask,
    input  wire [2:0]  wb_src,
    input  wire [127:0] alu_y,
    input  wire [127:0] mul_y,
    input  wire [127:0] div_y,
    input  wire [127:0] load_y,
    input  wire [127:0] simt_y,
    input  wire [127:0] tensor_y,
    input  wire [127:0] csr_y,
    input  wire [31:0]  link,
    output wire        we0,
    output wire        we1,
    output wire        we2,
    output wire        we3,
    output wire [6:0]  waddr,
    output wire [31:0] wdata0,
    output wire [31:0] wdata1,
    output wire [31:0] wdata2,
    output wire [31:0] wdata3
);
     wire w = advance & regwrite & (rd != 5'd0);

    reg [127:0] r;
    always @* begin
        case (wb_src)
            3'b000: r = alu_y;
            3'b001: r = mul_y;
            3'b010: r = div_y;
            3'b011: r = load_y;
            3'b100: r = simt_y;
            3'b101: r = tensor_y;
            3'b110: r = csr_y;
            3'b111: r = {link, link, link, link};
            default: r = {32'd0, 32'd0, 32'd0, 32'd0};
        endcase
    end

    assign we0 = w & tmask[0];
    assign we1 = w & tmask[1];
    assign we2 = w & tmask[2];
    assign we3 = w & tmask[3];

     assign waddr  = {wid, rd};

    assign wdata0 = r[31:0];
    assign wdata1 = r[63:32];
    assign wdata2 = r[95:64];
    assign wdata3 = r[127:96];
endmodule

module simt_gpu_core3__host_if (
    input  wire        clk,
    input  wire        rst,
    input  wire        host_en,
    input  wire        host_we,
    input  wire [31:0] host_addr,
    input  wire [31:0] host_wdata,
    input  wire        busy,
    input  wire        advance,
    input  wire [31:0] x_pc,
    input  wire [1:0]  x_wid,
    input  wire        err_illegal,
    input  wire        err_mem,
    input  wire        err_simt,
    input  wire        err_tensor,
    input  wire        err_csr,
    input  wire [127:0] g_rdata,
    input  wire [127:0] s_rdata,
    output wire [31:0] host_rdata,
    output wire        host_rvalid,
    output wire        running,
    output wire        start,
    output wire [31:0] start_pc,
    output wire [31:0] karg,
    output wire        done,
    output wire        error
);

    reg        running_r;
    reg        done_r;
    reg        error_r;
    reg [31:0] start_pc_r;
    reg [31:0] karg_r;
    reg [31:0] err_pc_r;
    reg [9:0]  err_info_r;
    reg        rvalid_r;
    reg [31:0] raddr_r;

    assign running   = running_r;
    assign done      = done_r;
    assign error     = error_r;
    assign start_pc  = start_pc_r;
    assign karg      = karg_r;
    assign host_rvalid = rvalid_r;

    assign start = host_en & host_we & (host_addr == 32'h3000_0000)
                 & host_wdata[0] & ~running_r;

    // cause priority
    reg [3:0] cause;
    always @* begin
        if (err_illegal)      cause = 4'd1;
        else if (err_mem)     cause = 4'd2;
        else if (err_simt)    cause = 4'd3;
        else if (err_tensor)  cause = 4'd4;
        else if (err_csr)     cause = 4'd5;
        else                  cause = 4'd0;
    end

    wire any_cause = err_illegal | err_mem | err_simt | err_tensor | err_csr;

    wire host_wr = host_en & host_we;
    wire wr_start_pc = host_wr & ~running_r & (host_addr == 32'h3000_0004);
    wire wr_karg     = host_wr & ~running_r & (host_addr == 32'h3000_0008);

    always @(posedge clk) begin
        if (rst) begin
            running_r   <= 1'b0;
            done_r      <= 1'b0;
            error_r     <= 1'b0;
            start_pc_r  <= 32'd0;
            karg_r      <= 32'd0;
            err_pc_r    <= 32'd0;
            err_info_r  <= 10'd0;
            rvalid_r    <= 1'b0;
            raddr_r     <= 32'd0;
        end else begin
            if (wr_start_pc) start_pc_r <= host_wdata;
            if (wr_karg)     karg_r     <= host_wdata;

            if (start) begin
                running_r <= 1'b1;
                done_r    <= 1'b0;
                error_r   <= 1'b0;
            end else if (running_r & advance & any_cause) begin
                running_r  <= 1'b0;
                error_r    <= 1'b1;
                err_pc_r   <= x_pc;
                err_info_r <= {x_wid, 4'b0000, cause};
            end else if (running_r & ~busy) begin
                running_r <= 1'b0;
                done_r    <= 1'b1;
            end

            rvalid_r <= host_en & ~host_we;
            raddr_r  <= host_addr;
        end
    end

    // read data mux (combinational from raddr)
    wire in_g = (raddr_r >= 32'h1000_0000) && (raddr_r <= 32'h1000_1FFF);
    wire in_s = (raddr_r >= 32'h2000_0000) && (raddr_r <= 32'h2000_0FFF);
    wire [1:0] word_sel = raddr_r[3:2];

    reg [31:0] ctrl_rdata;
    always @* begin
        case (raddr_r)
            32'h3000_0000: ctrl_rdata = 32'd0;
            32'h3000_0004: ctrl_rdata = start_pc_r;
            32'h3000_0008: ctrl_rdata = karg_r;
            32'h3000_000C: ctrl_rdata = {29'd0, error_r, done_r, running_r};
            32'h3000_0010: ctrl_rdata = err_pc_r;
            32'h3000_0014: ctrl_rdata = {22'd0, err_info_r};
            default:       ctrl_rdata = 32'd0;
        endcase
    end

    assign host_rdata = in_g ? g_rdata[word_sel*32 +: 32]
                      : in_s ? s_rdata[word_sel*32 +: 32]
                      : ctrl_rdata;

endmodule

module simt_gpu_core3__gfx_host (
    input wire clk,
    input wire rst,
    input wire host_en,
    input wire host_we,
    input wire [31:0] host_addr,
    input wire [31:0] host_wdata,
    input wire [31:0] core_rdata,
    input wire [15:0] vw_rdata0,
    input wire [15:0] vw_rdata1,
    input wire [15:0] vw_rdata2,
    input wire [15:0] vw_rdata3,
    input wire vblank,
    input wire [7:0] frame,
    output wire v_we0,
    output wire v_we1,
    output wire v_we2,
    output wire v_we3,
    output wire [14:0] v_waddr,
    output wire [15:0] v_wdata_lo,
    output wire [15:0] v_wdata_hi,
    output wire [14:0] vw_raddr,
    output wire [31:0] host_rdata,
    output reg disp_en
);
    reg [31:0] raddr;

    wire host_in_win;
    wire raddr_in_win;
    wire wr;
    wire [31:0] vwin_rdata;

    assign host_in_win = (host_addr[31:18] == 14'h1000) &&
                         (host_addr[17:0] < 18'h25800) &&
                         (host_addr[1:0] == 2'b00);

    assign raddr_in_win = (raddr[31:18] == 14'h1000) &&
                          (raddr[17:0] < 18'h25800) &&
                          (raddr[1:0] == 2'b00);

    assign wr = host_en & host_we & host_in_win;

    assign v_we0 = wr & ~host_addr[2];
    assign v_we1 = wr & ~host_addr[2];
    assign v_we2 = wr & host_addr[2];
    assign v_we3 = wr & host_addr[2];

    assign v_waddr = host_addr[17:3];
    assign v_wdata_lo = host_wdata[15:0];
    assign v_wdata_hi = host_wdata[31:16];
    assign vw_raddr = host_addr[17:3];

    assign vwin_rdata = raddr[2] ? {vw_rdata3, vw_rdata2} : {vw_rdata1, vw_rdata0};

    assign host_rdata = raddr_in_win ? vwin_rdata :
                        (raddr == 32'h3000_0020) ? {31'b0, disp_en} :
                        (raddr == 32'h3000_0024) ? {16'b0, frame[7:0], 7'b0, vblank} :
                        core_rdata;

    always @(posedge clk) begin
        if (rst) begin
            raddr <= 32'd0;
            disp_en <= 1'b0;
        end else begin
            raddr <= host_addr;
            if (host_en & host_we & (host_addr == 32'h3000_0020))
                disp_en <= host_wdata[0];
        end
    end
endmodule

module simt_gpu_core3__disp_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        enable,
    input  wire [15:0] vd_rdata0,
    input  wire [15:0] vd_rdata1,
    input  wire [15:0] vd_rdata2,
    input  wire [15:0] vd_rdata3,
    output wire [14:0] vd_raddr,
    output wire        hsync,
    output wire        vsync,
    output wire        de,
    output wire [15:0] rgb,
    output wire        vblank,
    output wire [7:0]  frame
);

    reg [9:0]  hc, vc;
    reg [7:0]  frame_r;
    reg [9:0]  d_hc, d_vc;
    reg        d_on;

    wire [14:0] addr_vis = (vc >> 1) * 10'd80 + (hc >> 3);
    assign vd_raddr = (hc < 10'd640 && vc < 10'd480) ? addr_vis : 15'd0;

    assign vblank = (vc >= 10'd480);
    assign frame  = frame_r;

    wire vis = d_on & (d_hc < 10'd640) & (d_vc < 10'd480);
    assign de = vis;

    reg [15:0] rgb_sel;
    always @* begin
        case ((d_hc >> 1) & 3)
            2'd0: rgb_sel = vd_rdata0;
            2'd1: rgb_sel = vd_rdata1;
            2'd2: rgb_sel = vd_rdata2;
            default: rgb_sel = vd_rdata3;
        endcase
    end
    assign rgb = vis ? rgb_sel : 16'd0;

    assign hsync = (d_on && (d_hc >= 10'd656) && (d_hc < 10'd752)) ? 1'b0 : 1'b1;
    assign vsync = (d_on && (d_vc >= 10'd490) && (d_vc < 10'd492)) ? 1'b0 : 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            hc      <= 10'd0;
            vc      <= 10'd0;
            frame_r <= 8'd0;
            d_hc    <= 10'd0;
            d_vc    <= 10'd0;
            d_on    <= 1'b0;
        end else if (!enable) begin
            hc   <= 10'd0;
            vc   <= 10'd0;
            d_on <= 1'b0;
        end else begin
            d_hc <= hc;
            d_vc <= vc;
            d_on <= 1'b1;
            if (hc == 10'd799) begin
                hc <= 10'd0;
                if (vc == 10'd524) begin
                    vc      <= 10'd0;
                    frame_r <= frame_r + 8'd1;
                end else begin
                    vc <= vc + 10'd1;
                end
            end else begin
                hc <= hc + 10'd1;
            end
        end
    end

endmodule

module simt_gpu_core3__gfx_regs (
    input wire clk,
    input wire rst,
    input wire clear,
    input wire valid,
    input wire advance,
    input wire gfx,
    input wire [2:0] gfx_op,
    input wire [3:0] tmask,
    input wire [127:0] a,
    input wire [127:0] b,
    output reg [8:0] sc_x0,
    output reg [8:0] sc_y0,
    output reg [8:0] sc_x1,
    output reg [8:0] sc_y1
);
    wire do_cfg;
    wire [1:0] lane;
    wire [31:0] reg_no;
    wire [31:0] reg_val;

    assign do_cfg = valid & advance & gfx & (gfx_op == 3'd0) & (tmask != 4'd0);
    assign lane = tmask[0] ? 2'd0 :
                  tmask[1] ? 2'd1 :
                  tmask[2] ? 2'd2 : 2'd3;
    assign reg_no = a[lane * 32 +: 32];
    assign reg_val = b[lane * 32 +: 32];

    always @(posedge clk) begin
        if (rst || clear) begin
            sc_x0 <= 9'd0;
            sc_y0 <= 9'd0;
            sc_x1 <= 9'd320;
            sc_y1 <= 9'd240;
        end else if (do_cfg) begin
            case (reg_no)
                32'd0: sc_x0 <= reg_val[8:0];
                32'd1: sc_y0 <= reg_val[8:0];
                32'd2: sc_x1 <= reg_val[8:0];
                32'd3: sc_y1 <= reg_val[8:0];
                default: begin
                end
            endcase
        end
    end
endmodule

module simt_gpu_core3__rop_unit (
    input  wire         valid,
    input  wire         advance,
    input  wire         gfx,
    input  wire  [2:0]  gfx_op,
    input  wire  [3:0]  tmask,
    input  wire  [127:0] a,
    input  wire  [127:0] b,
    input  wire  [8:0]  sc_x0,
    input  wire  [8:0]  sc_y0,
    input  wire  [8:0]  sc_x1,
    input  wire  [8:0]  sc_y1,
    input  wire         blend,
    input  wire  [15:0] vw_rdata0,
    input  wire  [15:0] vw_rdata1,
    input  wire  [15:0] vw_rdata2,
    input  wire  [15:0] vw_rdata3,
    output wire         r_we0,
    output wire         r_we1,
    output wire         r_we2,
    output wire         r_we3,
    output wire  [14:0] r_waddr0,
    output wire  [14:0] r_waddr1,
    output wire  [14:0] r_waddr2,
    output wire  [14:0] r_waddr3,
    output wire  [15:0] r_wdata0,
    output wire  [15:0] r_wdata1,
    output wire  [15:0] r_wdata2,
    output wire  [15:0] r_wdata3,
    output wire  [14:0] r_raddr0,
    output wire  [14:0] r_raddr1,
    output wire  [14:0] r_raddr2,
    output wire  [14:0] r_raddr3
);

    wire act = valid & advance & gfx & (gfx_op == 3'd5);
    wire pre = valid & gfx & (gfx_op == 3'd5);

    // blend helper: (s*a + d*(255-a)) / 255 rounded
    function [7:0] blend_ch;
        input [7:0] s;
        input [7:0] d;
        input [7:0] aa;
        reg [15:0] xv;
        reg [15:0] xb;
        begin
            xv = s * aa + d * (8'd255 - aa);
            xb = xv + 16'd128;
            blend_ch = (xb + (xb >> 8)) >> 8;
        end
    endfunction

    // per-lane signals
    wire [15:0] lx  [0:3];
    wire [15:0] ly  [0:3];
    wire [31:0] col [0:3];
    wire        en  [0:3];
    wire        draww [0:3];
    wire        drawp [0:3];
    wire [1:0]  bk  [0:3];
    wire [14:0] ix  [0:3];
    wire [15:0] wd  [0:3];

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : LANE
            wire [31:0] pos = a[g*32 +: 32];
            assign lx[g]  = pos[15:0];
            assign ly[g]  = pos[31:16];
            assign col[g] = b[g*32 +: 32];

            wire [15:0] sx0 = {7'd0, sc_x0};
            wire [15:0] sx1 = {7'd0, sc_x1};
            wire [15:0] sy0 = {7'd0, sc_y0};
            wire [15:0] sy1 = {7'd0, sc_y1};

            wire inb  = (lx[g] < 16'd320) & (ly[g] < 16'd240);
            wire insc = (sx0 <= lx[g]) & (lx[g] < sx1) &
                        (sy0 <= ly[g]) & (ly[g] < sy1);

            assign en[g]    = tmask[g] & inb & insc;
            assign draww[g] = en[g] & act;
            assign drawp[g] = en[g] & pre;

            assign bk[g] = lx[g][1:0];

            wire [15:0] ymul = {8'd0, ly[g][7:0]} * 8'd80;
            assign ix[g] = ymul[14:0] + {8'd0, lx[g][8:2]};

            wire [15:0] d = (bk[g] == 2'd0) ? vw_rdata0 :
                            (bk[g] == 2'd1) ? vw_rdata1 :
                            (bk[g] == 2'd2) ? vw_rdata2 :
                                              vw_rdata3;

            wire [7:0] sa = col[g][31:24];
            wire [7:0] sr = col[g][23:16];
            wire [7:0] sg = col[g][15:8];
            wire [7:0] sb = col[g][7:0];

            wire [7:0] dr = {d[15:11], d[15:13]};
            wire [7:0] dg = {d[10:5],  d[10:9]};
            wire [7:0] db = {d[4:0],   d[4:2]};

            wire [7:0] fr = blend ? blend_ch(sr, dr, sa) : sr;
            wire [7:0] fg = blend ? blend_ch(sg, dg, sa) : sg;
            wire [7:0] fb = blend ? blend_ch(sb, db, sa) : sb;

            assign wd[g] = {fr[7:3], fg[7:2], fb[7:3]};
        end
    endgenerate

    // per-bank winner selection (highest-numbered lane wins)
    wire [3:0]  we_w;
    wire [14:0] wa_w [0:3];
    wire [15:0] wdo_w [0:3];
    wire [14:0] ra_w [0:3];

    genvar k;
    generate
        for (k = 0; k < 4; k = k + 1) begin : BANK
            wire [1:0] kk = k[1:0];
            wire h0w = draww[0] & (bk[0] == kk);
            wire h1w = draww[1] & (bk[1] == kk);
            wire h2w = draww[2] & (bk[2] == kk);
            wire h3w = draww[3] & (bk[3] == kk);
            wire [3:0] hitw = {h3w, h2w, h1w, h0w};

            assign we_w[k] = |hitw;
            assign wa_w[k] = hitw[3] ? ix[3] :
                             hitw[2] ? ix[2] :
                             hitw[1] ? ix[1] :
                             hitw[0] ? ix[0] : 15'd0;
            assign wdo_w[k] = hitw[3] ? wd[3] :
                              hitw[2] ? wd[2] :
                              hitw[1] ? wd[1] :
                              hitw[0] ? wd[0] : 16'd0;

            wire h0r = drawp[0] & (bk[0] == kk);
            wire h1r = drawp[1] & (bk[1] == kk);
            wire h2r = drawp[2] & (bk[2] == kk);
            wire h3r = drawp[3] & (bk[3] == kk);
            wire [3:0] hitr = {h3r, h2r, h1r, h0r};

            assign ra_w[k] = hitr[3] ? ix[3] :
                             hitr[2] ? ix[2] :
                             hitr[1] ? ix[1] :
                             hitr[0] ? ix[0] : 15'd0;
        end
    endgenerate

    assign r_we0    = we_w[0];
    assign r_we1    = we_w[1];
    assign r_we2    = we_w[2];
    assign r_we3    = we_w[3];
    assign r_waddr0 = wa_w[0];
    assign r_waddr1 = wa_w[1];
    assign r_waddr2 = wa_w[2];
    assign r_waddr3 = wa_w[3];
    assign r_wdata0 = wdo_w[0];
    assign r_wdata1 = wdo_w[1];
    assign r_wdata2 = wdo_w[2];
    assign r_wdata3 = wdo_w[3];
    assign r_raddr0 = ra_w[0];
    assign r_raddr1 = ra_w[1];
    assign r_raddr2 = ra_w[2];
    assign r_raddr3 = ra_w[3];

endmodule

module simt_gpu_core3__vram_mux (
    input running,
    input v_we0,
    input v_we1,
    input v_we2,
    input v_we3,
    input [14:0] v_waddr,
    input [15:0] v_wdata_lo,
    input [15:0] v_wdata_hi,
    input r_we0,
    input r_we1,
    input r_we2,
    input r_we3,
    input [14:0] r_waddr0,
    input [14:0] r_waddr1,
    input [14:0] r_waddr2,
    input [14:0] r_waddr3,
    input [15:0] r_wdata0,
    input [15:0] r_wdata1,
    input [15:0] r_wdata2,
    input [15:0] r_wdata3,
    output m_we0,
    output m_we1,
    output m_we2,
    output m_we3,
    output [14:0] m_waddr0,
    output [14:0] m_waddr1,
    output [14:0] m_waddr2,
    output [14:0] m_waddr3,
    output [15:0] m_wdata0,
    output [15:0] m_wdata1,
    output [15:0] m_wdata2,
    output [15:0] m_wdata3
);

    assign m_we0 = running ? r_we0 : v_we0;
    assign m_we1 = running ? r_we1 : v_we1;
    assign m_we2 = running ? r_we2 : v_we2;
    assign m_we3 = running ? r_we3 : v_we3;

    assign m_waddr0 = running ? r_waddr0 : v_waddr;
    assign m_waddr1 = running ? r_waddr1 : v_waddr;
    assign m_waddr2 = running ? r_waddr2 : v_waddr;
    assign m_waddr3 = running ? r_waddr3 : v_waddr;

    assign m_wdata0 = running ? r_wdata0 : v_wdata_lo;
    assign m_wdata1 = running ? r_wdata1 : v_wdata_hi;
    assign m_wdata2 = running ? r_wdata2 : v_wdata_lo;
    assign m_wdata3 = running ? r_wdata3 : v_wdata_hi;

endmodule

module simt_gpu_core3__raster_regs (
    input  wire         clk,
    input  wire         rst,
    input  wire         clear,
    input  wire         valid,
    input  wire         advance,
    input  wire         gfx,
    input  wire  [2:0]  gfx_op,
    input  wire  [3:0]  tmask,
    input  wire  [1:0]  wid,
    input  wire  [127:0] a,
    input  wire  [127:0] b,
    output wire  [31:0] ea0,
    output wire  [31:0] eb0,
    output wire  [31:0] ec0,
    output wire  [31:0] ea1,
    output wire  [31:0] eb1,
    output wire  [31:0] ec1,
    output wire  [31:0] ea2,
    output wire  [31:0] eb2,
    output wire  [31:0] ec2,
    output wire  [2:0]  bias,
    output wire  [9:0]  s_x,
    output wire  [9:0]  s_y,
    output wire         s_done
);

    reg [8:0]  x0, y0, x1, y1;
    reg [31:0] coef [0:8];
    reg [2:0]  bias_r;
    reg [9:0]  sx  [0:3];
    reg [9:0]  sy  [0:3];
    reg        sdone [0:3];

    assign ea0 = coef[0];
    assign eb0 = coef[1];
    assign ec0 = coef[2];
    assign ea1 = coef[3];
    assign eb1 = coef[4];
    assign ec1 = coef[5];
    assign ea2 = coef[6];
    assign eb2 = coef[7];
    assign ec2 = coef[8];
    assign bias = bias_r;

    assign s_x    = sx[wid];
    assign s_y    = sy[wid];
    assign s_done = sdone[wid];

    wire en = valid & advance & gfx & (tmask != 4'b0000);

    // lowest set lane of tmask
    integer l;
    always @* begin
        if (tmask[0])      l = 0;
        else if (tmask[1]) l = 1;
        else if (tmask[2]) l = 2;
        else               l = 3;
    end

    wire [31:0] n = a[l*32 +: 32];
    wire [31:0] v = b[l*32 +: 32];

    wire [8:0] v_x0 = v[8:0] & 9'h1FC; // bits 8:0 with bits 1:0 cleared
    wire [8:0] v_y0 = v[24:16];
    wire [8:0] v_x1 = v[8:0];
    wire [8:0] v_y1 = v[24:16];

    wire [9:0] nx = {v_x0[8:2], 2'b00};
    wire [9:0] ny = {2'b00, v_y0};
    wire [1:0] q  = ny[1:0];

    // rast step for warp wid
    wire        d0   = sdone[wid];
    wire [9:0]  sxw  = sx[wid];
    wire [9:0]  syw  = sy[wid];
    wire        wrap = (sxw + 10'd4) > {2'b00, x1};
    wire [9:0]  nsx  = wrap ? {2'b00, x0} : sxw + 10'd4;
    wire [9:0]  nsy  = wrap ? syw + 10'd4 : syw;
    wire        ndone = wrap ? ((syw + 10'd4) > {2'b00, y1}) : 1'b0;

    integer w;
    reg [9:0] rsy [0:3];
    reg       rdn [0:3];

    always @(posedge clk) begin
        if (rst | clear) begin
            x0 <= 9'd0; y0 <= 9'd0; x1 <= 9'd0; y1 <= 9'd0;
            bias_r <= 3'd0;
            for (w = 0; w < 9; w = w + 1)
                coef[w] <= 32'd0;
            for (w = 0; w < 4; w = w + 1) begin
                sx[w]    <= 10'd0;
                sy[w]    <= 10'd0;
                sdone[w] <= 1'b1;
            end
        end else if (en) begin
            if (gfx_op == 3'd0) begin
                case (n)
                    32'd8: begin
                        x0 <= v_x0;
                        y0 <= v_y0;
                        for (w = 0; w < 4; w = w + 1) begin
                            sx[w] <= nx;
                            sy[w] <= rsy[w];
                            sdone[w] <= rdn[w];
                        end
                    end
                    32'd9: begin
                        x1 <= v_x1;
                        y1 <= v_y1;
                    end
                    32'd16: coef[0] <= v;
                    32'd17: coef[1] <= v;
                    32'd18: coef[2] <= v;
                    32'd19: coef[3] <= v;
                    32'd20: coef[4] <= v;
                    32'd21: coef[5] <= v;
                    32'd22: coef[6] <= v;
                    32'd23: coef[7] <= v;
                    32'd24: coef[8] <= v;
                    32'd25: bias_r <= v[2:0];
                    default: ;
                endcase
            end else if (gfx_op == 3'd1) begin
                if (!d0) begin
                    sx[wid]    <= nsx;
                    sy[wid]    <= nsy;
                    sdone[wid] <= ndone;
                end
            end
        end
    end

    // compute restart scan values combinationally
    always @* begin
        for (w = 0; w < 4; w = w + 1) begin
            rsy[w] = ny - {8'd0, q} + w[9:0];
            if (w < q)
                rsy[w] = rsy[w] + 10'd4;
            rdn[w] = (rsy[w] > {2'b00, y1}) || (nx > {2'b00, x1});
        end
    end

endmodule

module simt_gpu_core3__raster_eval (
    input  wire        gfx,
    input  wire [2:0]  gfx_op,
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire [9:0]  s_x,
    input  wire [9:0]  s_y,
    input  wire        s_done,
    input  wire [31:0] ea0,
    input  wire [31:0] eb0,
    input  wire [31:0] ec0,
    input  wire [31:0] ea1,
    input  wire [31:0] eb1,
    input  wire [31:0] ec1,
    input  wire [31:0] ea2,
    input  wire [31:0] eb2,
    input  wire [31:0] ec2,
    input  wire [2:0]  bias,
    output wire [127:0] y
);
    genvar l;
    generate
        for (l = 0; l < 4; l = l + 1) begin : g_lane
            // rast.edge inputs
            wire [31:0] p  = a[32*l +: 32];
            wire [31:0] nb = b[32*l +: 32];
            wire [15:0] px = p[15:0];
            wire [15:0] py = p[31:16];
            wire [1:0]  n  = nb[1:0];

            // edge evaluation for rast.edge
            wire [31:0] e0 = ea0 * {16'd0, px} + eb0 * {16'd0, py} + ec0;
            wire [31:0] e1 = ea1 * {16'd0, px} + eb1 * {16'd0, py} + ec1;
            wire [31:0] e2 = ea2 * {16'd0, px} + eb2 * {16'd0, py} + ec2;
            reg [31:0] eval_e;
            always @* begin
                case (n)
                    2'd0: eval_e = e0;
                    2'd1: eval_e = e1;
                    2'd2: eval_e = e2;
                    default: eval_e = 32'd0;
                endcase
            end

            // rast coverage
            wire [9:0]  xl = s_x + l[9:0];
            wire [31:0] c0 = ea0 * {22'd0, xl} + eb0 * {22'd0, s_y} + ec0;
            wire [31:0] c1 = ea1 * {22'd0, xl} + eb1 * {22'd0, s_y} + ec1;
            wire [31:0] c2 = ea2 * {22'd0, xl} + eb2 * {22'd0, s_y} + ec2;
            wire signed [31:0] t0 = $signed(c0) + $signed({31'd0, bias[0]});
            wire signed [31:0] t1 = $signed(c1) + $signed({31'd0, bias[1]});
            wire signed [31:0] t2 = $signed(c2) + $signed({31'd0, bias[2]});
            wire covered = (t0 > 32'sd0) && (t1 > 32'sd0) && (t2 > 32'sd0);
            wire [31:0] rast_val = covered ? {6'd0, s_y, 6'd0, xl}
                                           : {16'hFFFF, 6'd0, xl};

            reg [31:0] lane;
            always @* begin
                if (!gfx)
                    lane = 32'd0;
                else if (gfx_op == 3'd1)
                    lane = s_done ? 32'hFFFFFFFF : rast_val;
                else if (gfx_op == 3'd3)
                    lane = eval_e;
                else
                    lane = 32'd0;
            end

            assign y[32*l +: 32] = lane;
        end
    endgenerate
endmodule

module simt_gpu_core3__gfx_sel (
    input gfx,
    input [127:0] alu_y,
    input [127:0] gfx_y,
    input [127:0] tex_y,
    input [127:0] z_y,
    output [127:0] y
);

    assign y = gfx ? (gfx_y | tex_y | z_y) : alu_y;

endmodule

module simt_gpu_core3__tex_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        clear,
    input  wire        valid,
    input  wire        advance,
    input  wire        gfx,
    input  wire [2:0]  gfx_op,
    input  wire [3:0]  tmask,
    input  wire [127:0] a,
    input  wire [127:0] b,
    output wire        g_busy,
    output reg  [2:0]  tex_mode
);

    reg pending;

    wire is_tex = valid & gfx & (gfx_op == 3'd4);

    assign g_busy = is_tex & ~pending;

    wire [1:0] cfg_lane = tmask[0] ? 2'd0 :
                          tmask[1] ? 2'd1 :
                          tmask[2] ? 2'd2 : 2'd3;
    wire       cfg_en   = valid & advance & gfx & (gfx_op == 3'd0) & (tmask != 4'b0000);
    wire [2:0] cfg_val  = tmask[0] ? b[2:0] :
                          tmask[1] ? b[34:32] :
                          tmask[2] ? b[66:64] : b[98:96];

    always @(posedge clk) begin
        if (rst | clear) begin
            pending  <= 1'b0;
            tex_mode <= 3'b000;
        end else begin
            if (advance)
                pending <= 1'b0;
            else if (is_tex)
                pending <= 1'b1;

            if (cfg_en & (a[cfg_lane*32 +: 32] == 32'd32))
                tex_mode <= cfg_val;
        end
    end

endmodule

module simt_gpu_core3__tex_host (
    input host_en,
    input host_we,
    input [31:0] host_addr,
    input [31:0] host_wdata,
    output t_we0,
    output t_we1,
    output t_we2,
    output t_we3,
    output [7:0] t_waddr,
    output [15:0] t_wdata_lo,
    output [15:0] t_wdata_hi
);

    wire hit = host_en & host_we &
               (host_addr >= 32'h5000_0000) &
               (host_addr <  32'h5000_0800);

    assign t_we0 = hit & ~host_addr[6];
    assign t_we1 = hit & ~host_addr[6];
    assign t_we2 = hit &  host_addr[6];
    assign t_we3 = hit &  host_addr[6];

    assign t_waddr = {host_addr[10:7], host_addr[5:2]};
    assign t_wdata_lo = host_wdata[15:0];
    assign t_wdata_hi = host_wdata[31:16];

endmodule

module simt_gpu_core3__tex_addr (
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire [2:0]   tex_mode,
    output wire [7:0]   ta00,
    output wire [7:0]   ta01,
    output wire [7:0]   ta02,
    output wire [7:0]   ta03,
    output wire [7:0]   ta10,
    output wire [7:0]   ta11,
    output wire [7:0]   ta12,
    output wire [7:0]   ta13,
    output wire [7:0]   ta20,
    output wire [7:0]   ta21,
    output wire [7:0]   ta22,
    output wire [7:0]   ta23,
    output wire [7:0]   ta30,
    output wire [7:0]   ta31,
    output wire [7:0]   ta32,
    output wire [7:0]   ta33
);
    wire [7:0] iu0, iv0, iu1, iv1, iu2, iv2, iu3, iv3;
    assign iu0 = a[15:8];  assign iv0 = b[15:8];
    assign iu1 = a[47:40]; assign iv1 = b[47:40];
    assign iu2 = a[79:72]; assign iv2 = b[79:72];
    assign iu3 = a[111:104]; assign iv3 = b[111:104];

    // wrap on u axis: repeat (tex_mode[1]==0) -> c mod 32; clamp -> min(c,31)
    // wrap on v axis: repeat (tex_mode[2]==0) -> c mod 32; clamp -> min(c,31)
    // c is 9 bits (0..256)
    function [4:0] wrap;
        input [8:0] c;
        input rep;
        reg [8:0] cc;
        begin
            cc = c;
            if (rep)
                wrap = cc[4:0];
            else
                wrap = (cc > 9'd31) ? 5'd31 : cc[4:0];
        end
    endfunction

    wire [4:0] x0_0, x1_0, y0_0, y1_0;
    wire [4:0] x0_1, x1_1, y0_1, y1_1;
    wire [4:0] x0_2, x1_2, y0_2, y1_2;
    wire [4:0] x0_3, x1_3, y0_3, y1_3;

    assign x0_0 = wrap({1'b0, iu0}, ~tex_mode[1]); assign x1_0 = wrap({1'b0, iu0} + 9'd1, ~tex_mode[1]);
    assign y0_0 = wrap({1'b0, iv0}, ~tex_mode[2]); assign y1_0 = wrap({1'b0, iv0} + 9'd1, ~tex_mode[2]);
    assign x0_1 = wrap({1'b0, iu1}, ~tex_mode[1]); assign x1_1 = wrap({1'b0, iu1} + 9'd1, ~tex_mode[1]);
    assign y0_1 = wrap({1'b0, iv1}, ~tex_mode[2]); assign y1_1 = wrap({1'b0, iv1} + 9'd1, ~tex_mode[2]);
    assign x0_2 = wrap({1'b0, iu2}, ~tex_mode[1]); assign x1_2 = wrap({1'b0, iu2} + 9'd1, ~tex_mode[1]);
    assign y0_2 = wrap({1'b0, iv2}, ~tex_mode[2]); assign y1_2 = wrap({1'b0, iv2} + 9'd1, ~tex_mode[2]);
    assign x0_3 = wrap({1'b0, iu3}, ~tex_mode[1]); assign x1_3 = wrap({1'b0, iu3} + 9'd1, ~tex_mode[1]);
    assign y0_3 = wrap({1'b0, iv3}, ~tex_mode[2]); assign y1_3 = wrap({1'b0, iv3} + 9'd1, ~tex_mode[2]);

    // bank k = py*2 + px: xk = (x0 mod 2 == px) ? x0 : x1, yk likewise
    // ta = (yk>>1)*16 + (xk>>1) = {yk[4:1], xk[4:1]}
    wire [4:0] xa0_0 = x0_0[0] ? x1_0 : x0_0; // px=0: use x0 only if x0 even
    wire [4:0] xa1_0 = x0_0[0] ? x0_0 : x1_0; // px=1
    wire [4:0] ya0_0 = y0_0[0] ? y1_0 : y0_0; // py=0
    wire [4:0] ya1_0 = y0_0[0] ? y0_0 : y1_0; // py=1
    assign ta00 = {ya0_0[4:1], xa0_0[4:1]}; // py=0, px=0
    assign ta01 = {ya0_0[4:1], xa1_0[4:1]}; // py=0, px=1
    assign ta02 = {ya1_0[4:1], xa0_0[4:1]}; // py=1, px=0
    assign ta03 = {ya1_0[4:1], xa1_0[4:1]}; // py=1, px=1

    wire [4:0] xa0_1 = x0_1[0] ? x1_1 : x0_1;
    wire [4:0] xa1_1 = x0_1[0] ? x0_1 : x1_1;
    wire [4:0] ya0_1 = y0_1[0] ? y1_1 : y0_1;
    wire [4:0] ya1_1 = y0_1[0] ? y0_1 : y1_1;
    assign ta10 = {ya0_1[4:1], xa0_1[4:1]};
    assign ta11 = {ya0_1[4:1], xa1_1[4:1]};
    assign ta12 = {ya1_1[4:1], xa0_1[4:1]};
    assign ta13 = {ya1_1[4:1], xa1_1[4:1]};

    wire [4:0] xa0_2 = x0_2[0] ? x1_2 : x0_2;
    wire [4:0] xa1_2 = x0_2[0] ? x0_2 : x1_2;
    wire [4:0] ya0_2 = y0_2[0] ? y1_2 : y0_2;
    wire [4:0] ya1_2 = y0_2[0] ? y0_2 : y1_2;
    assign ta20 = {ya0_2[4:1], xa0_2[4:1]};
    assign ta21 = {ya0_2[4:1], xa1_2[4:1]};
    assign ta22 = {ya1_2[4:1], xa0_2[4:1]};
    assign ta23 = {ya1_2[4:1], xa1_2[4:1]};

    wire [4:0] xa0_3 = x0_3[0] ? x1_3 : x0_3;
    wire [4:0] xa1_3 = x0_3[0] ? x0_3 : x1_3;
    wire [4:0] ya0_3 = y0_3[0] ? y1_3 : y0_3;
    wire [4:0] ya1_3 = y0_3[0] ? y0_3 : y1_3;
    assign ta30 = {ya0_3[4:1], xa0_3[4:1]};
    assign ta31 = {ya0_3[4:1], xa1_3[4:1]};
    assign ta32 = {ya1_3[4:1], xa0_3[4:1]};
    assign ta33 = {ya1_3[4:1], xa1_3[4:1]};
endmodule

module simt_gpu_core3__tex_filter (
    input  wire        gfx,
    input  wire  [2:0] gfx_op,
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire  [2:0] tex_mode,
    input  wire [15:0] t00,
    input  wire [15:0] t01,
    input  wire [15:0] t02,
    input  wire [15:0] t03,
    input  wire [15:0] t10,
    input  wire [15:0] t11,
    input  wire [15:0] t12,
    input  wire [15:0] t13,
    input  wire [15:0] t20,
    input  wire [15:0] t21,
    input  wire [15:0] t22,
    input  wire [15:0] t23,
    input  wire [15:0] t30,
    input  wire [15:0] t31,
    input  wire [15:0] t32,
    input  wire [15:0] t33,
    output wire [127:0] tex_y
);
    genvar l;
    generate
        for (l = 0; l < 4; l = l + 1) begin : g_lane
            wire [31:0] u = a[32*l +: 32];
            wire [31:0] v = b[32*l +: 32];

            wire [7:0] iu = u[15:8];
            wire [7:0] iv = v[15:8];
            wire [7:0] fu = u[7:0];
            wire [7:0] fv = v[7:0];

            // wrap
            wire [8:0] iu_p1 = {1'b0, iu} + 9'd1;
            wire [8:0] iv_p1 = {1'b0, iv} + 9'd1;

            wire [4:0] x0 = tex_mode[1] ? ((iu > 8'd31) ? 5'd31 : iu[4:0])
                                        : iu[4:0];
            wire [4:0] x1 = tex_mode[1] ? ((iu_p1 > 9'd31) ? 5'd31 : iu_p1[4:0])
                                        : iu_p1[4:0];
            wire [4:0] y0 = tex_mode[2] ? ((iv > 8'd31) ? 5'd31 : iv[4:0])
                                        : iv[4:0];
            wire [4:0] y1 = tex_mode[2] ? ((iv_p1 > 9'd31) ? 5'd31 : iv_p1[4:0])
                                        : iv_p1[4:0];

            // texel select: k = (y mod 2)*2 + (x mod 2)
            wire [15:0] t0 = (l == 2'd0) ? ((y0[0] ? (x0[0] ? t03 : t02)
                                                   : (x0[0] ? t01 : t00))) :
                             (l == 2'd1) ? ((y0[0] ? (x0[0] ? t13 : t12)
                                                   : (x0[0] ? t11 : t10))) :
                             (l == 2'd2) ? ((y0[0] ? (x0[0] ? t23 : t22)
                                                   : (x0[0] ? t21 : t20))) :
                                           ((y0[0] ? (x0[0] ? t33 : t32)
                                                   : (x0[0] ? t31 : t30)));
            wire [15:0] t1 = (l == 2'd0) ? ((y0[0] ? (x1[0] ? t03 : t02)
                                                   : (x1[0] ? t01 : t00))) :
                             (l == 2'd1) ? ((y0[0] ? (x1[0] ? t13 : t12)
                                                   : (x1[0] ? t11 : t10))) :
                             (l == 2'd2) ? ((y0[0] ? (x1[0] ? t23 : t22)
                                                   : (x1[0] ? t21 : t20))) :
                                           ((y0[0] ? (x1[0] ? t33 : t32)
                                                   : (x1[0] ? t31 : t30)));
            wire [15:0] t2 = (l == 2'd0) ? ((y1[0] ? (x0[0] ? t03 : t02)
                                                   : (x0[0] ? t01 : t00))) :
                             (l == 2'd1) ? ((y1[0] ? (x0[0] ? t13 : t12)
                                                   : (x0[0] ? t11 : t10))) :
                             (l == 2'd2) ? ((y1[0] ? (x0[0] ? t23 : t22)
                                                   : (x0[0] ? t21 : t20))) :
                                           ((y1[0] ? (x0[0] ? t33 : t32)
                                                   : (x0[0] ? t31 : t30)));
            wire [15:0] t3 = (l == 2'd0) ? ((y1[0] ? (x1[0] ? t03 : t02)
                                                   : (x1[0] ? t01 : t00))) :
                             (l == 2'd1) ? ((y1[0] ? (x1[0] ? t13 : t12)
                                                   : (x1[0] ? t11 : t10))) :
                             (l == 2'd2) ? ((y1[0] ? (x1[0] ? t23 : t22)
                                                   : (x1[0] ? t21 : t20))) :
                                           ((y1[0] ? (x1[0] ? t33 : t32)
                                                   : (x1[0] ? t31 : t30)));

            // widen RGB565 -> RGB888: r8 = r5<<3 | r5>>2, g8 = g6<<2 | g6>>4
            function [7:0] widen5;
                input [4:0] c;
                widen5 = {c, 3'b000} | {5'b00000, c[4:2]};
            endfunction
            function [7:0] widen6;
                input [5:0] c;
                widen6 = {c, 2'b00} | {6'b000000, c[5:4]};
            endfunction

            wire [7:0] r00 = widen5(t0[15:11]);
            wire [7:0] g00 = widen6(t0[10:5]);
            wire [7:0] b00 = widen5(t0[4:0]);
            wire [7:0] r10 = widen5(t1[15:11]);
            wire [7:0] g10 = widen6(t1[10:5]);
            wire [7:0] b10 = widen5(t1[4:0]);
            wire [7:0] r01 = widen5(t2[15:11]);
            wire [7:0] g01 = widen6(t2[10:5]);
            wire [7:0] b01 = widen5(t2[4:0]);
            wire [7:0] r11 = widen5(t3[15:11]);
            wire [7:0] g11 = widen6(t3[10:5]);
            wire [7:0] b11 = widen5(t3[4:0]);

            // bilinear
            wire [17:0] wu = {10'd0, fu};
            wire [17:0] wv = {10'd0, fv};
            wire [17:0] wu_i = 18'd256 - wu;
            wire [17:0] wv_i = 18'd256 - wv;

            function [7:0] bl;
                input [7:0] c00, c10, c01, c11;
                input [17:0] wu, wv, wu_i, wv_i;
                reg [33:0] acc;
                begin
                    acc = c00 * wu_i * wv_i + c10 * wu * wv_i
                        + c01 * wu_i * wv  + c11 * wu * wv
                        + 34'd32768;
                    bl = acc[23:16];
                end
            endfunction

            wire [7:0] r_b = bl(r00, r10, r01, r11, wu, wv, wu_i, wv_i);
            wire [7:0] g_b = bl(g00, g10, g01, g11, wu, wv, wu_i, wv_i);
            wire [7:0] b_b = bl(b00, b10, b01, b11, wu, wv, wu_i, wv_i);

            wire [7:0] r_o = tex_mode[0] ? r_b : r00;
            wire [7:0] g_o = tex_mode[0] ? g_b : g00;
            wire [7:0] b_o = tex_mode[0] ? b_b : b00;

            wire tex_en = gfx && (gfx_op == 3'd4);

            assign tex_y[32*l +: 32] = tex_en ? {8'hFF, r_o, g_o, b_o} : 32'd0;
        end
    endgenerate
endmodule

module simt_gpu_core3__rop_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        clear,
    input  wire        valid,
    input  wire        advance,
    input  wire        gfx,
    input  wire [2:0]  gfx_op,
    input  wire [3:0]  tmask,
    input  wire [127:0] a,
    input  wire [127:0] b,
    input  wire        tex_busy,
    output wire        g_busy,
    output wire        blend
);

    reg blend_r;
    reg pending;

    assign blend = blend_r;
    assign g_busy = tex_busy | (valid & gfx & (gfx_op == 3'd5) & blend_r & ~pending);

    integer l;
    reg cfg_hit;
    reg [31:0] lane_a;
    reg [31:0] lane_b;

    always @* begin
        cfg_hit = 1'b0;
        lane_a = 32'd0;
        lane_b = 32'd0;
        for (l = 0; l < 4; l = l + 1) begin
            if (!cfg_hit && tmask[l]) begin
                cfg_hit = 1'b1;
                lane_a = a[32*l +: 32];
                lane_b = b[32*l +: 32];
            end
        end
    end

    always @(posedge clk) begin
        if (rst | clear) begin
            blend_r <= 1'b0;
            pending <= 1'b0;
        end else begin
            if (advance)
                pending <= 1'b0;
            else if (valid & gfx & (gfx_op == 3'd5) & blend_r)
                pending <= 1'b1;

            if (valid & advance & gfx & (gfx_op == 3'd0) & (tmask != 4'd0) & cfg_hit
                & (lane_a == 32'd4))
                blend_r <= lane_b[0];
        end
    end

endmodule

module simt_gpu_core3__vram_rmux (
    input running,
    input [14:0] vw_raddr,
    input [14:0] r_raddr0,
    input [14:0] r_raddr1,
    input [14:0] r_raddr2,
    input [14:0] r_raddr3,
    output [14:0] m_raddr0,
    output [14:0] m_raddr1,
    output [14:0] m_raddr2,
    output [14:0] m_raddr3
);

    assign m_raddr0 = running ? r_raddr0 : vw_raddr;
    assign m_raddr1 = running ? r_raddr1 : vw_raddr;
    assign m_raddr2 = running ? r_raddr2 : vw_raddr;
    assign m_raddr3 = running ? r_raddr3 : vw_raddr;

endmodule

module simt_gpu_core3__z_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       clear,
    input  wire       valid,
    input  wire       advance,
    input  wire       gfx,
    input  wire [2:0] gfx_op,
    input  wire       in_busy,
    output wire       g_busy
);

    reg pending;

    assign g_busy = in_busy | (valid & gfx & (gfx_op == 3'd6) & !pending);

    always @(posedge clk) begin
        if (rst | clear)
            pending <= 1'b0;
        else if (advance)
            pending <= 1'b0;
        else if (valid & gfx & (gfx_op == 3'd6))
            pending <= 1'b1;
    end

endmodule

module simt_gpu_core3__z_unit (
    input  wire         valid,
    input  wire         advance,
    input  wire         gfx,
    input  wire  [2:0]  gfx_op,
    input  wire  [3:0]  tmask,
    input  wire  [127:0] a,
    input  wire  [127:0] b,
    input  wire  [15:0] z_rdata0,
    input  wire  [15:0] z_rdata1,
    input  wire  [15:0] z_rdata2,
    input  wire  [15:0] z_rdata3,
    output wire  [14:0] z_raddr0,
    output wire  [14:0] z_raddr1,
    output wire  [14:0] z_raddr2,
    output wire  [14:0] z_raddr3,
    output wire         zw_we0,
    output wire         zw_we1,
    output wire         zw_we2,
    output wire         zw_we3,
    output wire  [14:0] zw_waddr0,
    output wire  [14:0] zw_waddr1,
    output wire  [14:0] zw_waddr2,
    output wire  [14:0] zw_waddr3,
    output wire  [15:0] zw_wdata0,
    output wire  [15:0] zw_wdata1,
    output wire  [15:0] zw_wdata2,
    output wire  [15:0] zw_wdata3,
    output wire  [127:0] z_y
);
    wire active = gfx & (gfx_op == 3'd6);

    // per-lane signals
    wire [15:0] x0 = a[15:0];    wire [15:0] y0 = a[31:16];   wire [15:0] z0 = b[15:0];
    wire [15:0] x1 = a[47:32];   wire [15:0] y1 = a[63:48];   wire [15:0] z1 = b[47:32];
    wire [15:0] x2 = a[79:64];   wire [15:0] y2 = a[95:80];   wire [15:0] z2 = b[79:64];
    wire [15:0] x3 = a[111:96];  wire [15:0] y3 = a[127:112]; wire [15:0] z3 = b[111:96];

    wire test0 = active & tmask[0] & (x0 < 16'd320) & (y0 < 16'd240);
    wire test1 = active & tmask[1] & (x1 < 16'd320) & (y1 < 16'd240);
    wire test2 = active & tmask[2] & (x2 < 16'd320) & (y2 < 16'd240);
    wire test3 = active & tmask[3] & (x3 < 16'd320) & (y3 < 16'd240);

    wire [1:0] bank0 = x0[1:0];
    wire [1:0] bank1 = x1[1:0];
    wire [1:0] bank2 = x2[1:0];
    wire [1:0] bank3 = x3[1:0];

    wire [26:0] full0 = y0[14:0] * 15'd80 + {13'd0, x0[15:2]};
    wire [26:0] full1 = y1[14:0] * 15'd80 + {13'd0, x1[15:2]};
    wire [26:0] full2 = y2[14:0] * 15'd80 + {13'd0, x2[15:2]};
    wire [26:0] full3 = y3[14:0] * 15'd80 + {13'd0, x3[15:2]};
    wire [14:0] idx0 = full0[14:0];
    wire [14:0] idx1 = full1[14:0];
    wire [14:0] idx2 = full2[14:0];
    wire [14:0] idx3 = full3[14:0];

    // winner per bank: priority lane 3 > 2 > 1 > 0
    // winner_sel[k][l]: lane l is bank k's winner
    wire [3:0] w0, w1, w2, w3; // w[k][l]
    assign w0[0] = test0 & (bank0 == 2'd0);
    assign w0[1] = test1 & (bank1 == 2'd0);
    assign w0[2] = test2 & (bank2 == 2'd0);
    assign w0[3] = test3 & (bank3 == 2'd0);
    assign w1[0] = test0 & (bank0 == 2'd1);
    assign w1[1] = test1 & (bank1 == 2'd1);
    assign w1[2] = test2 & (bank2 == 2'd1);
    assign w1[3] = test3 & (bank3 == 2'd1);
    assign w2[0] = test0 & (bank0 == 2'd2);
    assign w2[1] = test1 & (bank1 == 2'd2);
    assign w2[2] = test2 & (bank2 == 2'd2);
    assign w2[3] = test3 & (bank3 == 2'd2);
    assign w3[0] = test0 & (bank0 == 2'd3);
    assign w3[1] = test1 & (bank1 == 2'd3);
    assign w3[2] = test2 & (bank2 == 2'd3);
    assign w3[3] = test3 & (bank3 == 2'd3);

    // winner lane per bank (one-hot), priority 3,2,1,0
    wire [3:0] win0 = w0[3] ? 4'b1000 : w0[2] ? 4'b0100 : w0[1] ? 4'b0010 : w0[0] ? 4'b0001 : 4'b0000;
    wire [3:0] win1 = w1[3] ? 4'b1000 : w1[2] ? 4'b0100 : w1[1] ? 4'b0010 : w1[0] ? 4'b0001 : 4'b0000;
    wire [3:0] win2 = w2[3] ? 4'b1000 : w2[2] ? 4'b0100 : w2[1] ? 4'b0010 : w2[0] ? 4'b0001 : 4'b0000;
    wire [3:0] win3 = w3[3] ? 4'b1000 : w3[2] ? 4'b0100 : w3[1] ? 4'b0010 : w3[0] ? 4'b0001 : 4'b0000;

    wire any0 = |w0, any1 = |w1, any2 = |w2, any3 = |w3;

    // winner index / z per bank
    wire [14:0] widx0 = win0[3] ? idx3 : win0[2] ? idx2 : win0[1] ? idx1 : idx0;
    wire [14:0] widx1 = win1[3] ? idx3 : win1[2] ? idx2 : win1[1] ? idx1 : idx0;
    wire [14:0] widx2 = win2[3] ? idx3 : win2[2] ? idx2 : win2[1] ? idx1 : idx0;
    wire [14:0] widx3 = win3[3] ? idx3 : win3[2] ? idx2 : win3[1] ? idx1 : idx0;

    wire [15:0] wz0 = win0[3] ? z3 : win0[2] ? z2 : win0[1] ? z1 : z0;
    wire [15:0] wz1 = win1[3] ? z3 : win1[2] ? z2 : win1[1] ? z1 : z0;
    wire [15:0] wz2 = win2[3] ? z3 : win2[2] ? z2 : win2[1] ? z1 : z0;
    wire [15:0] wz3 = win3[3] ? z3 : win3[2] ? z2 : win3[1] ? z1 : z0;

    assign z_raddr0 = (valid & any0) ? widx0 : 15'd0;
    assign z_raddr1 = (valid & any1) ? widx1 : 15'd0;
    assign z_raddr2 = (valid & any2) ? widx2 : 15'd0;
    assign z_raddr3 = (valid & any3) ? widx3 : 15'd0;

    wire pass0 = any0 & (wz0 < z_rdata0);
    wire pass1 = any1 & (wz1 < z_rdata1);
    wire pass2 = any2 & (wz2 < z_rdata2);
    wire pass3 = any3 & (wz3 < z_rdata3);

    wire wr = valid & advance;

    assign zw_we0 = wr & pass0;
    assign zw_we1 = wr & pass1;
    assign zw_we2 = wr & pass2;
    assign zw_we3 = wr & pass3;

    assign zw_waddr0 = wr ? widx0 : 15'd0;
    assign zw_waddr1 = wr ? widx1 : 15'd0;
    assign zw_waddr2 = wr ? widx2 : 15'd0;
    assign zw_waddr3 = wr ? widx3 : 15'd0;

    assign zw_wdata0 = wr ? wz0 : 16'd0;
    assign zw_wdata1 = wr ? wz1 : 16'd0;
    assign zw_wdata2 = wr ? wz2 : 16'd0;
    assign zw_wdata3 = wr ? wz3 : 16'd0;

    // passing winner per lane
    wire p0 = (win0[0] & pass0) | (win1[0] & pass1) | (win2[0] & pass2) | (win3[0] & pass3);
    wire p1 = (win0[1] & pass0) | (win1[1] & pass1) | (win2[1] & pass2) | (win3[1] & pass3);
    wire p2 = (win0[2] & pass0) | (win1[2] & pass1) | (win2[2] & pass2) | (win3[2] & pass3);
    wire p3 = (win0[3] & pass0) | (win1[3] & pass1) | (win2[3] & pass2) | (win3[3] & pass3);

    assign z_y = {{32{p3}}, {32{p2}}, {32{p1}}, {32{p0}}};
endmodule

module simt_gpu_core3__z_host (
    input  wire        host_en,
    input  wire        host_we,
    input  wire [31:0] host_addr,
    input  wire [31:0] host_wdata,
    output wire        zh_we0,
    output wire        zh_we1,
    output wire        zh_we2,
    output wire        zh_we3,
    output wire [14:0] zh_waddr,
    output wire [15:0] zh_wdata_lo,
    output wire [15:0] zh_wdata_hi
);

    wire hit = host_en & host_we &
               (host_addr >= 32'h4004_0000) &
               (host_addr <  32'h4006_5800);

    assign zh_we0 = hit & ~host_addr[2];
    assign zh_we1 = hit & ~host_addr[2];
    assign zh_we2 = hit &  host_addr[2];
    assign zh_we3 = hit &  host_addr[2];

    assign zh_waddr    = host_addr[17:3];
    assign zh_wdata_lo = host_wdata[15:0];
    assign zh_wdata_hi = host_wdata[31:16];

endmodule

module simt_gpu_core3__z_mux (
    input running,
    input zh_we0,
    input zh_we1,
    input zh_we2,
    input zh_we3,
    input [14:0] zh_waddr,
    input [15:0] zh_wdata_lo,
    input [15:0] zh_wdata_hi,
    input zw_we0,
    input zw_we1,
    input zw_we2,
    input zw_we3,
    input [14:0] zw_waddr0,
    input [14:0] zw_waddr1,
    input [14:0] zw_waddr2,
    input [14:0] zw_waddr3,
    input [15:0] zw_wdata0,
    input [15:0] zw_wdata1,
    input [15:0] zw_wdata2,
    input [15:0] zw_wdata3,
    output mz_we0,
    output mz_we1,
    output mz_we2,
    output mz_we3,
    output [14:0] mz_waddr0,
    output [14:0] mz_waddr1,
    output [14:0] mz_waddr2,
    output [14:0] mz_waddr3,
    output [15:0] mz_wdata0,
    output [15:0] mz_wdata1,
    output [15:0] mz_wdata2,
    output [15:0] mz_wdata3
);

    assign mz_we0 = running ? zw_we0 : zh_we0;
    assign mz_we1 = running ? zw_we1 : zh_we1;
    assign mz_we2 = running ? zw_we2 : zh_we2;
    assign mz_we3 = running ? zw_we3 : zh_we3;

    assign mz_waddr0 = running ? zw_waddr0 : zh_waddr;
    assign mz_waddr1 = running ? zw_waddr1 : zh_waddr;
    assign mz_waddr2 = running ? zw_waddr2 : zh_waddr;
    assign mz_waddr3 = running ? zw_waddr3 : zh_waddr;

    assign mz_wdata0 = running ? zw_wdata0 : zh_wdata_lo;
    assign mz_wdata1 = running ? zw_wdata1 : zh_wdata_hi;
    assign mz_wdata2 = running ? zw_wdata2 : zh_wdata_lo;
    assign mz_wdata3 = running ? zw_wdata3 : zh_wdata_hi;

endmodule

module simt_gpu_core3__vwbank0 (
    input  wire        clk,
    input  wire        we,
    input  wire [14:0] waddr,
    input  wire [15:0] wdata,
    input  wire [14:0] raddr,
    output reg  [15:0] rdata
);

    reg [15:0] mem [0:19199];
    integer i;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
    end

    wire wsel = (waddr < 15'd19200);
    wire rsel = (raddr < 15'd19200);

    always @(posedge clk) begin
        if (we && wsel)
            mem[waddr] <= wdata;
        rdata <= rsel ? mem[raddr] : 16'd0;
    end

endmodule

module simt_gpu_core3__vwbank1 (
    input  wire        clk,
    input  wire        we,
    input  wire [14:0] waddr,
    input  wire [15:0] wdata,
    input  wire [14:0] raddr,
    output wire [15:0] rdata
);

    reg [15:0] mem [0:19199];
    reg [15:0] rdata_reg;
    integer i;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
        rdata_reg = 16'd0;
    end

    wire wsel = (waddr < 15'd19200);
    wire rsel = (raddr < 15'd19200);

    always @(posedge clk) begin
        if (we && wsel)
            mem[waddr] <= wdata;
        if (we && wsel && (raddr == waddr))
            rdata_reg <= mem[waddr];      // old contents
        else if (rsel)
            rdata_reg <= mem[raddr];
        else
            rdata_reg <= 16'd0;           // don't-care
    end

    assign rdata = rdata_reg;

endmodule

module simt_gpu_core3__vwbank2 (
    input wire clk,
    input wire we,
    input wire [14:0] waddr,
    input wire [15:0] wdata,
    input wire [14:0] raddr,
    output reg [15:0] rdata
);
    localparam DEPTH = 19200;

    reg [15:0] mem [0:DEPTH-1];
    wire [14:0] rindex;
    integer i;

    assign rindex = (raddr < 15'd19200) ? raddr : 15'd0;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = 16'd0;
        rdata = 16'd0;
    end

    always @(posedge clk) begin
        rdata <= mem[rindex];
        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
    end
endmodule

module simt_gpu_core3__vwbank3 (
    input clk,
    input we,
    input [14:0] waddr,
    input [15:0] wdata,
    input [14:0] raddr,
    output reg [15:0] rdata
);
    reg [15:0] mem [0:19199];
    integer i;
    wire [15:0] rdata_next;

    initial begin
        for (i = 0; i < 19200; i = i + 1) begin
            mem[i] = 16'h0000;
        end
        rdata = 16'h0000;
    end

    assign rdata_next = (raddr < 15'd19200) ? mem[raddr] : 16'h0000;

    always @(posedge clk) begin
        if (we && (waddr < 15'd19200)) begin
            mem[waddr] <= wdata;
        end
        rdata <= rdata_next;
    end
endmodule

module simt_gpu_core3__vdbank0 (
    input  wire        clk,
    input  wire        we,
    input  wire [14:0] waddr,
    input  wire [15:0] wdata,
    input  wire [14:0] raddr,
    output wire [15:0] rdata
);

    reg [15:0] mem [0:19199];
    reg [15:0] rdata_reg;

    integer i;
    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
        rdata_reg = 16'd0;
    end

    wire wsel = (waddr < 15'd19200);
    wire rsel = (raddr < 15'd19200);

    always @(posedge clk) begin
        if (we && wsel)
            mem[waddr] <= wdata;
        rdata_reg <= rsel ? mem[raddr] : 16'd0;
    end

    assign rdata = rdata_reg;

endmodule

module simt_gpu_core3__vdbank1 (
    input clk,
    input we,
    input [14:0] waddr,
    input [15:0] wdata,
    input [14:0] raddr,
    output reg [15:0] rdata
);

    reg [15:0] mem [0:19199];
    integer i;

    wire [14:0] rindex;
    wire [15:0] rdata_next;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
    end

    assign rindex = (raddr < 15'd19200) ? raddr : 15'd0;
    assign rdata_next = (raddr < 15'd19200) ? mem[rindex] : 16'd0;

    always @(posedge clk) begin
        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
        rdata <= rdata_next;
    end

endmodule

module simt_gpu_core3__vdbank2 (
    input wire clk,
    input wire we,
    input wire [14:0] waddr,
    input wire [15:0] wdata,
    input wire [14:0] raddr,
    output reg [15:0] rdata
);

    reg [15:0] mem [0:19199];
    integer i;

    initial begin
        for (i = 0; i < 19200; i = i + 1)
            mem[i] = 16'd0;
    end

    always @(posedge clk) begin
        rdata <= (raddr < 15'd19200) ? mem[raddr] : 16'd0;
        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
    end

endmodule

module simt_gpu_core3__vdbank3 (
    input clk,
    input we,
    input [14:0] waddr,
    input [15:0] wdata,
    input [14:0] raddr,
    output reg [15:0] rdata
);
    localparam integer DEPTH = 19200;

    reg [15:0] mem [0:DEPTH-1];
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = 16'd0;
        rdata = 16'd0;
    end

    always @(posedge clk) begin
        if (raddr < 15'd19200)
            rdata <= mem[raddr];
        else
            rdata <= 16'd0;

        if (we && (waddr < 15'd19200))
            mem[waddr] <= wdata;
    end
endmodule

module simt_gpu_core3__tbank00 (
